(window.GIM_TS=window.GIM_TS||{})["Pesachim.2"]={"from":48,"a":[["\u0003ורבא אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' יהודה\u0004 לעשות את \u0003שאין מתכוין כמתכוין — אלא ל\u0004ענין \u0003חומרה\u0004 שאין העדר הכוונה פוגם במעשה, \u0003אבל\u0004 שיחשוב \u0003מתכוין כשאין מתכוין לקולא — לא.\u0004","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 ומוצא מקור לשיטתי זו — \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמרו עליו על רבן יוחנן בן זכאי שהיה יושב\u0004 ברחוב הסמוך להר הבית \u0003בצילו של היכל, ודורש\u0004 למנין רב של אנשים \u0003כל היום כולו. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003לא אפשר\u0004 היה לנהוג אחרת, כי לא היה מקום אחר שיחזיק כה הרבה אנשים, \u0003ו\u0004בודאי היה \u0003מיכוין\u0004 \u0005[מתכוון]\u0006 ליהנות מצילו של היכל, \u0003ושרי\u0004 \u0005[ומותר].\u0006 הרי שלא אפשר ומתכוין — מותר.","\u0003ורבא אמר\u0004 בתשובה לכך \u0003: שאני\u0004 \u0005[שונה]\u0006 \u0003היכל\u0004 ש\u0003לתוכו\u0004 הוא \u0003עשוי,\u0004 שאיסור ההנאה מן ההיכל הוא רק בצידו הפנימי שלשמו נעשה, אבל מחוצה לו אין כאן איסור כלל.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את דעתי זו, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לולין\u0004 (פתחים כעין ארובות) \u0003היו פתוחין בעליית בית קדשי הקדשים, שבהן\u0004 (דרכם) \u0003משלשלין את האומנים\u0004 (בעלי המלאכה) \u0003בתיבות\u0004 אל תוך בית קודשי הקודשים, \u0003כדי שלא יזונו עיניהם\u0004 ויהנו ממראה בית קדשי הקודשים בשעה שהם עושים שם תיקונים. \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003לא אפשר\u0004 אחרת, שהרי הכרחי מפעם בפעם לתקן את בית קודשי הקודשים, וגם אי אפשר לתקנו מבלי להיכנס לתוכו, \u0003ו\u0004כיון שייתכן ש\u0003קא מיכוין\u0004 \u0005[שמתכוון]\u0006 האומן ליהנות מהמראה — \u0003ואסור.\u0004","ודוחים: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 כן, שאפשר להביא ראיה מכאן?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' שמעון בן פזי אמר\u0004 בשם \u0003ר' יהושע בן לוי משום\u0004 (משמו של) \u0003בר קפרא: קול\u0004 כלי השיר שבמקדש \u0003ומראה וריח\u0004 הקטורת \u0003אין בהן משום מעילה!\u0004 כי האיסור ליהנות מדבר של קודש נאמר רק על שימוש שיש בו ממש. \u0003אלא, מעלה עשו בבית קדשי הקדשים\u0004 משום קדושתו היתירה שלא יביטו בו, ואין ללמוד מכאן הלכה כללית,","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 זאת בלשון אחרת, ש\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את דעתי זו? \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' שמעון בן פזי אמר\u0004 בשם \u0003ר' יהושע בן לוי משום\u0004 (משמו של) \u0003בר קפרא: קול ומראה וריח אין בהם משום מעילה.\u0004 משמע: \u0003מעילה\u0004 מן התורה — \u0003הוא דליכא\u0004 \u0005[שאין כאן],\u0006 \u0003הא איסורא\u0004 \u0005[אבל איסור]\u0006 מדברי סופרים — \u0003איכא\u0004 \u0005[יש כאן].\u0006","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא \u0003לאותן העומדין בפנים\u0004 בתוך ההיכל ש\u0003לא אפשר\u0004 שלא יגיע אליהם הקול או יראו מראה או יריחו ריח הקטורת, \u0003וקא מיכוין\u0004 \u0005[והוא מתכוון]\u0006 ליהנות — \u0003ואסור!\u0004 ודוחים: \u0003לא,\u0004 המדובר הוא כאן \u0003לאותן העומדין בחוץ,\u0004 שכיון שאינם חייבים להיות שם באותה שעה, הרי זה \"אפשר ומתכוין\", שלכל הדעות אסור.","כיון שהובאה הלכה זו דנים בה עתה ל \u0003גופא\u0004 \u0005[לעצמה].\u0006 \u0003אמר ר' שמעון בן פזי אמר\u0004 בשם \u0003ר' יהושע בן לוי משום\u0004 (משמו של) \u0003בר קפרא: קול ומראה וריח אין בהן משום מעילה.\u0004 ושואלים: \u0003ו\u0004כי \u0003ריח אין בו משום מעילה? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המפטם\u0004 (העושה) \u0003את הקטורת\u0004 כדי \u0003להתלמד בה\u0004 כיצד היא נעשית, \u0003או\u0004 כדי \u0003למוסרה לציבור — פטור.\u0004 ואם עשה אותה כדי \u0003להריח בה — חייב,\u0004 שנאמר בתורה \"איש אשר יעשה כמוה להריח בה ונכרת מעמיו\" (שמות ל, לח). \u0003והמריח בה\u0004 בקטורת המקדש — \u0003פטור\u0004 מן הכרת ומן החטאת, \u0003אלא שמעל\u0004 שהרי השתמש בקודש. הרי שיש מעילה בריח!","\u0003אלא אמר רב פפא: קול ומראה — אין בהן משום מעילה, לפי שאין בהן ממש. ו\u0004לגבי \u0003ריח\u0004 שבסממנים עצמם יש ממש, יש לחלק; ריח הקטורת היוצא בזמן הנחת הסממנים על הגחלים — יש בו משום מעילה, שזוהי דרך קיום המצוה, אבל ריח הקטורת היוצא \u0003לאחר שתעלה תמרותו\u0004 (שהציתו אש בקטורת ועלתה תמרת העשן) — \u0003אין בו משום מעילה, הואיל ונעשית\u0004 כבר \u0003מצותו.\u0004 ומה שיש לאחר מכן, אין בו עוד מעילה.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003נעשית\u0004 כבר \u0003מצותו אין\u0004 בשימוש \u0003בו\u0004 עוד \u0003משום מעילה?! והרי תרומת הדשן\u0004 כאשר נוטלים בכל יום מקצת מאפר הקרבנות אשר על המזבח ש\u0003נעשית\u0004 כבר \u0003מצותה\u0004 לאחר שנתרמה, \u0003ו\u0004בכל זאת \u0003יש בה משום מעילה,\u0004 שנאמר \u0003\"\u0004ולבש הכהן מדו בד ומכנסי בד ילבש על בשרו והרים את הדשן אשר תאכל האש את העולה על המזבח \u0003ושמו אצל המזבח\"\u0004 (ויקרא ו, ג), ודרשו חכמים: \"ושמו\" — \u0003שלא יפזר\u0004 אלא יניחנו בנחת, \u0003\"ושמו\" — שלא יהנה\u0004 ממנו.","ודוחים: אין להוכיח מכאן \u0003משום דהוו\u0004 \u0005[שהריהם],\u0006 \u0003תרומת הדשן ו\u0004גם \u0003בגדי כהונה\u0004 של כהן גדול ביום הכפורים, \u0003שני כתובין הבאין כאחד,\u0004 שנאסר השימוש בשניהם לאחר שהשתמשו בהם למצוותם, \u0003ו\u0004כלל הוא בידינו: \u0003\"כל שני כתובין הבאין כאחד אין מלמדין\".\u0004 שאם יש שני מקרים שיש בשניהם אותה הלכה מיוחדת, אומרים שיש ללמוד מהם רק לגופם, אבל לא לדברים אחרים. כי אם היה כלל זה קיים בכל הדינים שבתורה, לא היה צריך לחזור ולפרשו פעמיים, ודוקא מפני החזרה משמע שמקרים אלה הם יוצאים מן הכלל ואינם מלמדים על הכלל.","ומפרטים: \u0003תרומת הדשן — הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 \u0003בגדי כהונה\u0004 כיצד? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ובא אהרן אל אוהל מועד ופשט את בגדי הבד אשר לבש בבואו אל הקודש \u0003והניחם שם\"\u0004 (ויקרא טז, כג), ולמדים: \"והניחם שם\" — \u0003מלמד שטעונין גניזה\u0004 ואסור ליהנות מהם, אף שנעשתה בהם כבר מצוותם.","ומעירים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת חכמים \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 שפסוק זה \u0003מלמד שטעונין גניזה, אלא לר' דוסא דפליג עלייהו\u0004 \u0005[שחלק עליהם]\u0006 ש\u0003אמר\u0004 שבגדים אלה אמנם אינם ראויים עוד לכהן גדול לעבודת יום הכפורים, \u0003אבל ראויין הן לכהן הדיוט\u0004 שבגדי בד אלה הם כעין הבגדים שלובש כהן הדיוט בכל יום. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"והניחם שם\"\u0004 — ללמד \u0003שלא ישתמש בהם\u0004 הכהן הגדול \u0003ביום כפורים אחר.\u0004 אם כן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי לשיטת ר' דוסא יש רק כתוב אחד בדבר שנעשתה מצוותו ומועלים בו, ואפשר איפוא ללמוד מכאן הלכה כוללת!","ומשיבים: אין לקבוע הלכה כוללת, \u0003משום דהוו\u0004 \u0005[שהריהם],\u0006 \u0003תרומת הדשן ו\u0004אף \u0003עגלה ערופה\u0004 שאסור ליהנות ממנה לאחר עריפתה, \u0003שני כתובין הבאין כאחד, וכל שני כתובים הבאין כאחד אין מלמדין.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר,\u0004 חכמים, ש\u0003אין\u0004 שני כתובים הבאים כאחד \u0003מלמדין. אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר,\u0004 ר' דוסא, שאף שני כתובים הבאים כאחד \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בדחיית סברה זו? ומשיבים: \u0003תרי מיעוטי כתיבי\u0004 \u0005[שתי\u0006 לשונות \u0005מיעוט כתובות]\u0006 בהלכות אלה, ללמד שדין זה מיוחד רק בהן. לענין תרומת הדשן \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ושמו\"\u0004 — משמע: אותו ולא אחר. ולענין עגלה ערופה \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"הערופה\"\u0004 — משמע: רק זו הידועה, ולא כל דבר אחר דומה.","לאחר סטייה זו לבירור הלכה בדיני מעילה שבים למחלוקת אביי ורבא בענין דבר שאין מתכוון, ומנסים להביא ראיות שונות. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003הכניסה\u0004 (את העגלה המיועדת להיערף, או את הפרה האדומה) \u0003לרבקה\u0004 (צמד פרות) \u0003ודשה\u0004 תבואה תוך כדי לכתה עם פרות אחרות — \u0003כשירה\u0004 ולא נפסלה משום עבודה, כי לא התכוון שתעבוד. והיא עדיין בכלל \"אשר לא עלה עליה עול\" (במדבר יט, ב), וכן \"אשר לא עובד בה\" (דברים כא, ג), שכן נפסלה הפרה האדומה לשריפה, וכן העגלה לעריפה כשנעשתה בהן מלאכה. ואם הכניסה אף \u0003בשביל שתינק\u0004 מאמה \u0003ותדוש — פסולה.\u0004","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003לא אפשר\u0004 \u0005[שאי אפשר]\u0006 אחרת שהרי צריך שתינק, ובכל זאת כיון \u0003וקא מיכוין\u0004 \u0005[ומתכוון]\u0006 שתדוש \u0003וקתני\u0004 \u0005[ושנה]\u0006 \u0003פסולה,\u0004 והרי זו הוכחה שאי אפשר ומתכוון — אסור! ודוחים: \u0003שאני התם דכתיב\u0004 \u0005[שונה שם שנאמר]:\u0006 \u0003\"אשר לא עבד בה\",\u0004 ולשון זו משמעה שלא נעשתה בה עבודה \u0003מכל מקום\u0004 בכל אופן.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהכוונה שלא נעשתה בה עבודה \u0003אפילו רישא נמי\u0004 \u0005[בתחילה גם כן]\u0006 אף כשדשה שלא ברצונו, כיון שמכל מקום עשתה עבודה תיאסר!"],["ומתרצים: \u0003הא\u0004 \u0005[זה]\u0006 \u0003לא דמיא\u0004 \u0005[דומה]\u0006 \u0003אלא להא\u0004 \u0005[לזו]\u0006 ההלכה ששנינו: \u0003שכן עליה\u0004 על הפרה האדומה \u0003עוף — כשירה,\u0004 שאין זה נקרא \"עלה עליה עול\", \u0003עלה עליה זכר\u0004 להרביעה — \u0003פסולה.\u0004 והוא הדין לענייננו, שבהכניסה לרבקה ודשה, כיון שאין הדבר נוח לבעליה כמו עליית העוף עליה, לכן אינה נפסלת בכך. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל בדין בין עלה עליה עוף לעלה עליה זכר?","\u0003אמר רב פפא:\u0004 נאמר בכתוב \"ולקחו זקני העיר ההיא עגלת בקר אשר לא עבד בה אשר לא משכה בעול\" (דברים כא ג), \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005כתוב]\u0006 \u0003\"עבד\" וקרינן\u0004 \u0005[ו\u0006היינו \u0005קוראים]\u0006 \u0003\"עבד\",\u0004 היתה הכוונה — \u0003עד דעביד\u0004 \u0005[שעובד]\u0006 \u0003בה איהו\u0004 \u0005[הוא\u0006 עצמו\u0005]\u0006 בעל העגלה, ואם לא עבד בה בעצמו — כשירה. \u0003אי כתיב\u0004 \u0005[ואם\u0006 היה \u0005כתוב]\u0006 \u0003\"עובד\" וקרינן\u0004 \u0005[ו\u0006היינו \u0005קוראים]\u0006 \u0003\"עובד\",\u0004 היתה הכוונה — \u0003אפילו\u0004 נעשתה עבודה \u0003ממילא\u0004 \u0005[מעצמה],\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 אסור, שהרי מכל מקום \"עובד\" בה על ידי מישהו.","\u0003השתא דכתיב\u0004 \u0005[עכשיו שהכתוב]\u0006 הוא \u0003\"עבד\" וקרינן\u0004 \u0005[וקוראים אנו]\u0006 \u0003\"עובד\",\u0004 יש לצרף את שתי המשמעויות: \u0003עובד דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003עבד. מה עבד\u0004 בעצמו באופן \u0003דניחא ליה\u0004 \u0005[שנוח לו],\u0006 \u0003אף עובד\u0004 על ידי אחרים באופן \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 בכך. ולכן אם שכן עליה העוף — כשירה, משום שאין לו הנאה ורצון בכך. ואם עלה עליה זכר — פסולה. שהרי הוא מעונין בדבר.","ושוב מביאים הוכחה אחרת; \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: אדם שמצא \u0003אבידה, לא ישטחנה לא על גבי מטה ולא על גבי מגוד\u0004 (קולב) \u0003לצורכו\u0004 ליהנות או להתנאות בה, שהרי הוא נהנה מדבר שאינו שלו. \u0003אבל שוטחה לצורכה\u0004 אם צריכה האבידה אוורור \u0003על גבי מטה ועל גבי מגוד.\u0004 ואם \u0003נזדמנו לו אורחין\u0004 הרואים את הבגד, \u0003לא ישטחנה לא על גבי מטה, ולא על גבי מגוד, בין לצורכה בין לצורכו.\u0004 הרי זו ראיה גמורה שבמקום שיש צד הנאה שלו, אפילו אינו מתכוון לכך — אסור!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שטעם האיסור אינו משום הנאתו אלא משום הנזק שנגרם לאבידה, שעל ידי כך \u0003קלי לה\u0004 \u0005[\u0006הוא \u0005שורף,\u0006 מאבד \u0005אותה]\u0006 בידים, על ידי שמראה אותה לאורחים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום עינא בישא\u0004 \u0005[עין הרע]\u0006 שמטילים בה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום גנבי\u0004 \u0005[הגנבים]\u0006 שנודע להם על ידי כך שיש דבר יקר ברשותו ועשויים לבוא ולגנוב, ומטעם זה אסור.","ומציעים \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר, ששנינו: \u0003מוכרי כסות מוכרין\u0004 לגוים בגד שיש בו שעטנז (צמר ופשתים) \u0003כדרכן\u0004 שהם מניחים בגדים אלה על כתפיהם בלכתם. \u0003ובלבד שלא יתכוין\u0004 להתכסות בבגדים אלה \u0003בחמה\u0004 (בחום) \u0003מפני החמה, ו\u0004לא \u0003בגשמים מפני הגשמים. והצנועין\u0004 (הנזהרים ביותר במצוות) \u0003מפשילין\u0004 את הבגדים הללו \u0003לאחוריהם\u0004 ותולים אותם \u0003במקל.\u0004","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003אפשר\u0004 לכל מוכרי הכסות \u0003למעבד\u0004 \u0005[לעשות]\u0006 \u0003כצנועים,\u0004 ולא ליהנות כלל מן השעטנז, \u0003ו\u0004בכל זאת, \u0003כי\u0004 \u0005[וכאשר]\u0006 \u0003לא מכוין\u0004 \u0005[מתכון] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 הרי זו \u0003תיובתא למאן דתני לישנא קמא\u0004 \u0005[קושיה חמורה למי ששונה\u0006 את \u0005הלשון הראשונה]\u0006 של \u0003רבא,\u0004 שלפי גירסא זו אסר \"אפשר ואינו מתכוין\". ומסכמים: אכן, לענין לשון זו \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005],\u0006 ונדחתה אותה סברה.","במשנה שנינו כי \u0003\"לא יסיק בו\u0004 בחמץ את התנור \u0003\"\u0004. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בדומה לכך: \u0003תנור שהסיקו בקליפי\u0004 (בקליפות) של פירות \u0003ערלה או בקשין של\u0004 דגן שהיו מ\u0003כלאי הכרם.\u0004 אם היה זה תנור \u0003חדש,\u0004 ועל ידי היסק זה נתחזק החומר שבו ונעשה ראוי לשימוש קבוע — \u0003יותץ\u0004 (ישבר). שהרי הוא נהנה מן האיסור בבניית התנור. ואם היה זה תנור \u0003ישן — יוצן\u0004 (יצננוהו), ולא יאפו בו באותה שעה.","אם \u0003אפה בו את הפת\u0004 כל זמן שהאיסורים הללו בעין, \u0003רבי אומר: הפת אסורה\u0004 באכילה ובהנאה, משום שהשתמש לאפייתה בדבר אסור ונהנה מן האיסור. \u0003וחכמים אומרים: הפת מותרת.\u0004 ואם \u0003בישלה\u0004 את הפת \u0003על גבי גחלים\u0004 שנעשו מעצים אסורים — ל\u0003דברי הכל מותר,\u0004 ולכאורה יש סתירה בכך,","\u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בין חדש ובין ישן — יוצן,\u0004 הרי שאף תנור חדש אין צריך נתיצה! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 המחייב לנתוץ — כשיטת \u0003רבי,\u0004 ששיטתו היא שכיון שהאיסור גורם לקיומו, יש לאסור הכל. \u0003והא\u0004 \u0005[וזה]\u0006 האומר שדי לצננו בלבד — כשיטת \u0003רבנן\u0004 \u0005[חכמים];\u0006 כיון שהתנור אינו עשוי מכוח האיסור בלבד, שהרי היה התנור קיים קודם לכן, ואין האיסור אלא גורם לו חיזוק, סבורים חכמים שדי אם יצננוהו ולא יהנו בו מהיסק זה, ואינו צריך נתיצה.","על תירוץ זה מקשים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003רבי\u0004 האוסר את הפת שנאפתה מכח האיסור \u0003משום\u0004 ש\u0003יש שבח עצים בפת,\u0004 שהרי על ידי עצי האיסור נאפתה, ולכן אוסר הוא את הפת. ואולם \u0003זה וזה גורם,\u0004 כשגם היתר וגם איסור שייכים בדבר, וכגון תנור זה שאין נהנים בו מן ההיסק האסור אלא ממה שיסיקו בו בעתיד בעצי היתר. \u0003מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שהוא אסור? \u0003אלא\u0004 יש לחזור מהסבר זה ולומר: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 וכך יש לומר: \u0003הא\u0004 \u0005[זו]\u0006 הברייתא המחמירה — כשיטת \u0003ר' אליעזר\u0004 האוסר בזה וזה גורם, \u0003הא\u0004 \u0005[זו]\u0006 המקילה — כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 מדברי \u0003ר' אליעזר\u0004 הוא המקור להסבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר בדברי \u0003ר' אליעזר\u0004 שאמר לענין \u0003שאור, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שאור של חולין ו\u0004שאור \u0003של תרומה שנפלו לתוך עיסה\u0004 של חולין, \u0003ואין בזה\u0004 לבדו \u0003כדי להחמיץ\u0004 את העיסה \u0003ואין בזה\u0004 לבדו \u0003כדי להחמיץ ונצטרפו וחמצו\u0004 את העיסה. \u0003ר' אליעזר אומר: אחר אחרון אני בא\u0004 כלומר, דנים לפי הדבר האחרון שנפל. ואם היתה זו תרומה — הכל אסור, לפי שהשתמש בתרומה. \u0003וחכמים אומרים: בין שנפל איסור לכתחלה, ובין שנפל איסור לבסוף — לעולם אינו אוסר,\u0004"],["\u0003עד שיהא בו\u0004 באיסור לבדו \u0003כדי להחמיץ. ואמר אביי: לא שנו\u0004 בדברי ר' אליעזר שאם נפל ההיתר אחרון שמותר, \u0003אלא\u0004 באופן \u0003שקדם וסילק את האיסור\u0004 קודם נפילת ההיתר לתוך העיסה, ועדיין לא הספיק להחמיצה. \u0003אבל לא קדם וסילק את האיסור — אסור\u0004 אפילו נפל ההיתר אחרון, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003זה וזה גורם אסור.\u0004","ודוחים: \u0003וממאי דטעמא\u0004 \u0005[וממה\u0006 יודע אתה \u0005שהטעם]\u0006 של \u0003ר' אליעזר כאביי? דילמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של \u0003ר' אליעזר\u0004 כפי שאמר במפורש \u0003משום\u0004 ש\u0003אחר\u0004 מעשה \u0003אחרון אני בא,\u0004 שהכל הולך אחר גמר המעשה: אם היה בהיתר — הרי זה מותר, ואם היה באיסור — הרי זה אסור. \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003קדם וסילק את האיסור, לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003לא קדם וסילק את האיסור. אבל\u0004 אם נפלו \u0003בבת אחת, הכי נמי\u0004 \u0005[כך גם כן]\u0006 יהא הדין \u0003דשרי\u0004 \u0005[שמותר]\u0006 כי זה וזה גורם — מותר.","\u0003אלא\u0004 הכוונה היתה לשיטת \u0003ר' אליעזר\u0004 בענין \u0003עצי אשירה, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נטל הימנה\u0004 מן האשירה \u0003עצים\u0004 — הרי הם \u0003אסורין בהנאה. הסיק בהן את התנור,\u0004 אם היה זה תנור \u0003חדש — יותץ, ישן — יוצן.\u0004","\u0003אפה בו\u0004 בעצים אלה \u0003את הפת — אסורין\u0004 כל הנאפים בהם \u0003בהנאה. נתערבה\u0004 פת אסורה זו \u0003באחרות ואחרות באחרות\u0004 — \u0003כולן אסורין בהנאה. ר' אליעזר אומר: יוליך הנאה לים המלח,\u0004 כלומר אם נתערבה פת זו בהיתר מרובה, אין משמידים הכל, אלא יקח מעות כדי שווי עצי האשרה בהם הסיק, ואת הסכום הזה יאבד. \u0003אמר לו: אין פדיון לעבודה זרה,\u0004 ואם נאסרה פת משום כך, אי אפשר לפדותה ורק להשליך את דמיה לים המלח. ומדברי שני החכמים החולקים נלמד שזה וזה גורם — אסור.","ואולם דוחים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' אליעזר\u0004 והחולק עליו שמחמיר עד כדי כך \u0003בעבודה זרה, דחמיר\u0004 \u0005[שחמור]\u0006 \u0003איסורה,\u0004 אבל \u0003בשאר איסורין שבתורה\u0004 שאין איסורם חמור כל כך, \u0003מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 מחמיר עד כדי כך? כנגד הטענה הזו משיבים: \u0003אלא אם כן\u0004 שאתה טוען כי ר' אליעזר לא סבר כן בשאר איסורים, \u0003אמאן תרמייה\u0004 \u0005[על מי תזרוק,\u0006 תשליך\u0005]\u0006 את הברייתא הזו? שאם כן לא תמצא חכם הסבור כן. \u0003ועוד, הא תניא בהדיא\u0004 \u0005[הרי שנינו\u0006 בברייתא \u0005במפורש]:\u0006 \u0003וכן היה ר' אליעזר אוסר בכל איסורין שבתורה.\u0004","\u0003אמר אביי: אם תמצא לומר\u0004 כלומר, אם תדקדק בשיטות ותגיע למסקנה כי אמנם סבור רבי ש\u0003\"זה וזה גורם אסור\"\u0004 — הרי \u0003רבי היינו ר' אליעזר,\u0004 ששניהם אוסרים מטעם זה. \u0003ואם תמצי\u0004 (תמצא) \u0003לומר\u0004 ותגיע למסקנה כי \u0003\"זה וזה גורם מותר\"\u0004 לשיטת רבי לפחות, \u0003והכא\u0004 \u0005[וכאן]\u0006 שאסר רבי בפת \u0003משום\u0004 ש\u0003יש שבח עצים בפת הוא,\u0004 אם כן \u0003הני\u0004 \u0005[אותן]\u0006 \u0003קערות וכוסות וצלוחיות\u0004 של חרס שעשאן בתנור על ידי עצי איסור — \u0003אסירי\u0004 \u0005[אסורים],\u0006 שהרי יש שבח עצי איסור בכלים אלה, ואחר כך נהנים מגופם של כלי האיסור.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 רבי וחכמים הרי זה \u0003בתנור וקדירה\u0004 שנעשו על ידי עצי איסור, \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר \"זה וזה גורם אסור\"\u0004 — \u0003אסור,\u0004 שהרי תמיד ישאר גורם האיסור. \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר \"זה וזה גורם מותר\" — שרי\u0004 \u0005[מותר].\u0006 שהרי אינו נהנה מגוף התנור והקדירה האסורים, אלא רק לאחר שאפו בהם מכוח עצי היתר, וגורם האיסור המצוי בקדירה אינו אלא גורם אחד בלבד.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003אפילו ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר \"זה וזה גורם מותר\" — קדירה\u0004 שעשאה על ידי עצי איסור — \u0003אסורה, דהא קבלה\u0004 \u0005[שהרי מקבלת]\u0006 היא בתוכה \u0003בישולא מקמי דניתן\u0004 \u0005[תבשיל\u0006 עוד \u0005לפני שניתנו]\u0006 בתוכה \u0003עצים דהיתירא\u0004 \u0005[של היתר].\u0006 ואפשר להשתמש בתבשילים שבקדירה זו עוד לפני שמוסיפים עצים של היתר, ונמצא שנהנים מגוף הקדירה שנאסרה, ויש כאן רק איסור שהוא גורם אחד.","\u0003אמר רב יוסף אמר רב יהודה אמר שמואל: תנור שהסיקו בקליפי ערלה, או בקשין של כלאי הכרם,\u0004 אם היה זה תנור \u0003חדש — יותץ, ישן — יוצן. אפה בו את הפת, רבי אומר: הפת מותרת, וחכמים אומרים: הפת אסורה.\u0004 ומקשים: \u0003והתניא איפכא\u0004 \u0005[והרי שנויה\u0006 הברייתא \u0005להיפך,\u0006 בהיפוך השיטות\u0005]!\u0006 ומשיבים: \u0003שמואל איפכא תני\u0004 \u0005[שנה ההיפך]\u0006 אף את הברייתא הראשונה, ושנה שרבי הוא המתיר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003בעלמא קסבר\u0004 \u0005[כרגיל סבר]\u0006 \u0003שמואל\u0004 כי \u0003הלכה כרבי מחבירו\u0004 החולק עליו אבל \u0003לא מחביריו\u0004 הרבים. \u0003ובהא\u0004 \u0005[ו\u0006בהלכה \u0005זו]\u0006 בניגוד למקום אחר הלכה כרבי \u0003אפילו מחביריו. וסבר\u0004 שמואל \u0003אתנייה איפכא\u0004 \u0005[אשנה\u0006 את ההלכה \u0005להיפך]\u0006 שאהפוך את דעות החולקים, \u0003כי היכי דניקום רבנן לאיסורא\u0004 \u0005[כדי שיעמדו חכמים\u0006 בצד \u0005האיסור]\u0006 ויהא פסק ההלכה לאיסור כשיטת המרובים. שהרי לדעתו מסקנת ההלכה היא לאסור, ולכן שנה את הברייתא באופן שהכל יקבלו את פסק ההלכה הזה אף אם לא יסכימו לדעתו, שאף שזוהי אכן דעת רבי, בכל זאת הלכה כמותו.","באותה הלכה שנינו כי אם \u0003בישלה\u0004 את הפת \u0003על גבי גחלים\u0004 של עצי אשירה — \u0003דברי הכל הפת מותרת. אמר רב יהודה אמר\u0004 בשם \u0003שמואל, ור' חייא בר אשי אמר\u0004 בשם \u0003ר' יוחנן: חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא שנו\u0004 היתר זה \u0003אלא\u0004 כשהיו \u0003גחלים עוממות\u0004 שאין עוד אש בהם, וחומם רק מכוח היסק קודם לכן, \u0003אבל גחלים לוחשות — אסורין. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אפילו גחלים לוחשות נמי\u0004 \u0005[גם כן]\u0006 \u0003מותרין.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שגחלים \u0003לוחשות אסורין,\u0004 הרי זה \u0003משום\u0004 ש\u0003יש שבח עצים בפת. אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר אפילו\u0004 גחלים \u0003לוחשות מותרות\u0004 משום ששוב בטלו מלהיות עצים, אם כן אותה \u0003פת\u0004 ש\u0003אסר\u0004 משום ש\u0003יש שבח עצים בפת\u0004 לשיטת \u0003רבי היכי משכחת ליה\u0004 \u0005[איך מוצא אתה אותה]\u0006 הזדמנות שיש שבח עצים בפת? \u0003אמר רב פפא:\u0004 דבר זה יכול להיות \u0003כשאבוקה כנגדו\u0004 כאשר אופה את הפת כנגד העצים כשהם בוערים עדיין, שנהנה מהם עצמם."],["ותוהים: האם \u0003מכלל\u0004 הדברים נאמר כי \u0003דרבנן דפליגי עליה שרו\u0004 \u0005[שחכמים החלוקים עליו\u0006 על רבי \u0005התירו]\u0006 \u0003אפילו כשאבוקה כנגדו, אלא\u0004 אם כן \u0003עצים\u0004 שיש בהם \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003לרבנן היכי משכחת להו\u0004 \u0005[ל\u0006שיטת \u0005חכמים כיצד מוצא אתה אותם]\u0006 אם אפילו כך אינו אוסר? \u0003אמר רב אמי בר חמא: ב\u0004שעשה מהם \u0003שרשיפא\u0004 \u0005[שרפרף]\u0006 שאסור ליהנות מהם כשהם בעינם ממש, אבל בהיסק אכן אין הנאה כלל אלא לאחר שכלה ונתבער האיסור לגמרי, ולכן מותר.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רמי בר חמא מרב חסדא: תנור שהסיקו בעצי הקדש, ואפה בו\u0004 את \u0003הפת, לרבנן דשרו בקמייתא\u0004 \u0005[לחכמים שהתירו בראשונה]\u0006 בפת שנאפתה בעצי ערלה, \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הפת אסורה.\u0004 שאלו: \u0003ומה בין זו לערלה\u0004 שהרי בערלה התירו?! \u0003אמר רבא: הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003ערלה — בטילה במאתים,\u0004 ולכן יש מקום לומר שכמות הערלה שנספגה בתוך הפת הזו היתה פחותה מאחד במאתים בפת. ואילו \u0003הקדש — אפילו באלף לא בטיל\u0004 \u0005[בטל],\u0006 ולכן גם כשיש משהו מן הקודש בתוך הפת, הרי היא נאסרת כולה.","\u0003אלא אמר רבא: אי קשיא ליה\u0004 \u0005[אם קשה לו] —\u0006 הרי \u0003הא קשיא\u0004 \u0005[זה היה קשה]\u0006 לו, כלומר צד זה של השאלה הוא שנתקשה בו רמי בר חמא: \u0003והלא\u0004 כשהסיק בהקדש, \u0003מעל המסיק,\u0004 שכל המשתמש (אף במזיד) בדבר של הקדש לצורך חולין מעל בקודש. \u0003וכל היכא\u0004 \u0005[וכל מקום]\u0006 ש\u0003מעל המסיק — נפקו להו\u0004 \u0005[יצאו להם\u0006 העצים\u0005]\u0006 \u0003לחולין,\u0004 שנתחללו מקדושתם עם המעילה וחייב המועל לשלם תמורתם להקדש. ואם העצים יצאו לחולין, הפת שנאפת מהם ודאי מותרת!","\u0003אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 \u0003בעצי שלמים עסקינן\u0004 \u0005[עוסקים אנו]\u0006 שהקדישם לצורך הקרבת קרבן שלמים בדמיהם שהם קדשים קלים ואין לגבוה בהם אלא לאחר זריקת הדם, \u0003ואליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה\u0004 ש\u0003אמר: הקדש\u0004 אם השתמש בו \u0003בשוגג — מתחלל\u0004 על ידי כך, והריהו מעתה חולין גמורים, ואם נשתמש בו \u0003במזיד — אינו מתחלל.\u0004","ובדרך יסודית יותר: \u0003מזיד מאי טעמא\u0004 \u0005[מה הטעם]\u0006 ש\u0003לא\u0004 מתחלל, \u0003כיון דלאו\u0004 \u0005[שאינו]\u0006 \u0003בר מעילה,\u0004 שדין מעילה אינו קיים בו — \u0003לא נפיק\u0004 \u0005[יוצא]\u0006 \u0003לחולין,\u0004 שכן אין מביאים קרבן מעילה אלא על שימוש בהקדש בשגגה. ולפי שיטה זו \u0003שלמים נמי\u0004 \u0005[גם כן],\u0006 \u0003כיון דלאו בר מעילה נינהו\u0004 \u0005[שאינם בני מעילה הם],\u0006 כי בקרבן שלמים אין מעילה אלא לאחר זריקת דמם ולא קודם לכן. ולכן לשיטת ר' יהודה אם השתמש בהם אף בשוגג \u0003לא נפקא\u0004 \u0005[יוצאים]\u0006 \u0003לחולין\u0004 ונשארים באיסורם.","ושואלים: \u0003וכל היכא\u0004 \u0005[מקום]\u0006 ש\u0003מעל המסיק נפקי\u0004 \u0005[יוצאים]\u0006 העצים \u0003לחולין? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל\u0004 איסורים \u0003הנשרפין — אפרן מותר\u0004 לאחר שריפה, \u0003חוץ מעצי אשירה, ואפר הקדש — לעולם אסור.\u0004 הרי שיתכן שאף שהמסיק מעל, מכל מקום האפר עדיין אסור!","\u0003אמר רמי בר חמא:\u0004 שם מדובר \u0003כגון שנפלה דליקה מאיליה בעצי הקדש, דליכא אינש דנמעול\u0004 \u0005[שלא היה אדם שימעל].\u0006 וכיון שכך, לא יצאו אותם עצים לחולין, ומה שנשאר מהם עדיין הקדש הוא ואסור בהנאה. \u0003רב שמעיה אמר:\u0004 שם מדובר \u0003באותן\u0004 מיני אפר הקדש \u0003שטעונין גניזה\u0004 כגון תרומת הדשן. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \"והרים את הדשן אשר תאכל האש את העולה על המזבח ושמו אצל המזבח\" (ויקרא ו, ג), \u0003\"ושמו\" — בנחת, \"ושמו\" — כולו, \"ושמו\" — שלא יפזר.\u0004 הרי שאף לאחר שריפתו, עדיין יש בו קדושה ואסור בהנאה, ואף אין מעילה בהיסקו שלצורך הקרבת הקרבנות הוא.","שנינו במשנה: \u0003ר' יהודה אומר \"אין ביעור\u0004 חמץ אלא שריפה \u0003\"\u0004. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יהודה: אין ביעור חמץ אלא שריפה. ו\u0004דבר זה, \u0003הדין\u0004 (קל וחומר) \u0003נותן\u0004 (מלמד), ובאופן זה: \u0003ומה נותר\u0004 מן הקרבן לאחר זמן היתר אכילתו, \u0003שאינו ב\u0004כלל איסור \u0003\"בל יראה ובל ימצא\" — טעון שריפה, חמץ\u0004 שחמור ממנו \u0003שישנו ב\u0004כלל איסור \u0003\"בל יראה ובל ימצא\" — לא כל שכן שטעון שריפה!\u0004","\u0003אמרו לו\u0004 חכמים: \u0003כל דין\u0004 (קל וחומר) \u0003שאתה דן\u0004 (לומד) ש\u0003תחלתו\u0004 לכאורה \u0003להחמיר וסופו\u0004 מביא \u0003להקל — אינו דין\u0004 שאין זה קל וחומר אמיתי. ואף כאן לדעת ר' יהודה, אם \u0003לא מצא עצים לשורפו יהא\u0004 לדעתך \u0003יושב ובטל\u0004 ולא יבערנו? \u0003ו\u0004הרי \u0003התורה אמרה: \"תשביתו שאר מבתיכם\"\u0004 (שמות יב, טו), משמע \u0003בכל דבר שאתה יכול להשביתו,\u0004 וקל וחומר שלך בסופו של דבר יבוא להקל בדין החמץ!","\u0003חזר ר' יהודה ודנו דין אחר\u0004 שלא בדרך קל וחומר אלא על ידי \"מה מצינו\" (רש\"ש): \u0003נותר אסור באכילה\u0004 ואף \u0003חמץ אסור באכילה,\u0004 ומפני הדמיון ביניהם נסיק: \u0003מה נותר בשריפה — אף חמץ בשריפה.\u0004","\u0003אמרו לו: נבילה תוכיח, שאסורה באכילה ואינה טעונה שריפה,\u0004 ואם כן אין להביא ראיה מאיסור אכילה לחובת שריפה! \u0003אמר להן: הפרש\u0004 יש בין הדברים, שכן בנבילה מפורש היתר הנאה, וכך יש להשוות: \u0003נותר אסור באכילה ובהנאה, ו\u0004אף \u0003חמץ אסור באכילה ובהנאה. מה נותר טעון שריפה — אף חמץ טעון שריפה.\u0004","\u0003אמרו לו:\u0004 אף כאן אפשר להראות סתירה: \u0003שור הנסקל יוכיח, שאסור באכילה ובהנאה — ואינו טעון שריפה. אמר להן: הפרש\u0004 יש בין חמץ ושור הנסקל. וכך יש להשוות: \u0003נותר אסור באכילה ובהנאה וענוש כרת\u0004 על אכילתו, \u0003ו\u0004אף \u0003חמץ אסור באכילה ובהנאה וענוש כרת\u0004 על אכילתו, \u0003מה נותר\u0004 דינו \u0003בשריפה — אף חמץ\u0004 דינו \u0003בשריפה, אמרו לו:\u0004 אם כן, \u0003חלבו של שור הנסקל יוכיח, שאסור באכילה, ו\u0004כיון שהוא שור הנסקל אף אסור \u0003בהנאה, וענוש כרת,\u0004 שהרי כל האוכל חלב דינו בכרת, \u0003ו\u0004בכל זאת — \u0003אין טעון שריפה!\u0004"],["\u0003חזר ר' יהודה ודנו דין אחר: נותר ישנו ב\u0004כלל איסור \u0003\"בל תותירו\",\u0004 שהרי עיקר איסורו ממה שעברו והותירוהו אחר זמן אכילתו, \u0003וחמץ\u0004 הריהו \u0003ב\"בל תותירו\",\u0004 שהרי לאחר זמן איסור אכילתו הוא ב\"בל יראה ובל ימצא\". \u0003מה נותר\u0004 דינו \u0003בשריפה — אף חמץ\u0004 דינו \u0003בשריפה.\u0004","\u0003אמרו לו:\u0004 אם כן, \u0003אשם תלוי וחטאת העוף הבא על הספק, לדבריך\u0004 (לפי שיטתך שלך. במסכת תמורה לד,א) \u0003יוכיחו שהן ב\"בל תותירו\"\u0004 שאסור להותיר מהם לאחר זמנם. \u0003שאנו אומרים\u0004 דינם של אלו \u0003בשריפה, ואתה אומר\u0004 שאשם תלוי \u0003בקבורה! שתק ר' יהודה\u0004 ולא מצא תשובה לדבר.","\u0003אמר רב יוסף: היינו דאמרי אינשי\u0004 \u0005[זהו מה שאומרים אנשים]\u0006 כפתגם עממי: \u0003כפא דחטא נגרא — בגווה נשרוף חרדלא\u0004 \u0005[הכף שעשה הנגר —\u0006 \u0005בתוכה ישרפנו החרדל],\u0006 שאדם גורם רעה לעצמו על ידי מעשיו שלו. שהרי ההוכחה החותכת כנגד ר' יהודה באה לו מדבריו שלו.","פתגם עממי אחר \u0003אמר אביי: סדנא בסדני יתיב, מדויל ידיה משתלים\u0004 \u0005[עושה הסד בסד\u0006 הוא \u0005יושב,\u0006 ש\u0005מגמול ידיו\u0006 שלו \u0005משתלם\u0006 עונשו\u0005].\u0006","ו\u0003רבא אמר\u0004 כפתגם אחר: \u0003גירא בגירי מקטיל, מדויל ידיה משתלים\u0004 \u0005[עושה החיצים בחיציו\u0006 הוא \u0005נהרג, מגמול ידו משתלם\u0006 עונשו\u0005].\u0006","שנינו במשנה: \u0003וחכמים אומרים\u0004 שחמץ אפשר לבערו בדרכים שונות: \u0003מפרר וזורה\u0004 לרוח ומטיל לים. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003היכי קאמר\u0004 \u0005[כיצד אמר,\u0006 למה התכוון\u0005],\u0006 האם כוונת דבריהם היא: \u0003מפרר וזורה לרוח,\u0004 וכן דוקא \u0003מפרר ומטיל לים. או דילמא\u0004 \u0005[שמא]\u0006 יש להבין: \u0003מפרר וזורה לרוח, אבל מטיל לים בעיניה\u0004 \u0005[בעינו],\u0006 שיכול לזרוק את החמץ לים כמות שהוא ואינו צריך לפררו תחילה. \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן\u0006 במשנה\u0005]\u0006 ל\u0003גבי עבודה זרה כי האי גוונא\u0004 \u0005[כעין זה]\u0006 \u0003ר' יוסי אומר: שוחק\u0004 עבודה זרה \u0003וזורה לרוח, או מטיל לים, ואיבעיא להו\u0004 \u0005[ונשאלה להם\u0006 ללומדים\u0005]\u0006 אף שם: \u0003היכי קאמר\u0004 \u0005[כיצד אמר,\u0006 למה התכוון\u0005]?\u0006 האם \u0003שוחק וזורה לרוח, ושוחק ומטיל לים. או\u0004 שמא \u0003שוחק וזורה לרוח, אבל מטיל לים בעיניה\u0004 \u0005[בעינו].\u0006","\u0003אמר רבה: מסתברא\u0004 \u0005[מסתבר]\u0006 \u0003עבודה זרה\u0004 ש\u0003לים המלח קא אזלא\u0004 \u0005[הולכת\u0006 מושלכת שם\u0005] —\u0006 \u0003לא בעי\u0004 \u0005[צריכה]\u0006 \u0003שחיקה,\u0004 שכן לא יבואו להוציאה משם ולהשתמש בה. \u0003חמץ\u0004 ש\u0003לשאר\u0004 ה\u0003נהרות קאזיל\u0004 \u0005[הוא הולך]\u0006 ונזרק — \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003פירור. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: אדרבא, איפכא מסתברא\u0004 \u0005[ההיפך\u0006 הוא \u0005המסתבר],\u0006 \u0003עבודה זרה\u0004 שלרוב היא \u0003לא ממיסה\u0004 \u0005[נמסה]\u0006 שהרי עשויה היא בדרך כלל מחומר מוצק, \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003שחיקה. חמץ דממיס\u0004 \u0005[ש\u0006הוא \u0005נמס]\u0006 במים — \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003פירור\u0004 ונמס מעצמו.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רבה, תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב יוסף.\u0004 כיצד, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רבה: היה\u0004 אדם \u0003מהלך במדבר\u0004 וחמץ בידו, והגיע זמן הפסח — \u0003מפרר וזורה\u0004 את החמץ \u0003לרוח. היה מהלך בספינה — מפרר\u0004 את החמץ \u0003ומטיל לים.\u0004 וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב יוסף: היה מהלך במדבר\u0004 ומצא עבודה זרה — \u0003שוחק וזורה לרוח. היה מהלך בספינה — שוחק ומטיל לים.\u0004","ומעירים: \u0003שחיקה\u0004 שבברייתא אחת \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לרבה,\u0004 שלדעתו עבודה זרה המושלכת לים אינה צריכה שחיקה. \u0003פירור\u0004 חמץ שבברייתא אחרת \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לרב יוסף.\u0004 ומשיבים: \u0003שחיקה לרבה לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[כאן]\u0006 שאינו צריך לשחוק — כשזורק \u0003לים המלח, הא\u0004 \u0005[כאן]\u0006 שצריך לשחוק כשנוסע בספינה — וזורק \u0003לשאר נהרות.\u0004 וכן \u0003פירור לרב יוסף לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[כאן]\u0006 — \u0003בחיטי\u0004 \u0005[ב\u0006שק \u0005חיטים]\u0006 שהחמיצו שצריך להוציאם מן השק לפררם ולפזרם על פני המים, \u0003הא\u0004 \u0005[כאן]\u0006 \u0003— בנהמא\u0004 \u0005[בלחם],\u0006 כיון שזרקו לים הריהו נמס, ואינו צריך לפררו עוד.","\u0003חמץ של גוי שעבר עליו הפסח — מותר בהנאה\u0004 לישראל, ואילו חמץ \u0003של ישראל\u0004 שנשאר חמץ ברשותו לאחר הפסח — \u0003אסור בהנאה, שנאמר:\u0004 \"ולא יראה לך חמץ \u0003ולא יראה לך שאר\u0004 בכל גבולך\" (שמות יג, ז).","תחילה שואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' יהודה ולא\u0004 כשיטת \u0003ר' שמעון ולא\u0004 כשיטת \u0003ר' יוסי הגלילי.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה הלכה בה נשנו שיטותיהם של חכמים אלה, ומה הן שיטות אלו שהזכרנו תחילה? ומסבירים: \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמץ בין לפני זמנו\u0004 מחצות ערב פסח עד הערב, \u0003בין לאחר זמנו\u0004 משעבר הפסח — \u0003עובר עליו\u0004 אם אוכלו רק \u0003בלאו\u0004 (איסור לא תעשה). \u0003תוך זמנו\u0004 בימי הפסח עצמו אם אוכלו — \u0003עובר עליו\u0004 גם \u0003בלאו ו\u0004גם נענש ב\u0003כרת,\u0004 אלו \u0003דברי ר' יהודה.\u0004"],["\u0003ר' שמעון אומר: חמץ לפני זמנו ולאחר זמנו — אינו עובר עליו בלא כלום,\u0004 ואין בו איסור הנאה כלל. \u0003תוך זמנו — עובר עליו\u0004 כמפורש בתורה \u0003בכרת ובלאו, ומשעה שאסור באכילה\u0004 מחצות ערב פסח \u0003אסור בהנאה,\u0004 ומעירים: במשפט זה \u0003אתאן לתנא קמא\u0004 \u0005[באנו לתנא הראשון],\u0006 שמשפט זה אינו כשיטת ר' שמעון אלא לדעת ר' יהודה הוא. ו\u0003ר' יוסי הגלילי אומר: תמה על עצמך, היאך חמץ אסור בהנאה כל שבעה!\u0004 שהוא חולק על עיקרה של ההנחה שחמץ אסור בהנאה אפילו בכל שבעת ימי הפסח.","\u0003ו\u0004מכאן באים לדון בבעיה קרובה: \u0003מנין לאוכל חמץ משש שעות ולמעלה\u0004 בערב פסח \u0003שהוא עובר בלא תעשה — שנאמר\u0004 \"וזבחת פסח לה' אלהיך צאן ובקר במקום אשר יבחר ה' לשכן שמו שם, \u0003לא תאכל עליו חמץ\u0004 שבעת ימים תאכל עליו מצות, לחם עוני\" (דברים טז, ב— ג). ולמד מכאן שמזמן ששוחטים את קרבן הפסח משעת הצהריים של יום ארבעה עשר בניסן, אסורה אכילת החמץ, אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר לו ר' שמעון: וכי אפשר לומר כן? והלא כבר נאמר \"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות\",\u0004 שהכתוב קשר את אכילת המצות עם איסור החמץ, ולדעתך יש לאכול מצות עוד ביום ארבעה עשר בניסן! \u0003אם כן מה תלמוד לומר \"לא תאכל עליו חמץ\",\u0004 יש לדייק ממנו כך: \u0003בשעה שישנו ב\u0004מצוות עשה של \u0003קום אכול מצה — ישנו\u0004 גם \u0003ב\u0004איסור \u0003בל תאכל חמץ, ובשעה שאינו בקום אכול מצה — אינו בבל תאכל חמץ.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שאיננו מקבל דחיה זו? ומסבירים: לדעתו \u0003תלתא קראי כתיבי\u0004 \u0005[שלושה מקראות כתובים]\u0006 כאן: נאמר \u0003\"ולא יאכל חמץ\"\u0004 (שמות יג, ג), \u0003ו\u0004נאמר \u0003\"כל מחמצת לא תאכלו\u0004 בכל מושבותיכם תאכלו מצות\u0003\"\u0004 (שמות יב, כ), ונאמר \u0003\"לא תאכל עליו חמץ\"\u0004 (דברים טז, ג). \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 בא ללמד שיש איסור חמץ \u0003לפני זמנו\u0004 בערב פסח, \u0003וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 בא לומר שישנו גם \u0003לאחר זמנו\u0004 לאחר שעבר עליו הפסח, \u0003וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 בא ללמד \u0003לתוך זמנו.\u0004","ושואלים: אם כן, \u0003ור' שמעון\u0004 כיצד הוא מבין כתובים אלה? ומשיבים: \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 — \u0003לתוך זמנו, ו\u0004פסוק זה שנאמר בו \u0003\"כל מחמצת\u0004 לא תאכלו \u0003\"\u0004— \u0003מבעי ליה\u0004 \u0005[נחוץ לו]\u0006 \u0003לכדתניא\u0004 \u0005[לכמו ששנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003אין לי אלא\u0004 חמץ אסור כ\u0003שנתחמץ מאליו\u0004 מחמת ששהה והחמיץ מעצמו, ואולם דבר שהחמיץ \u0003מחמת דבר אחר, מנין\u0004 שהוא בכלל חמץ? \u0003תלמוד לומר: \"כל מחמצת לא תאכלו\"\u0004 משמע לאסור כל שיש בו צד חימוץ, בין מעצמו בין מאחרים.","ואילו \u0003\"ולא יאכל חמץ\"\u0004 — \u0003מבעי ליה\u0004 \u0005[נחוץ לו]\u0006 ללמוד ממנו ענין אחר \u0003לכדתניא\u0004 \u0005[לכמו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: מנין לפסח מצרים שאין חימוצו נוהג\u0004 כלומר, שלא נהגו בו איסור \u0003אלא יום אחד\u0004 בלבד — \u0003תלמוד לומר \"לא יאכל חמץ\",\u0004 ונאמר בפסוק ש\u0003סמיך ליה\u0004 \u0005[סמוך לו\u0006 הבא אחריו\u0005]\u0006 \u0003\"היום אתם יצאים\u0004 בחודש האביב\u0003\"\u0004 (שמות יג, ד), שאיסור אכילת חמץ בפסח מצרים חל באותו יום בלבד.","ושואלים: \u0003ור' יהודה\u0004 חמץ ש\u0003מחמת דבר אחר מנא ליה\u0004 \u0005[מנין לו]\u0006 שהוא אסור? ומשיבים: \u0003מדאפקיה רחמנא\u0004 \u0005[מכיון שהוציאו הכתוב]\u0006 \u0003בלשון מחמצת\u0004 אין אנו צריכים לריבוי בפסוק מיוחד, והדבר נלמד מלשון זו.","ושואלים: ודבר זה שאמר \u0003ר' יוסי הגלילי\u0004 בענין פסח מצרים \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 לר' יהודה? שהרי מפסוק זה למד הלכה אחרת! ומשיבים: \u0003אי בעית אימא מדסמיך ליה\u0004 \u0005[אם תרצה אמור מכיון שנסמך לו]\u0006 \u0003\"היום\",\u0004 ולדעתו לא כל הפסוק נאמר לצורך זה, אלא דבר זה נלמד אגב סמיכותו של פסוק אחר. \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ר' יהודה \u0003סמוכין לא דריש\u0004 \u0005[דורש].\u0006 ששיטתו בכלל היא שאין לומדים מסמיכות המקראות, אלא במקרים מיוחדים. ובאמת ר' יהודה אינו מקבל את שיטת ר' יוסי הגלילי וסבור שבפסח מצרים היה איסור חמץ כל שבעת ימים.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהבאנו: \u0003ומנין לאוכל חמץ משש שעות ולמעלה שהוא עובר בלא תעשה — שנאמר: \"לא תאכל עליו חמץ\",\u0004 אלו \u0003דברי ר' יהודה. אמר לו ר' שמעון: וכי אפשר לומר כן? והלא כבר נאמר \"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות\",\u0004 שסמך זמן איסור אכילת חמץ לזמן אכילת מצה.","ושואלים: \u0003ור' יהודה\u0004 הלוא \u0003שפיר קאמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' שמעון,\u0004 וכיצד יכול הוא להביא ראיה מפסוק זה? ומשיבים: \u0003ור' יהודה אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 שכך יש להבין את הדברים: \u0003ההוא\u0004 \u0005[אותו]\u0006 הקשר בין איסור חמץ לאכילת מצה — \u0003לקובעו חובה אפילו בזמן הזה הוא דאתא\u0004 \u0005[שבא].\u0006 שהרי יכולנו לחשוב שלאחר חורבן הבית, כשאין קרבן פסח, שוב אין גם חובת אכילת מצה. על כן מצרף הכתוב את מצות המצה עם איסור החמץ, לומר: כשם שאסורים באכילת חמץ בזמן הזה, כן גם חייבים באכילת מצה.","ושואלים: \u0003ור' שמעון לקובעו חובה\u0004 בזמן הזה \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 דבר זה מכתוב מפורש שנאמר בו \"בראשון בארבעה עשר יום לחודש \u0003בערב תאכלו\u0004 מצות עד יום האחד ועשרים לחודש בערב\" (שמות יב, יח), הרי שחובת מצה קשורה בזמן מסויים ולא רק בקרבן הפסח. \u0003ור' יהודה,\u0004 שאינו למד דבר זה מכאן, \u0003מיבעי ליה\u0004 \u0005[נחוץ, לו]\u0006 פסוק זה \u0003ל\u0004למדנו חיובו של מי שהוא \u0003טמא או שהיה בדרך רחוקה,\u0004 שאינו יכול להקריב את הפסח בזמנו. \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ובפסח לא יאכל, מצה ומרור נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניכול\u0004 \u0005[לא יאכל].\u0006 לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף הוא חייב במצה.","ומצד שני, \u0003ור' שמעון\u0004 טוען כי מי שהיה \u0003טמא ושהיה בדרך רחוקה לא איצטריך קרא\u0004 \u0005[צריך כתוב\u0006 מיוחד\u0005]\u0006 ללמד שחייבים באכילת מצה, משום שהוא \u0003לא גרע\u0004 \u0005[גרוע]\u0006 \u0003מערל ובן נכר.\u0004 שהרי נאמר בקרבן הפסח: \u0003\"וכל ערל לא יאכל בו\"\u0004 (שמות יב, מח), ומן ההדגשה \u0003\"בו\"\u0004 אנו מדייקים: בקרבן הפסח בלבד \u0003הוא אינו אוכל, אבל אוכל הוא במצה ובמרור.\u0004 ושואלים: \u0003ור' יהודה,\u0004 מה אומר הוא כנגד טענה זו? ומשיבים: לדעתו \u0003כתיב בהאי וכתיב בהאי\u0004 \u0005[כתוב בזה וכתוב בזה]\u0006 שפירש הכתוב גם לדין טמא ושהיה בדרך רחוקה וגם לדין ערל ובן נכר החייבים מכל מקום במצה ומרור.","מעתה לאחר בירור שיטות ר' יהודה, ר' שמעון ור' יוסי הגלילי, שואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כ\u0003ר' יהודה\u0004 — הלוא ר' יהודה \u0003חמץ סתמא\u0004 \u0005[סתם]\u0006 \u0003קאמר\u0004 \u0005[אמר]\u0006 משמע, \u0003אפילו\u0004 חמץ של \u0003גוי\u0004 אסור בהנאה בפסח, שלא כמשנתנו, \u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' שמעון\u0004"],["חמץ של \u0003ישראל נמי מישרא קא שרי\u0004 \u0005[גם כן הוא מתיר]\u0006 בהנאה לאחר זמנו! \u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' יוסי הגלילי — אפילו תוך זמנו נמי מישרא קא שרי\u0004 \u0005[גם כן הוא מתיר]\u0006 \u0003בהנאה.\u0004","\u0003אמר רב אחא בר יעקב: לעולם\u0004 אפשר לפרש כי משנתנו כשיטת \u0003ר' יהודה היא, ויליף\u0004 \u0005[ולומד\u0006 הוא\u0005]\u0006 דין \u0003שאור\u0004 לענין איסור \u0003אכילה משאור\u0004 לענין \u0003ראייה.\u0004 כיצד; \u0003מה שאור\u0004 של איסור \u0003ראייה\u0004 נאמר בו \"לא יראה לך\", ואנו מבינים בכך כי \u0003שלך,\u0004 של ישראל \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה רואה, אבל אתה רואה של אחרים\u0004 (גוים) \u0003ושל גבוה\u0004 השייך למקדש. \u0003אף שאור\u0004 לענין איסור \u0003אכילה\u0004 נאמר בו: \u0003שלך אי\u0004 \u0005[אין]\u0006 \u0003אתה אוכל, אבל אתה אוכל של אחרים\u0004 (גוים), \u0003ושל גבוה\u0004 לאחר הפסח.","\u0003ובדין הוא דאיבעי ליה למיתנא\u0004 \u0005[שהיה לו לשנות]\u0006 ש\u0003אפילו באכילה נמי שרי\u0004 \u0005[גם כן מותר]\u0006 חמץ לאחר זמנו, \u0003ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 שחמץ של \u0003ישראל אסור בהנאה — תנא נמי\u0004 \u0005[שנה גם כן]\u0006 משום גרר הלשון שחמץ של \u0003גוי מותר בהנאה,\u0004 אבל יש להבין כי הוא מותר אף באכילה. \u0003ו\u0004כן \u0003בדין הוא דאיבעי ליה למיתנא\u0004 \u0005[שהיה צריך לו לשנות]\u0006 ש\u0003אפילו בתוך זמנו\u0004 חמץ של גוים \u0003מותר בהנאה. ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 מענין החמץ של \u0003ישראל לאחר זמנו — תנא נמי\u0004 \u0005[שנה גם כן]\u0006 של \u0003גוי לאחר זמנו,\u0004 ואין לדייק מלשון הברייתא בפרטים אלה, והמשנה היא כשיטתו של ר' יהודה.","\u0003רבא אמר:\u0004 לא כך, אלא \u0003לעולם\u0004 משנתנו כשיטת \u0003ר' שמעון היא.\u0004 ואם תאמר: הלוא לשיטת ר' שמעון חמץ של ישראל לאחר הפסח מותר בהנאה, ומדוע נאסר במשנה? יש לומר ש\u0003ר' שמעון\u0004 סבור אף שלדעתו מותר מן התורה, בכל זאת \u0003קנסא קניס\u0004 \u0005[קנס קנס]\u0006 את העבריין, \u0003הואיל ועבר עליה\u0004 \u0005[עליו\u0006 על החמץ\u0005]\u0006 \u0003בבל יראה ובל ימצא\u0004 אסרוהו חכמים בהנאה.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא, היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 במשנה: \u0003של ישראל אסור, משום שנאמר \"לא יראה\",\u0004 מעתה יכולים אנו להבין מה הקשר לציווי לא יראה עם חמץ שעבר עליו הפסח — משום קנס על שעבר על \"לא יראה\". \u0003אלא ל\u0004שיטת \u0003רב אחא בר יעקב\u0004 שמשנתנו כר' יהודה, ולדעתו חמץ שעבר עליו הפסח אסור באכילה מן התורה, אם כן \u0003משום \"לא יאכל חמץ\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 שהרי לדעתו זהו מקור האיסור!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שראיה זו \u0003אסיפא קאי\u0004 \u0005[על הסוף,\u0006 איסור ההנאה בחמץ ישראל, \u0005היא עומדת\u0006 מתייחסת\u0005]?!\u0006 \u0003ארישא קאי\u0004 \u0005[על תחילת\u0006 המשנה \u0005היא עומדת\u0006 מתייחסת\u0005]\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 כך יש לקרוא את משנתנו: \u0003חמץ של גוי שעבר עליו הפסח — מותר בהנאה, משום שנאמר \"לא יראה לך\" — שלך אי\u0004 \u0005[אין]\u0006 \u0003אתה רואה, אבל אתה רואה של אחרים\u0004 (גוים) \u0003ושל גבוה\u0004 (הקדש). \u0003ויליף\u0004 \u0005[ולמד]\u0006 \u0003שאור\u0004 של \u0003אכילה משאור\u0004 של \u0003ראייה\u0004 שאת הכתוב \"לא יראה לך\" יש להבין כההסבר של ההיתר ולא של האיסור שבו.","ומעירים כי רבא ורב אחא בר יעקב \u0003אזדו לטעמייהו\u0004 \u0005[הלכו\u0006 כל אחד \u0005לטעמיהם\u0006 לשיטתם\u0005],\u0006 כיצד: \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בדבר זה, \u0003האוכל שאור של גוי שעבר עליו הפסח, לדברי ר' יהודה, רבא אמר: לוקה\u0004 שעבר על איסור מן התורה, \u0003ורב אחא בר יעקב אמר: אינו לוקה.\u0004","ומפרטים, \u0003רבא אמר:\u0004 כי לשיטת ר' יהודה \u0003לוקה,\u0004 כי \u0003לא יליף\u0004 \u0005[למד]\u0006 \u0003ר' יהודה שאור\u0004 של \u0003אכילה משאור\u0004 של \u0003ראייה,\u0004 וכיון שבאכילה לא נאמר \"לך\" הרי לענין אכילה חמץ אף של גוי אסור לעולם. \u0003ורב אחא בר יעקב אמר: אינו לוקה,\u0004 שכן \u0003יליף\u0004 \u0005[למד]\u0006 ענין \u0003שאור\u0004 של \u0003אכילה משאור\u0004 של \u0003ראייה\u0004 ובכך תלוי הדבר.","ומעירים: \u0003והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003רב אחא בר יעקב מההיא\u0004 \u0005[מאותה]\u0006 שיטה שאחז בה, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 במקום אחר: \u0003האוכל חמץ של הקדש במועד\u0004 (בפסח) — \u0003מעל,\u0004 שאם עשה זאת בשוגג הריהו חייב להביא קרבן על מעילתו, על שהשתמש בקודש. \u0003ויש אומרים: לא מעל.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003יש אומרים\u0004 אלה הסבורים שעל חמץ של הקדש בפסח אינו מועל? \u0003אמר ר' יוחנן:\u0004 שיטת \u0003ר' נחוניא בן הקנה היא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נחוניא בן הקנה היה עושה את יום הכפורים כשבת\u0004 לענין \u0003תשלומין\u0004 של נזקים שהזיק אדם בו ביום.","כיצד; \u0003מה שבת,\u0004 מי שחילל שבת במזיד ותוך כדי כך גרם נזק לחבירו, וכגון שהדליק גדישו של חבירו בשבת, כיון שהוא \u0003מתחייב בנפשו\u0004 (שהרי המחלל שבת במזיד חייב סקילה) \u0003ו\u0004לכן הוא \u0003פטור מן התשלומין,\u0004 שכן אין מענישים אדם בשני עונשים ונדון רק בעונש החמור יותר. \u0003אף\u0004 מי שגרם נזק תוך כדי חילול \u0003יום הכפורים מתחייב בנפשו\u0004 שהרי מחלל יום הכפורים עונשו כרת, שהוא מיתת הנפש בידי שמים, \u0003ו\u0004לכן אף הוא \u0003פטור מן התשלומין.\u0004 ואם כן, אף האוכל חמץ בפסח, כיון שענוש כרת, ממילא נפטר משאר ענשים, ובכללם מעילה. ומכל מקום ברור כי שני התנאים בברייתא זו סבורים כי לחמץ בפסח יש ערך, ובודאי משום שלאחר הפסח יהא החמץ מותר בהנאה, ודברים אלה כשיטת ר' שמעון הם.","\u0003רב יוסף אמר:\u0004 את המחלוקת בברייתא יש להבין בדרך אחרת. שני התנאים הללו מקבלים את דעת ר' יוסי הגלילי שחמץ בפסח מותר בהנאה, ואם כן אף חמץ זה של הקדש מותר בהנאה. ואולם אם מדובר בחמץ סתם, הרי מותר למכרו לגוי או להאכילו לכלבים. אבל חמץ של הקדש (בשל קדושתו) אי אפשר להשתמש בו כך, ואם כן ערכו תלוי בשאלה האם \u0003פודין את הקדשים\u0004 לא לצורך אכילת אדם אלא כדי \u0003להאכילן לכלבים קמיפלגי\u0004 \u0005[חולקים].\u0006","\u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ש\u0003מעל\u0004 בחמץ ההקדש בפסח \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003פודין את הקדשים להאכילן לכלבים,\u0004 וכיון שאפשר לפדות את חמץ ההקדש ולהאכילו לכלבים משמע שיש לו ערך מסויים, ולכן יש בו מעילה. \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר לא מעל קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003אין פודין\u0004 את הקדשים אלא לצורך אכילת אדם מישראל. ובמקרה זה שאדם מישראל אסור באכילת חמץ, הרי שחמץ של הקדש אין לו ערך כלל בפסח, ולכן האוכלו לא מעל.","ומעירים: \u0003רב אחא בר רבא תנא לה\u0004 \u0005[שנה אותה]\u0006"],["\u0003להא שמעתא משמיה\u0004 \u0005[את ההלכה הזו משמו]\u0006 של \u0003רב יוסף בהא לישנא\u0004 \u0005[בלשון זו]\u0006 \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003אין פודין את הקדשים\u0004 כדי \u0003להאכילן לכלבים, והכא בהא קמיפלגי\u0004 \u0005[וכאן\u0006 בברייתא זו, \u0005ב\u0006דבר \u0005זה נחלקו]:\u0006 האם \u0003דבר הגורם לממון כממון דמי\u0004 \u0005[נחשב]\u0006 או לא. כלומר, האם דבר שכשלעצמו ברגע זה איננו שוה כסף, ואולם אם ישמידוהו יגרם על ידי כך לאחר מכן הפסד כספי, האם נחשב הדבר כבעל ערך כספי ממש, ולשיטתו של ר' שמעון שחמץ לאחר הפסח מותר באכילה.","ומפרטים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר מעל,\u0004 שבהקדש חמץ בפסח מועלים, \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003דבר הגורם לממון — כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 ולכן אף שהחמץ איננו שוה כעת מאומה, כיון שאחר הפסח ראוי הוא שוב לאכילה, הרי גם כעת יש לו ערך כספי (שהרי בעתיד הוא שווה כסף). \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר לא מעל — קסבר\u0004 \u0005[סבור הוא]:\u0006 כי \u0003דבר הגורם לממון — לאו\u0004 \u0005[לא]\u0006 \u0003כממון דמי\u0004 \u0005[נחשב],\u0006 וכיון שבשעה זו אין החמץ בעל ערך — לא מעל.","\u0003רב אחא בר יעקב אמר\u0004 בפירוש סוגיה זו: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003דבר הגורם לממון כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003והכא בפלוגתא\u0004 \u0005[וכאן במחלוקת]\u0006 של \u0003ר' יהודה ור' שמעון קמיפלגי\u0004 \u0005[\u0006הרי \u0005הם נחלקים].\u0006 כיצד? \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר לא מעל\u0004 סבור כשיטת \u0003ר' יהודה\u0004 שלדעתו חמץ שעבר עליו הפסח אסור בהנאה, ואם כן חמץ ההקדש אין לו היתר, ולכן אינו שוה מאומה. \u0003ו\u0004אילו \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר מעל\u0004 סבור כשיטת \u0003ר' שמעון\u0004 שחמץ לאחר הפסח מותר בהנאה, וכיון שכך הריהו דבר הגורם לממון ודינו כממון, ומעל בו.","ולכאורה אפשר להקשות: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב אחא בר יעקב הוא\u0004 זה ש\u0003אמר\u0004 כי \u0003ר' יהודה יליף\u0004 \u0005[למד]\u0006 \u0003שאור\u0004 שנאמר באיסור \u0003אכילה משאור\u0004 שנאמר באיסור \u0003ראייה,\u0004 כלומר שאף איסור אכילה לא חל אלא על חמץ של ישראל שאסור בראיה, אבל חמץ של גוי ושל הקדש שמותרים בראיה מותר! \u0003אלא\u0004 עלינו לומר כי \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רב אחא בר יעקב מההיא\u0004 \u0005[מאותה\u0006 שיטה\u0005]\u0006 בפירוש דברי ר' יהודה, והוא סבור כרבא שר' יהודה אוסר כל חמץ שעבר עליו הפסח.","\u0003רב אשי אמר\u0004 בפירוש הדברים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין פודין\u0004 קדשים להאכילם לכלבים, \u0003ו\u0004כן \u0003דבר הגורם לממון לאו\u0004 \u0005[לא]\u0006 \u0003כממון דמי\u0004 \u0005[נחשב],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 בברייתא זו \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יוסי הגלילי ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003קמיפלגי\u0004 \u0005[הם חלוקים].\u0006 ובאופן זה: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר מעל\u0004 בחמץ של הקדש סבור \u0003כר' יוסי\u0004 הגלילי, שלדעתו אפילו חמץ של ישראל מותר בהנאה כל שבעה, ויש איפוא לחמץ ערך, ולכן מעל. \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר לא מעל\u0004 סבור \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 שלדעתם חמץ בפסח אסור בהנאה ואינו שוה מאומה, שאף שאולי יהיה שוה משהו אחר הפסח, הרי דבר הגורם לממון אינו נחשב כממון, ובדבר שאין בו ערך אין מעילה.","\u0003אמר רב: חמץ בזמנו\u0004 כלומר בתוך הפסח, \u0003בין\u0004 שנתערב \u0003במינו,\u0004 כגון קמח חמץ בקמח מצה ומצה במצת חמץ, \u0003בין\u0004 שנתערב \u0003שלא במינו — אסור.\u0004 אם היה זה \u0003שלא בזמנו\u0004 אלא לאחר הפסח, אם נתערב \u0003במינו — אסור,\u0004 נתערב \u0003שלא במינו — מותר.\u0004","ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה\u0006 בדיוק \u0005אנו עוסקים],\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בנותן טעם,\u0004 כלומר שהחמץ שנתערב היה מרובה עד כדי שיוכל לתת טעם בדברים שנתערב בהם (שהוא בערך אחד מששים), אם כן \u0003שלא בזמנו שלא במינו\u0004 מדוע \u0003מותר? הא יהיב טעמא\u0004 \u0005[הרי\u0006 הוא \u0005נותן טעם]\u0006 והאוכל מן התערובת מרגיש בטעמו של איסור!","\u0003אלא\u0004 ודאי מדובר כאן \u0003במשהו\u0004 חמץ בתוך כמות רבה של מצה. ומבארים את השיטה, מה שאמר רב \u0003חמץ בזמנו בין במינו בין שלא במינו אסור,\u0004 כאן \u0003רב\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 פסק הלכה זה: \u0003כל איסורין שבתורה\u0004 שנתערבו בהיתר, אם נתערב מין \u0003במינו\u0004 שאין דרך להבחין בדבר האיסור, הרי הוא אוסר \u0003במשהו,\u0004 כלומר בכל שיעור שיהיה. ואם נתערב \u0003שלא במינו\u0004 דנים אותו \u0003בנותן טעם.\u0004","\u0003רב\u0004 הוסיף וגם \u0003גזר\u0004 על \u0003חמץ בזמנו\u0004 שנתערב \u0003שלא במינו אטו\u0004 \u0005[משום]\u0006 \u0003מינו.\u0004 שכיון שחמץ שנתערב במינו אסור במשהו, אף בשלא במינו גזרו משום חומרת איסור חמץ שיהא אוסר במשהו. \u0003ו\u0004מה שסבר רב שחמץ \u0003שלא בזמנו\u0004 שנתערב \u0003במינו — אסור,\u0004 הרי זה \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 שחמץ לאחר הפסח אסור מן התורה, ולכן אף התערובת אסורה.","\u0003ו\u0004אם נתערב \u0003שלא במינו — מותר,\u0004 כי על \u0003שלא בזמנו ושלא במינו אטו\u0004 \u0005[משום]\u0006 \u0003מינו כולי האי לא גזרינן\u0004 \u0005[כל כך איננו גוזרים],\u0006 שכיון שלדעת רב כל איסור שנפל שלא במינו בטל אם אינו בנותן טעם, הרי אף חמץ לאחר הפסח כיון שהוא שלא בזמנו אין לאסור במשהו.","ואילו \u0003שמואל אמר\u0004 בהלכה זו כי \u0003חמץ בזמנו,\u0004 אם נתערב \u0003במינו — אסור, שלא במינו — מותר.\u0004 ואם היה זה \u0003שלא בזמנו, בין\u0004 שנתערב \u0003במינו בין\u0004 שנתערב \u0003שלא במינו — מותר.\u0004 ומבארים את שיטתו: \u0003חמץ בזמנו\u0004 אם נתערב \u0003במינו — אסור, שמואל\u0004 הלך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כי \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל איסורין שבתורה,\u0004 נתערב \u0003במינו — אסורין במשהו, שלא במינו — בנותן טעם\u0004 בלבד הוא שנאסר.","ואילו \u0003שלא במינן אטו\u0004 \u0005[משום]\u0006 זה שנפל לתוך \u0003מינן — לא גזר\u0004 בו שמואל. ואילו \u0003שלא בזמנו, בין\u0004 שנתערב \u0003במינן בין\u0004 שנתערב \u0003שלא במינן — מותרין,\u0004 והוא \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שחמץ שעבר עליו הפסח מותר.","\u0003ור' יוחנן אמר: חמץ בזמנו, בין\u0004 שנתערב \u0003במינו ובין\u0004 שנתערב \u0003שלא במינו — אסור\u0004 אם בו כדי שיהא \u0003נותן טעם\u0004 בתערובת. ואילו \u0003שלא בזמנו, בין\u0004 שנתערב \u0003במינן בין\u0004 שנתערב \u0003שלא במינן — מותר.\u0004","ומבארים: \u0003חמץ בזמנו בין\u0004 שנתערב \u0003במינו בין\u0004 שנתערב \u0003שלא במינו\u0004 אינו אסור אלא אם יש בו שיעור \u0003בנותן טעם\u0004 — לענין זה \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 כי \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל איסורין שבתורה\u0004 שנתערבו, \u0003בין\u0004 שנתערבו \u0003במינן בין\u0004 שנתערבו \u0003שלא במינן\u0004 — אוסרים \u0003ב\u0004כדי שיעור \u0003נותן טעם.\u0004 היו פחות מכן — בטלו. ואילו \u0003שלא בזמנו, בין במינו בין שלא במינו — מותרין,\u0004 שדעתו \u0003כר' שמעון,\u0004 שלשיטתו אין איסור תורה בחמץ שעבר עליו הפסח."],["\u0003אמר רבא: הלכתא\u0004 \u0005[הלכה]\u0006 פסוקה במחלוקת זו ש\u0003חמץ בזמנו, בין\u0004 שנתערב \u0003במינו בין\u0004 שנתערב \u0003שלא במינו — אסור\u0004 אפילו \u0003במשהו,\u0004 כשיטתו של \u0003רב. שלא בזמנו, בין\u0004 נתערב \u0003במינו בין\u0004 נתערב \u0003שלא במינו — מותר\u0004 אפילו בנותן טעם, \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שחמץ שעבר עליו הפסח מותר.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך]\u0006 שלשיטת ר' שמעון מותר חמץ לאחר זמנו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא\u0004 עצמו כי \u0003ר' שמעון קנסא קניס\u0004 \u0005[קנס קנס]\u0006 ואסר בהנאה חמץ שעבר עליו הפסח \u0003הואיל ועבר עליו\u0004 בימות החג \u0003ב\"בל יראה\" ו\"בל ימצא\"!\u0004","ומשיבים: \u0003הני מילי בעיניה\u0004 \u0005[דברים אלה\u0006 אמורים כשהחמץ \u0005בעינו],\u0006 \u0003אבל על ידי תערובת — לא\u0004 קנס, אף שהחמץ עדיין קיים. ומוסיפים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבא\u0004 בכך שפסק הלכה כר' שמעון \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 לומדים \u0005בבית]\u0006 \u0003רב נחמן, כי הוו נפקי שבעה יומי דפסחא\u0004 \u0005[כאשר היו יוצאים שבעת ימי הפסח]\u0006 במוצאי החג \u0003אמר לן\u0004 \u0005[\u0006היה \u0005אומר לנו]\u0006 רב נחמן: \u0003פוקו וזבינו חמירא דבני חילא\u0004 \u0005[צאו וקנו\u0006 את \u0005החמץ של הגוים]\u0006 שאפוהו באותו יום שהוא שביעי של פסח, הרי שסבר שחמץ של גוי שעבר עליו הפסח מותר אפילו באכילה.","\u0003אמר רב: קדירות\u0004 חרס שבישלו בהן חמץ \u0003בפסח ישברו,\u0004 שהרי בתוכן בלוע משהו מן החמץ ואסור לבשל בהן שוב מפני טעם האיסור. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 החמיר כל כך? \u0003לשהינהו\u0004 \u0005[שישהה]\u0006 את הקדירות עד ל\u0003אחר הפסח, וליעבד בהו\u0004 \u0005[ושיעשה,\u0006 יבשל \u0005בהן]\u0006 \u0003שלא במינן,\u0004 שהרי אף רב התיר חמץ שלא בזמנו שלא במינו במשהו לאחר הפסח! ומסבירים שלא רוצה לומר כן כי \u0003גזירה דילמא אתו למיעבד בהו\u0004 \u0005[שמא יבואו לעשות\u0006 לבשל, \u0005בהן]\u0006 \u0003במינו,\u0004 ויהא אסור בהנאה, ולכן גזר שישברו ולא יבואו לידי מכשול.","\u0003ושמואל אמר: לא ישברו\u0004 קדירות אלו, \u0003אבל משהי להו\u0004 \u0005[ישהו אותם]\u0006 \u0003לאחר זמנו\u0004 של פסח, \u0003ועביד בהו\u0004 \u0005[ועושה בהם]\u0006 \u0003בין במינו בין שלא במינו.\u0004","\u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר שמואל להנהו דמזבני כנדי\u0004 \u0005[לאותם המוכרים קדירות]\u0006 שהיו מפקיעים מחירי הקדירות לאחר הפסח: \u0003אשוו זביני אכנדיכי\u0004 \u0005[השוו\u0006 את \u0005המחיר על קדירותיכם]\u0006 כלומר: אל תפקיעו את המחירים, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תצייתו — \u0003דרשינא לכו\u0004 \u0005[אדרוש לכם\u0006 בפניכם\u0005]\u0006 שההלכה היא \u0003כר' שמעון,\u0004 שחמץ לאחר הפסח מותר בהנאה, וישאירו כל העם את קדירותיהם ולא יקנו מכם כלל קדירות חדשות אחר הפסח.","ושואלים: \u0003ולידרוש להו\u0004 \u0005[ושידרוש להם],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שמואל כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא]\u0006 כפי שנתבאר, ומדוע לא יפרסם ברבים שהלכה כמותו! ומשיבים: \u0003אתריה\u0004 \u0005[מקומו]\u0006 של \u0003רב הוה\u0004 \u0005[היה],\u0006 ולכתחילה אינו ראוי שידרוש ויפרסם במקומו של רב שלא כשיטתו, אבל כשראה שהם מפקיעים את המחירים איים עליהם שבכל זאת יפרסם הלכה זו.","מסופר: \u0003ההוא תנורא\u0004 \u0005[תנור אחד]\u0006 ש\u0003טחו ביה טיחיא\u0004 \u0005[בו שומן]\u0006 של בשר ואפו בו לחם, ונבלע בו משהו משומן הבשר. \u0003אסרה\u0004 \u0005[אסר]\u0006 \u0003רבא בר אהילאי למיכליה לריפתא\u0004 \u0005[לאכול את הלחם]\u0006 \u0003אפילו במילחא\u0004 \u0005[במלח]\u0006 ולא רק בחלב \u0003לעולם\u0004 אפילו כשיאפו בו פעם אחרת משום טעם הבשר שנבלע בו, \u0003דילמא אתי למיכליה בכותחא\u0004 \u0005[שמא יבוא לאכול אותו עם כותח]\u0006 תבלין שמעורב בו חלב, ונמצא אוכל בשר וחלב באחד.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: שנינו \u0003אין לשין את העיסה בחלב, ואם לש\u0004 את העיסה בחלב — \u0003כל הפת כולה אסורה\u0004 באכילה, \u0003מפני הרגל עבירה\u0004 שמא יבוא לאכול את הפת עם בשר ונמצא אוכל בשר וחלב יחד. ו\u0003כיוצא בו\u0004"],["\u0003אין טשין\u0004 (טחים, מורחים) \u0003את התנור באליה\u0004 של כבש מפני שהיא כבשר. \u0003ואם טש\u0004 בה את התנור — \u0003כל הפת כולה\u0004 שנאפתה בו \u0003אסורה,\u0004 שמא יאכלוהו בחלב \u0003עד שיסיק את התנור\u0004 ויתבער שומן זה. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003הוסק התנור\u0004 לאחר מכן — \u0003מיהא שרי\u0004 \u0005[על כל פנים מותר]\u0006 ואם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבא בר אהילאי\u0004 שאסר את התנור לעולם. ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ונדחו דבריו מההלכה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: וכי מאחר דאיתותב\u0004 \u0005[שהושבו]\u0006 הושארו בקושיה דברי \u0003רבא בר אהילאי, אמאי קאמר\u0004 \u0005[מדוע אמר]\u0006 \u0003רב: קדירות בפסח ישברו?\u0004 הרי יש להן תקנה כמו לתנורים על ידי הסקתן על האש עד שיתבער החמץ שבהן! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש להבדיל; \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003תנור של מתכת\u0004 הראוי להכשר לאחר הסקה, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בקדירה של חרס\u0004 שאין די לה בהסקה מאחר והחרס בולע יותר מאשר המתכת.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 \u0003בשל חרס\u0004 אלא \u0003זה\u0004 התנור — \u0003הסיקן מבפנים\u0004 שהרי מסיקים את התנור מבפנים ואופים בו מבפנים, והאש שבו מוציאה ושורפת את האיסור. \u0003וזה\u0004 הקדירות — \u0003הסיקן מבחוץ\u0004 והאיסור נבלע מבפנים ואינו יוצא על ידי האש. \u0003וכי תימא הכי נמי ליעבד ליה\u0004 \u0005[ואם תאמר כך גם כן יעשה להם\u0006 לקדירות\u0005]\u0006 \u0003הסקה מבפנים,\u0004 ועל ידי כך יוכשרו — מן הסתם הוא \u0003חייס\u0004 \u0005[חס]\u0006 \u0003עליה\u0004 על הקדירה להסיקה יפה \u0003משום דפקעה\u0004 \u0005[ש\u0006עשויה \u0005לפקוע]\u0006 ולכן יש לחשוש שלא יסיקה די צורכה.","ומסכמים: \u0003הלכך\u0004 \u0005[לכן]\u0006 על פי דברים אלה \u0003האי בוכיא\u0004 \u0005[תבנית זו]\u0006 העשויה מרעפי חרס שאופים עליה פת \u0003הסיקו מבחוץ הוא — ואסור, ואי מלייה גומרי\u0004 \u0005[ואם מילא אותם בגחלים\u0006 בוערות\u0005] —\u0006 \u0003שפיר דמי\u0004 \u0005[יפה הדבר]\u0006 ומותר על ידי הגחלים, שבבוכיא אין חוששים שמא תפקע שהרי תמיד מצויה בה אש, ואין לחשוש שמא לא יסיקנה כראוי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: הני סכיני בפסחא היכי עבדינן להו\u0004 \u0005[סכינים אלו בפסח איך עושים להן]\u0006 כיצד מכשירים אותן לצורך הפסח? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לדידי חדתא קא עבדינן\u0004 \u0005[בשבילי חדשות עושים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תינח מר\u0004 \u0005[נניח, אדוני]\u0006 ש\u0003אפשר ליה\u0004 \u0005[לו]\u0006 מפני עשירותו לקנות סכינים חדשות, ואולם מי ש\u0003לא אפשר ליה מאי\u0004 \u0005[מה]\u0006 יעשה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני],\u0006 \u0003כעין חדתא קאמינא\u0004 \u0005[חדשות אמרתי]\u0006 שלא התכוונתי שיש לקנות חדשות, אלא לנקותן היטב כעין חידוש הסכין, וכוונתי שיעשו כך: \u0003קתייהו בטינא ופרזלייהו בנורא\u0004 \u0005[\u0006מכניס את \u0005קתות\u0006 הסכינים העשויות עץ בתוך \u0005הטיט\u0006 שלא ישרפו, \u0005וברזלן,\u0006 ללבן, \u0005באש]\u0006 \u0003והדר מעיילנא לקתייהו ברותחין\u0004 \u0005[ואחר כך\u0006 אני חוזר ו\u0005מכניס את קתות ה\u0006סכינים במים \u0005רותחים]\u0006 להגעלה, וכך נפלט כל החמץ שייתכן שהיה בסכין. ופוסקים: \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 גם להב הסכין וגם קתו דיים בהגעלה במים \u0003רותחין ובכלי ראשון\u0004 כלומר, באותו כלי בו הורתחו המים ולא רותחים שנשפכו מכלי לכלי.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: עץ פרור\u0004 (כף שבוחשים בו הקדירה) \u0003מגעילו\u0004 כדי להוציא ממנו את האיסור במים \u0003רותחין ובכלי ראשון.\u0004 וקובעים: שהוא \u0003סבר\u0004 לפי הכלל: \u0003כבולעו כך פולטו\u0004 שבאותו אופן ודרגת חום שנבלע דבר בכלי, באותו אופן אף ייפלט מתוכו. ועץ הפרור שבלע חמץ כשהיה במים רותחים בכלי ראשון יפלוט את החמץ כשיבוא בשנית במים הרותחים שעל האש.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003אמימר: הני מאני דקוניא\u0004 \u0005[אותם כלי חרס מצופים],\u0006 \u0003מהו לאשתמושי בהו בפסחא\u0004 \u0005[להשתמש בהם בפסח]?\u0006 ומפרטים: הכלים \u0003ירוקא\u0004 \u0005[הירוקים]\u0006 ודאי \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה — ש\u0003ודאי\u0004 הם \u0003אסירי\u0004 \u0005[אסורים]\u0006 שציפויים אינו מונע מהם לספוג. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 הרי זה בכלים \u0003אוכמי וחיורי, מאי\u0004 \u0005[שחורים ולבנים, מה\u0006 הדין\u0005]?\u0006 ועוד: \u0003והיכא דאית בהו קרטופני\u0004 \u0005[ובמקום שיש בהם בקיעים],\u0006 בודאי \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, ש\u0003ודאי\u0004 הם \u0003אסירי\u0004 \u0005[אסורים],\u0006 שהחמץ נבלע בבקיעים אלה. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה באלה \u0003דשיעי, מאי\u0004 \u0005[שהם חלקים, מה\u0006 הדין\u0005]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזינא להו דמידייתי\u0004 \u0005[רואה אני אותם ש\u0006הם \u0005פולטים,\u0006 מזיעים\u0005]\u0006 מצידם החיצון משהו מן המשקה שבתוכם, \u0003אלמא: בלעי, ואסירי\u0004 \u0005[מכאן\u0006 ש\u0005בולעים ואסורים]\u0006 ולכן אין להם תקנה גם על ידי ניקוי. כי \u0003התורה העידה על כלי חרס\u0004 שבלע איסור \u0003שאינו יוצא מידי דופיו\u0004 (קלקולו) \u0003לעולם,\u0004 שבשאר כלים נתנה התורה תקנה במריקה ושטיפה, אבל כלי חרס נאמר בו רק נתיצה.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003שלענין יין נסך דדריש מרימר\u0004 בענין זה: \u0003מאני דקוניא\u0004 \u0005[כלי חרס מצופים]\u0006 \u0003בין אוכמא בין חיורי ובין ירוקי, שרי\u0004 \u0005[בין\u0006 שהוא \u0005שחור ובין\u0006 שהוא \u0005לבן ובין\u0006 שהוא \u0005ירוק מותר]\u0006 אם השתמשו בו ביין של גוים, \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 לחלק באופן זה, איסור \u0003יין נסך\u0004 הוא רק איסור מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ואילו \u0003חמץ\u0004 אסור מן התורה. והרי כלל בידינו: \u0003כל דתקון רבנן\u0004 \u0005[כל שתקנו חכמים] —\u0006 \u0003כעין דאורייתא תקון\u0004 \u0005[\u0006הכתוב \u0005בתורה תקנו]\u0006 שכיון שגזרו איסור בדבר אין הם עושים בו גזירות ותקנות שונות מאיסורים של תורה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 טעם ההבדל הוא כי \u0003זה,\u0004 בקדירות החמץ בפסח \u0003תשמישו על ידי חמין\u0004 ונבלע היטב. \u0003וזה\u0004 היין, \u0003תשמישו על ידי צונן\u0004 ואינו נבלע כל כך.","ועוד בענין כלי חמץ בפסח \u0003אמר רבא בר אבא אמר רב חייא בר אשי אמר שמואל: כל הכלים שנשתמשו בהן חמץ בצונן\u0004 שלא חממו כלל את הכלי — \u0003משתמש בהן מצה\u0004 שהחמץ לא נבלע שם ואינו נפלט במצה, \u0003חוץ מן בית שאור\u0004 מקום שהיו מניחים בו בקביעות את השאור שבו מחמיצים \u0003הואיל שחימוצו קשה\u0004 יש לשער שטעם החמץ נבלע בדפנות הכלי אפילו בצונן. \u0003אמר רב אשי: ובית חרוסת\u0004 מקום שבו מניחים את התבלינים החריפים המכילים קמח כדי לתבל את המאכל — \u0003כבית שאור שחימוצו קשה דמי\u0004 \u0005[נחשב].\u0006","\u0003אמר רבא: הני אגני\u0004 \u0005[אותן קדירות]\u0006 שבעיר \u0003מחוזא הואיל ותדירי למילש בהו חמירא\u0004 \u0005[ומצוי ללוש בהם חמץ]\u0006 \u0003ומשהו בהו חמירא\u0004 \u0005[ומשהים בהן חמץ]\u0006 \u0003כבית שאור שחימוצו קשה דמי\u0004 \u0005[נחשב]\u0006 ואסורות בפסח. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 הדבר\u0005]\u0006 הלוא הוא ממש כבית שאור, ומה חידש רבא? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כיון\u0004 שהכלים הללו \u0003רויחא, שליט בהו אוירא ולא בלעי\u0004 \u0005[מרווחים, שולט בהם האויר, ואינם בולעים]\u0006 כל כך כבית שאור שהוא קטן ומלא בשאור, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לחלק.","\u0003גוי שהלוה את ישראל על חמצו\u0004 שלווה ממנו הישראל כסף ונתן לו את חמצו למשכון והיה אצל הגוי עד \u0003אחר הפסח,\u0004 אם שילם אותו אדם מישראל בו את חובו — \u0003מותר\u0004 החמץ \u0003בהנאה,\u0004 כיון שהוברר הדבר שבזמן הפסח כבר לא היה שייך לישראל. ואילו \u0003ישראל שהלוה את גוי על חמצו\u0004 באותה דרך — הרי חמץ זה \u0003אחר הפסח אסור בהנאה.\u0004 שכיון שהוברר שהחמץ היה במשך הפסח של הישראל כפרעון חוב, הריהו נחשב כחמץ שעבר עליו הפסח ואסור בהנאה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 נחלקו אמוראים בשאלה זו: \u0003בעל חוב\u0004 מבחינת זכותו על החוב, \u0003אביי אמר: למפרע הוא גובה\u0004 שאם שיעבד הלוה את נכסיו למלוה ולא פרע, אומרים אנו שזכות המלוה על המשכון נחשבת כשלו מזמן ההלואה, ולא רק משעה שהנכסים עוברים בפועל לרשות המלוה. \u0003ורבא אמר:\u0004 לא, אלא \u0003מכאן ולהבא\u0004 משעת פרעון והלאה \u0003הוא גובה\u0004 שאין לו זכות כלשהי במשכון אלא משעת הפרעון. והמחלוקת היא כמובן לגבי פעולות שונות שנעשו בנכסים הללו בין שעת ההלואה לשעת הפרעון. ומסייגים את המחלוקת בכמה סייגים: \u0003כל היכא דאקדיש לוה וזבין לוה\u0004 \u0005[כל מקום שהקדיש הלוה\u0006 בינתיים את הקרקע הממושכנת \u0005או מכרה הלוה]\u0006 \u0003כולי עלמא לא פליגי דאתי מלוה וטריף\u0004 \u0005[הכל אינם חולקים שיכול המלוה לבוא ולטרוף]\u0006 כלומר, להפקיע את הרכוש מידי המחזיקים בו כעת, משום שיש לו משכנתא קודמת עליו"],["\u0003ואתי\u0004 \u0005[ו\u0006יכול \u0005לבוא]\u0006 ה\u0003מלוה ופריק\u0004 \u0005[ויפדה]\u0006 בסכום סמלי מן ההקדש, כלומר להפקיעו למעשה מרשות הקדש. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בכגון זה: \u0003מוסיף\u0004 המלוה \u0003עוד דינר\u0004 על סכום החוב \u0003ופודה את הנכסים האלו\u0004 שמעיקר הדין אינו צריך לפדות כלל. אלא כדי שלא יאמרו שדבר יוצא מן ההקדש בלא פדיון תיקנו שיעשה פדיון סמלי, בדינר אחד. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003דזבין\u0004 \u0005[\u0006כ\u0005שמכר]\u0006 \u0003מלוה, ו\u0004כן \u0003אם קדיש\u0004 \u0005[הקדיש]\u0006 \u0003מלוה\u0004 את הנכסים בתקופה שלפני זמן הפרעון.","\u0003אביי אמר: למפרע הוא גובה,\u0004 וטעמו: \u0003כיון דמטא זמניה ולא פרעיה, איגלאי מילתא למפרע דמעיקרא ברשותיה הוה קאי\u0004 \u0005[שהגיע זמנו ולא פרעו, התברר הדבר למפרע שמתחילה ברשותו\u0006 של המלוה \u0005היה עומד]\u0006 \u0003ושפיר אקדיש, ושפיר זבין\u0004 \u0005[ויפה הקדיש ויפה מכר].\u0006 ואילו \u0003רבא אמר: מכאן ולהבא הוא גובה,\u0004 וטעמו: \u0003כיון\u0004 ש\u0003אילו הוו ליה זוזי — הוה מסליק להו בזוזי\u0004 \u0005[היה לו\u0006 ללוה \u0005כסף היה מסלק את\u0006 חובו \u0005בכסף]\u0006 ולא היה כל קנין למלוה בקרקעות. \u0003אישתכח דהשתא קא קני\u0004 \u0005[נמצא שעכשיו\u0006 עם זמן הפרעון \u0005הוא קונה]\u0006 ולכן אינו יכול להקדיש או למכור.","לפני שמגיעים להבאת ראיות לצד זה או אחר, רוצים לברר: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך]?\u0006 והרי מדבריו במקום אחר נראה שלא כך סבר, כי \u0003אמר רמי בר חמא: ראובן שמכר שדה לשמעון באחריות,\u0004 כלומר בתנאי שכל נכסיו של ראובן אחראים לשמעון על מקח זה ואם יתברר שיש משכנתא על שדה זה יכול שמעון ליטול תמורתה נכס אחר \u0003וזקפן עליו במלוה,\u0004 ולא שילם שמעון את דמי השדה אלא נשאר חייב סכום זה. ובינתיים \u0003מת ראובן ואתא\u0004 \u0005[ובא]\u0006 \u0003בעל חוב\u0004 של \u0003ראובן\u0004 שהיה חובו מוקדם לזמן מכירה זו \u0003וטריף ליה\u0004 \u0005[ולקח את\u0006 הקרקע\u0005]\u0006 \u0003משמעון\u0004 מתוך שהיתה משועבדת לחוב זה. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003שמעון ופייסיה בזוזי\u0004 \u0005[ופייס\u0006 את המלוה הראשון \u0005בכסף]\u0006 ששילם את חובו כדי שיוותר על השדה.","עדיין \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דאתו\u0004 \u0005[\u0006שיכולים \u0005לבוא]\u0006 \u0003בני ראובן\u0004 המוכר \u0003ואמרי ליה\u0004 \u0005[ואומרים לו]\u0006 \u0003לשמעון\u0004 תן לנו את הכסף שאתה חייב לאבינו עבור השדה. ואם תתבע מאתנו עבור האחריות — איננו משלמים כי \u0003אנן מטלטלי שבק אבון גבך\u0004 \u0005[אנחנו, מטלטלים הניח אבינו אצלך]\u0006 אותו ממון שאתה חייב לנו תמורת השדה \u0003ומטלטלי דיתמי\u0004 \u0005[ומטלטלים של יתומים]\u0006 \u0003לבעל חוב לא משתעבדי\u0004 \u0005[משתעבדים]\u0006 ומכיון שכך לא היה לבעל חוב עלינו דבר ואתה שפרעת חוב זה גרמת לעצמך הפסד בכך.","\u0003ואמר רבא: אי\u0004 \u0005[אם]\u0006 \u0003פיקח שמעון\u0004 זה — \u0003מגבי להו\u0004 \u0005[ישלם להם]\u0006 בחובם לא כסף אלא \u0003ארעא\u0004 \u0005[קרקע].\u0006 וכיון שעתה יש בידם קרקע, יש מקום מהיכן להפרע את אחריות הנכסים של ראובן, \u0003והדר גבי לה מינייהו\u0004 \u0005[ויחזור ויגבה אותם מהם]\u0006 בשביל אחריות ראובן על השדה שנמכר. ש\u0003אמר רב נחמן: יתומים שגבו קרקע בחובת אביהם מבעל חוב אחד — בעל חוב\u0004 אחר \u0003חוזר וגובה אותה מהן\u0004 לפרעון התחיבויותיו של האב.","ולענייננו שלנו: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003\"למפרע הוא גובה\"\u0004 והשדה נחשב של המלוה אף לפני זמן הפרעון, \u0003אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003חוזר וגובה אותה מהן — דכמאן דגבו מחיים דאבוהון דמי\u0004 \u0005[שכמי שגבו מחיי אביהם הם נחשבים]\u0006 שאומרים אנו שהשדה שנתן שמעון בפרעון חובו התברר למפרע שהיה שייך לראובן משעה שנתחייב לו הקונה לשלם בעד השדה, ומשום כך יכול עכשיו שמעון לחזור ולגבות את השדה, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003\"מכאן ולהבא הוא גובה\" אמאי\u0004 \u0005[מדוע]\u0006 \u0003חוזר וגובה אותה מהן? הא הוי כמאן דזבין יתמי נכסי דמי\u0004 \u0005[הרי הוא כמי שקנו היתומים נכסים נחשב],\u0006 \u0003ואילו קני יתמי נכסי, מי קא משתעבדי לבעל חוב\u0004 \u0005[היו קונים היתומים נכסים\u0006 חדשים משלהם, \u0005האם היו משתעבדים לבעל חוב]\u0006 של אביהם? שהרי רק נכסי האב משועבדים לפרעון חובותיו! ואם כן הרי זו סתירה לשיטת רבא מדברי עצמו.","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דאמר להו\u0004 \u0005[ש\u0006יכול אותו שמעון \u0005לומר להם]\u0006 לבני ראובן; \u0003כי היכי דמשתעבדנא ליה לאבוכון\u0004 \u0005[כמו שאני משועבד לאביכם]\u0006 לשלם לו את חובו, \u0003משתעבדנא נמי\u0004 \u0005[משועבד אני גם כן]\u0006 \u0003לבעל חוב דאבוכון\u0004 \u0005[של אביכם].\u0006 וזאת, \u0003מ\u0004שיטתו של \u0003ר' נתן\u0004 הסבור כי מי שהלווה לאחד ולוה מאחר, משמש רק אמצעי בין המלוה הראשון והלווה השני, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: מנין לנושה בחבירו מנה וחבירו בחבירו, שמוציאין מזה\u0004 הלווה השני, \u0003ונותנין לזה,\u0004 המלוה הראשון, ואין צורך כלל להעביר את הכסף דרך אותו אדם שלוה מאחד והלוה לאחר. \u0003תלמוד לומר \"ונתן לאשר אשם לו\"\u0004 (במדבר ה, ז) משמע שיש להחזיר את החוב למי שהחוב בסופו של דבר שלו ואין הדבר קשור במחלוקת אם למפרע הוא גובה.","ומעתה רוצים להביא ראיות לשיטות החולקים. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003גוי שהלוה את ישראל על חמצו\u0004 ונשאר ברשות ישראל — \u0003אחר הפסח מותר בהנאה.\u0004 ונברר: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003\"למפרע הוא גובה\" — אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003מותר בהנאה,\u0004 משום שנתברר למפרע שהחמץ היה שייך לגוי.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003\"מכאן ולהבא הוא גובה\", אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותר בהנאה?\u0004 הלוא \u0003ברשותא\u0004 \u0005[ברשות]\u0006 \u0003ישראל הוה קאי\u0004 \u0005[היה עומד]\u0006 החמץ, ושלו היה, וכיון שכן — הריהו אסור בהנאה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כשהרהינו אצלו\u0004 שלא היה החמץ מצוי בבית הישראלי אלא היה ממושכן ומונח בבית הגוי, ובמקרה זה ודאי שהמשכון נחשב כשייך לגוי אלא אם כן החזיר הישראלי את חובו.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שמחלוקת זו \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו אף הם בסוגיה זו ששנינו: \u0003ישראל שהלוה לגוי על חמצו — לאחר הפסח אינו עובר, משום\u0004 (משמו של) \u0003ר' מאיר אמרו: עובר.\u0004 ומעירים: \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו]\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר\u0005]\u0006 \u0003סבר\u0004 שעובר משום שלדעתו \u0003למפרע הוא גובה,\u0004 ולכן התברר למפרע שהחמץ היה שלו וברשותו של הישראל בפסח, \u0003ומר\u0004 \u0005[וחכם זה\u0006 שהתיר\u0005]\u0006 \u0003סבר\u0004 ש\u0003מכאן ולהבא הוא גובה\u0004 ועדיין אינו ברשותו.","ודוחים: \u0003ותסברא\u0004 \u0005[וכי\u0006 יכול \u0005אתה לסבור]\u0006 כן? \u0003אימא סיפא\u0004 \u0005[אמור את סוף]\u0006 אותה ברייתא: \u0003אבל גוי שהלוה לישראל על חמצו — לאחר הפסח דברי הכל עובר. והא איפכא מיבעי ליה\u0004 \u0005[והרי ההיפך היה צריך להיות]\u0006 \u0003למאן\u0004 \u0005[למי]\u0006 ש\u0003אמר התם\u0004 \u0005[שם\u0006 בקטע הראשון\u0005]\u0006 \u0003\"אינו עובר\"\u0004 — \u0003הכא\u0004 \u0005[כאן]\u0006 צריך להיות \u0003עובר, למאן\u0004 \u0005[למי]\u0006 ש\u0003אמר התם\u0004 \u0005[שם]\u0006 \u0003\"עובר\"\u0004 — \u0003הכא\u0004 \u0005[כאן]\u0006 צריך היה להיות \u0003אינו עובר,\u0004 שהרי לפי עקרון זה מי שסבור שלמפרע הוא גובה צריך היה לומר שהחמץ שייך לגוי ואינו עובר עליו."],["\u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה \u0003כגון שהרהינו\u0004 \u0005[משכנו]\u0006 את החמץ \u0003אצלו, וקמיפלגי\u0004 \u0005[ונחלקו]\u0006 בדברי \u0003ר' יצחק.\u0004 ש\u0003אמר ר' יצחק: מנין לבעל חוב שקונה משכון\u0004 שנותנים לו, שהמשכון נחשב כל זמן היותו בידו כשלו לכל דבר — \u0003שנאמר\u0004 \"השב תשיב לו את העבוט כבוא השמש ושכב בשלמתו וברכך \u0003ולך תהיה צדקה\u0004 לפני ה' אלהיך\" (דברים כד, יג), ומכאן נסיק: אם המלוה \u0003אינו קונה משכון — צדקה מנין?\u0004 הרי אינו נותן כלום משלו! \u0003מכאן לבעל חוב שקונה משכון.\u0004","ובהלכה זו נחלקו בברייתא \u0003תנא קמא סבר: הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003רק\u0004 ב\u0003ישראל\u0004 שלקח משכון \u0003מישראל הוא דקרינא ביה\u0004 \u0005[שקוראים בו]\u0006 \u0003\"ולך תהיה צדקה\"\u0004 ואומרים שהמשכון הוא קניינו של המלוה, \u0003אבל ישראל מגוי,\u0004 שלא נאמר דבר במקרא על כגון זה \u0003לא קני\u0004 \u0005[אינו קונה]\u0006 את משכונו והמשכון שייך עדיין לבעליו הגוי, ולכן בפסח אינו עובר עליו.","ואילו \u0003ר' מאיר סבר, קל וחומר:\u0004 אם \u0003ישראל מישראל קני\u0004 \u0005[קונה]\u0006 משכון, \u0003ישראל מגוי לא כל שכן\u0004 שהוא קונה. \u0003אבל גוי שהלוה את ישראל על חמצו\u0004 — \u0003אחר הפסח דברי הכל עובר. התם\u0004 \u0005[שם]\u0006 \u0003ודאי גוי מישראל לא קני\u0004 \u0005[אינו קונה]\u0006 את המשכון ואינו נקנה לו אלא בדרכי הקנין המקובלות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003גוי שהלוה את ישראל על חמצו — אחר הפסח מותר בהנאה. נהי נמי\u0004 \u0005[אמנם גם כן]\u0006 כפי שאמרת מדובר \u0003דהרהינו\u0004 \u0005[שמשכנו]\u0006 לחמץ \u0003אצלו, הא אמרת\u0004 \u0005[הרי אמרת]\u0006 ש\u0003גוי מישראל לא קני\u0004 אינו קונה משכון ומדוע יהא מותר בהנאה? והרי חמץ ישראל הוא! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שקנה הגוי ואין הישראל עובר עליו — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 אם איני פורע את חובי יהיה המשכון קנוי לך \u0003\"מעכשיו\", והא\u0004 \u0005[וזה]\u0006 שאסור ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"מעכשיו\".\u0004","\u0003ומנא תימרא דשני ליה בין היכא דאמר\u0004 \u0005[ומנין תאמר ששונה לו\u0006 לדין אפילו אם הרהינו \u0005בין מקום שאמר]\u0006 \u0003\"מעכשיו\" ובין היכא דלא אמר\u0004 \u0005[ובין מקום שלא אמר\u0006 לו\u0005]\u0006 \u0003\"מעכשיו\" דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גוי שהרהין\u0004 \u0005[שמישכן]\u0006 \u0003פת פורני\u0004 (פת שנאפתה בתנור) \u0003אצל ישראל — אינו עובר\u0004 עליו משום \"בל יראה ובל ימצא\", \u0003ואם אמר לו \"הגעתיך\"\u0004 מעכשיו, שאם לא אפרע לך חובי הרי המשכון שלך מעכשיו \u0003עובר. מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[במה שונה ההתחלה ובמה שונה הסוף]\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תשמע מכאן]\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003היכא\u0004 \u0005[מקום]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"מעכשיו\" להיכא\u0004 \u0005[למקום]\u0006 ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"מעכשיו\".\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: היתה \u0003חנות של ישראל ומלאי\u0004 (הדברים הנמכרים בחנות) \u0003של ישראל, ופועלי גוים נכנסין לשם\u0004 מזמן לזמן — \u0003חמץ שנמצא שם לאחר הפסח אסור בהנאה, ואין צריך לומר\u0004 שאסור \u0003באכילה\u0004 משום שחזקה שהחמץ שייך לחנות ולבעליה. ולהיפך, אם היתה \u0003חנות של גוי ומלאי של גוי ופועלי ישראל נכנסין ויוצאין לשם\u0004 סברה ש\u0003חמץ שנמצא שם אחר הפסח\u0004 לא של ישראל היה אלא של גוי היה והוא \u0003מותר באכילה, ואין צריך לומר\u0004 שמותר \u0003בהנאה.\u0004","\u0003חמץ שנפלה עליו מפולת הרי הוא כמבוער\u0004 ואין צורך לחפור ולהוציאו משם כדי לשורפו. \u0003רבן שמעון בן גמליאל אומר: כל\u0004 שהחמץ טמון באופן \u0003שאין הכלב יכול לחפש אחריו\u0004 — הרי זה כמבוער.","\u0003אמר רב חסדא:\u0004 אף שאין צורך לחפור ולהוציא את החמץ, בכל זאת \u0003צריך שיבטל\u0004 את החמץ \u0003בלבו\u0004 שמא יתגלה החמץ בתוך הפסח ויעבור עליו. \u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003כמה חפישת הכלב\u0004 כדי עומק של \u0003שלשה טפחים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר שמואל כספים\u0004 של פקדון \u0003אין להם שמירה\u0004 שאפשר יהיה לומר שהם מצויים במקום בטוח ומשומר מן הגנבים ויהיה שומר חינם פטור על גניבתם, \u0003אלא\u0004 כשמטמינים אותם \u0003בקרקע מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 לענין זה להטמינן \u0003שלשה טפחים\u0004 בעומק הקרקע \u0003או לא? אמר ליה\u0004 \u0005[לו]\u0006 \u0003הכא\u0004 \u0005[כאן\u0006 בפסח\u0005]\u0006 \u0003משום ריחא\u0004 \u0005[ריח]\u0006 הלחם \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003שלשה טפחים,\u0004 שחוש הריח של הכלב חד רק עד עומק שלושה טפחים. \u0003התם\u0004 \u0005[שם\u0006 בכספים\u0005]\u0006 \u0003משום איכסויי מעינא\u0004 \u0005[הכיסוי מעין]\u0006 \u0003הוא, ולא בעי\u0004 \u0005[צריך]\u0006 \u0003שלשה\u0004 טפחים, שהכלב ובעלי חיים לא יחטטום ובני אדם כבר אינם רואים אותם. ושואלים: אם כן \u0003כמה? אמר רפרם בר פפא\u0004 מהעיר \u0003סיכרא:\u0004 עומק \u0003טפח\u0004 אחד מספיק להטמנת כספים.","\u0003האוכל תרומת חמץ בפסח,\u0004 אם היה זה \u0003בשוגג\u0004 שלא ידע שהיא תרומה — \u0003משלם קרן וחומש,\u0004 כי האוכל תרומה בשוגג משלם לכהן את מחיר התרומה ומוסיף עליה עוד חמישית, אף על פי שתרומת חמץ אינה שווה בפסח מאומה. ואם אכל \u0003במזיד\u0004 שידע שהוא אוכל תרומה — \u0003פטור מתשלומין\u0004 בכלל, ואם היתה זו תרומה טמאה אף אינו משלם עבור \u0003דמי עצים\u0004 שהנהנה מתרומה טמאה משלם עבור שוויה כחומר הסקה, שמותר להשתמש בה להסקה, אבל חמץ בפסח — אסור בהנאה ואין לו כל ערך כספי.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת תרומות \u0003האוכל תרומה בשוגג — משלם\u0004 עבורה \u0003קרן וחומש, אחד האוכל ואחד השותה\u0004"],["\u0003ואחד הסך\u0004 גופו בשמן תרומה, \u0003אחד תרומה טמאה ואחד תרומה טהורה — משלם חומש\u0004 ואם שגג ואכל, את חומש הקנס הזה — משלם \u0003חומשא דחומשא\u0004 \u0005[חומש של חומש]\u0006 שהחומש עצמו נעשה לענין זה כתרומה עצמה, שצריך לשלם חומש עליו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו בדיני תרומה: \u0003כשהוא משלם\u0004 את התרומה, \u0003לפי מדה משלם או לפי דמים\u0004 (שוויים הכספי) \u0003משלם?\u0004 ומבארים: \u0003כל היכא דמעיקרא שויא ארבעה זוזי ולבסוף שויא זוזא\u0004 \u0005[כל מקום שמתחילה שוה\u0006 התרומה \u0005ארבעה דינרים ולבסוף שוה\u0006 רק \u0005דינר\u0006 אחד\u0005]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל,\u0006 תסתפק\u0005]\u0006 \u0003לך,\u0004 ש\u0003ודאי כדמעיקרא\u0004 \u0005[כמתחילה]\u0006 הוא \u0003משלם, לפי\u0004 ה\u0003דמים\u0004 שעלה הדבר קודם לכן, ש\u0003לא גרע\u0004 \u0005[גרוע]\u0006 הוא \u0003מגזלן,\u0004 כלומר אין מקילים בדינו מבדין גזלן הגוזל מחבירו, ולאו דוקא מהקדש. \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הגזלנין משלמין כשעת הגזלה\u0004 גם אם ירד ערכו של הדבר הנגזל לאחר מכן,","\u0003כי תיבעי לך\u0004 \u0005[כאשר תישאל,\u0006 תסתפק, \u0005לך]\u0006 \u0003דמעיקרא שויא זוזא ולבסוף שויא ארבעה\u0004 \u0005[שבתחילה\u0006 היתה \u0005שוה דינר, ולבסוף שוה ארבעה\u0006 דינרים\u0005]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם \u0003לפי מדה משלם, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 גזבר ההקדש: \u0003גריוא אכל גריוא משלם\u0004 \u0005[סאה אכלת סאה תשלם]\u0006 ואפילו עלה המחיר. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לפי דמים משלם, בזוזא\u0004 \u0005[ב\u0006שווה \u0005דינר]\u0006 \u0003אכל בזוזא\u0004 \u0005[ב\u0006שווה \u0005דינר]\u0006 \u0003משלם.\u0004","\u0003אמר רב יוסף: תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, ששנינו בברייתא: \u0003אכל גרוגרות\u0004 (תאנים יבשות) של תרומה \u0003ושילם לו\u0004 תמורתם \u0003תמרים — תבא עליו ברכה\u0004 שמחיר התמרים גבוה יותר. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003לפי מדה משלם — אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003תבא עליו ברכה, דאכיל גריוא דגרוגרות דשויא זוזא\u0004 \u0005[שאכל סאה של גרוגרות ששוה דינר]\u0006 \u0003וקא יהיב גריוא דתמרים דשויא ארבעה\u0004 \u0005[ונותן לו סאה של תמרים השוה ארבעה\u0006 דינרים\u0005]\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003לפי דמים משלם אמאי\u0004 \u0005[מדוע]\u0006 \u0003תבא עליו ברכה? בזוזא אכל בזוזא קא משלם\u0004 \u0005[ב\u0006שוה \u0005דינר אכל\u0006 — \u0005בדינר משלם]\u0006 ומה הרבותה בדבר?","\u0003אמר אביי: לעולם\u0004 אפשר לפרש ש\u0003לפי דמים משלם, ואמאי\u0004 \u0005[ומדוע]\u0006 אומרים \u0003תבא עליו ברכה — דאכל מידי דלא קפיץ עליה זביניה\u0004 \u0005[שאכל דבר שאין קופצים עליו הקונים]\u0006 \u0003וקא משלם מידי דקפיץ עליה זביניה\u0004 \u0005[ומשלם בדבר שקופצים עליו קונים]\u0006 ולכן אף שלא הוסיף כלל במחיר, נוח לכהן לקבל תשלום כזה משום שיכול לקבל עבורו כסף מיד אם רצונו בכך.","ושוב מנסים להוכיח; \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003האוכל תרומת חמץ בפסח, בשוגג — משלם קרן וחומש, אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003לפי מדה משלם שפיר\u0004 \u0005[יפה],\u0006 מובן. שהאוכל סאה של תרומה חוזר ומשלם סאה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003לפי דמים משלם,\u0004 וכי \u0003חמץ בפסח בר\u0004 \u0005[בן]\u0006 \u0003דמים הוא?\u0004 והרי אינו שוה מאומה! ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 אף לחמץ בפסח יש ערך, \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 לפי \u0005מי היא] —\u0006 לפי שיטת \u0003ר' יוסי הגלילי היא\u0004 ש\u0003אמר חמץ\u0004 אף \u0003בפסח מותר בהנאה.\u0004","ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור את סופה\u0006 של המשנה\u0005]:\u0006 \u0003במזיד פטור מן התשלומין ומדמי עצים\u0004 ואף שעשה במזיד, \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יוסי הגלילי,\u0004 אם כן גם אם נפטר משום כך מחומש, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור מן התשלומין ומדמי עצים\u0004 ולא ישלם את הקרן, שהרי גרם לכהן נזק כשאר גזלנים?!","ומשיבים: \u0003סבר לה כר' נחוניא בן הקנה דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נחוניא בן הקנה היה עושה את יום הכפורים כשבת לתשלומים,\u0004 שלדעתו לא רק החייב מיתה בידי אדם (כמחלל שבת) איננו משלם עבור מה שהזיק בשעת מעשה העבירה שחייבו מיתה, אלא גם מי שמתחייב מיתה בידי שמים (כרת) כגון מחלל יום הכפורים איננו משלם עבור מה שהזיק באותה שעה. ולכן, האוכל חמץ של אחר בפסח במזיד, כיון שהוא מתחייב כרת — נפטר מכל תשלום.","ומעירים: השאלה אם לפי מידה או לפי דמים משלם היא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו כבר בבעיה זו, ששנינו בתוספתא: \u0003האוכל תרומת חמץ בפסח\u0004 בין שוגג בין מזיד — \u0003פטור מן התשלומין ומדמי עצים\u0004 — אלו \u0003דברי ר' עקיבא,\u0004 ואילו \u0003ר' יוחנן בן נורי מחייב. אמר לו ר' עקיבא לר' יוחנן בן נורי: וכי מה הנאה יש לו בה?\u0004 כלומר, הלוא תרומה זו אסורה בהנאה ואינה שווה מאומה, ומה יכול הכהן ליהנות בה? \u0003אמר לו ר' יוחנן בן נורי לר' עקיבא: ומה הנאה יש לאוכל תרומה טמאה בשאר כל ימות השנה — שמשלם,\u0004 והרי גם תרומה טמאה אסורה באכילה, ואף על פי כן זר שאכלה חייב קרן וחומש!","\u0003אמר לו:\u0004 יש לחלק; \u0003לא, אם אמרת בתרומה טמאה בשאר ימות השנה, שאף על פי שאין לו בה היתר אכילה,\u0004 מכל מקום \u0003יש לו בה\u0004 לכהן \u0003היתר הסקה\u0004 שיכול לשרפה ולהנות ממנה תוך כדי כך, \u0003תאמר בזה\u0004 בתרומת חמץ בפסח — \u0003שאין לו בה לא היתר אכילה ולא היתר הסקה, הא\u0004 \u0005[הרי]\u0006 \u0003למה זה דומה לתרומת תותים וענבים שנטמאה, שאין לו בה לא היתר אכילה ולא היתר הסקה\u0004 שהרי אינם ראויים להסקה.","ומוסיפים: \u0003במה דברים אמורים\u0004 שנחלקו בפיצוי עבור התרומה — \u0003במפריש תרומה\u0004 ראויה \u0003והחמיצה\u0004 בתוך הפסח, \u0003אבל מפריש תרומת חמץ\u0004 בפסח — \u0003דברי הכל אינה קדושה\u0004 שהרי נתן דבר שאיננו שוה מאומה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 את הכתוב \u0003\"\u0004ואיש כי יאכל קודש בשגגה ויסף חמישיתו עליו \u0003ונתן לכהן את הקדש\"\u0004 (ויקרא כב, יד) דורשים: שנותן לכהן \u0003דבר הראוי להיות קדש, פרט לאוכל תרומת חמץ בפסח, שפטור מן התשלומים\u0004 ואף \u0003מדמי עצים,\u0004 אלו \u0003דברי ר' אליעזר בן יעקב, ור' אלעזר חסמא מחייב. אמר לו ר' אליעזר בן יעקב לר' אלעזר חסמא: וכי מה הנאה יש לו בה\u0004 בתרומת חמץ? והלוא אינה שוה מאומה! \u0003אמר לו ר' אלעזר חסמא לר' אליעזר בן יעקב: וכי מה הנאה יש לו\u0004 לזר ה\u0003אוכל תרומה טמאה בשאר ימות השנה שמשלם?\u0004","\u0003אמר לו:\u0004 יש לחלק \u0003לא אם אמרת בתרומה טמאה בשאר ימות השנה שאף על פי שאין לו בה היתר אכילה\u0004 אבל \u0003יש לו בה היתר הסקה, תאמר בזו — שאין לו בה לא היתר אכילה\u0004 ואין לו בה \u0003היתר הסקה\u0004 שהרי חמץ אסור בהנאה! \u0003אמר לו: אף בזו\u0004 בתרומת חמץ בפסח \u0003יש לו בה היתר הסקה, שאם רצה הכהן — מריצה\u0004 (זורקה) \u0003לפני כלבו, או מסיקה תחת תבשילו\u0004 שלדעת ר' אלעזר חסמא חמץ בפסח מותר בהנאה כשיטת ר' יוסי הגלילי."],["\u0003אמר אביי: ר' אליעזר בן יעקב, ור' עקיבא ור' יוחנן בן נורי כולהו סבירא להו\u0004 \u0005[כולם סבורים]\u0006 כי \u0003חמץ בפסח אסור בהנאה, ובהא פליגי\u0004 \u0005[וב\u0006בעיה \u0005זו נחלקו],\u0006 ש\u0003ר' עקיבא סבר: לפי דמים משלם\u0004 ולכן עבור תרומת חמץ אינו משלם כלל, \u0003ור' יוחנן בן נורי סבר: לפי מדה משלם\u0004 ומחזיר כמדתה, אפילו תרומת חמץ בפסח,","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן שכך הוא\u0005]\u0006 שהרי אין דרך אחרת להסביר את השיטות! ודוחים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ר' יוחנן בן נורי נמי\u0004 \u0005[גם כן]\u0006 \u0003כר' עקיבא סבירא ליה\u0004 \u0005[סבור]\u0006 לענין זה ש\u0003אמר\u0004 אף הוא \u0003לפי דמים משלם. והתם היינו טעמא דקא מחייב\u0004 \u0005[ושם זהו הטעם שהוא מחייב] —\u0006 \u0003משום דסבר לה כר' יוסי הגלילי,\u0004 ש\u0003אמר: חמץ בפסח מותר בהנאה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שר' יוחנן בן נורי סובר שחמץ בפסח אסור בהנאה.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן]\u0006 אולי באמת כך סבור ר' יוחנן בן נורי? ודוחים: \u0003אם כן,\u0004 אם סבור הוא שחמץ מותר בהנאה \u0003נהדר ליה\u0004 \u0005[שישיב לו]\u0006 \u0003ר' יוחנן בן נורי לר' עקיבא כי היכי דמהדר ליה\u0004 \u0005[כפי שהשיב לו]\u0006 \u0003ר' אלעזר חסמא לר' אליעזר בן יעקב\u0004 שחמץ זה נותנו לכלבו. וכיון שלא השיב תשובה זו — משמע שאף הוא מסכים שחמץ בפסח אסור בהנאה.","כיון שדובר בדיני המזיק את התרומה מביאים עוד דיון בנושא זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 זר \u0003האוכל כזית תרומה — משלם קרן וחומש, אבא שאול אומר:\u0004 אינו מתחייב בתשלום \u0003עד שיהא בו\u0004 בדבר שאכל \u0003שוה פרוטה.\u0004 ומבארים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה טעמו של התנא הראשון]\u0006 הוא מתבסס על האמור \u0003\"ואיש כי יאכל קדש בשגגה\u0004 ויסף חמישיתו עליו ונתן לכהן את הקודש\u0003\"\u0004 (ויקרא כב, יד), \u0003ואכילה\u0004 שיעורה הקטן ביותר הוא \u0003בכזית,\u0004","\u0003ואבא שאול מאי טעמא\u0004 \u0005[מה טעמו]?\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בפסוק זה \u0003\"ונתן\" ואין נתינה פחות משוה פרוטה.\u0004 ושואלים: \u0003ואידך נמי הא כתיב\u0004 \u0005[והאחר\u0006 אבא שאול, \u0005גם כן הלוא כתוב]\u0006 \u0003\"יאכל\"\u0004 ומשמעו שיהא בו שיעור אכילה שהוא בכזית! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 ללמדנו \u0003פרט למזיק הוא דאתא\u0004 \u0005[שבא]\u0006 כלומר, שהמזיק תרומה אפילו בשוגג בלא ליהנות ממנה איננו מוסיף את החומש אלא משלם קרן בלבד, כי גזירת הכתוב היא שרק האוכל יוסיף חומש.","ושואלים: \u0003ותנא קמא\u0004 \u0005[ו\u0006לדעת התנא \u0005הראשון]\u0006 \u0003הכתיב\u0004 \u0005[והרי נאמר]\u0006 בכל זאת \u0003\"ונתן\"!\u0004 ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו]\u0006 לענין \u0003דבר הראוי להיות קדש\u0004 שאין דבר מתקדש מתחילה בקדושת תרומה אם אינו שוה משהו, \u0003פרט לאוכל תרומת חמץ בפסח,\u0004 שכיון שאיננה שוה מאומה ואי אפשר להקדישה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003האוכל תרומה פחות מכזית — משלם את הקרן ואינו משלם את החומש.\u0004 ודנים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הענין\u0005]?\u0006 \u0003אי דלית ביה\u0004 \u0005[אם אין בו]\u0006 באוכל זה \u0003שוה פרוטה — קרן נמי\u0004 \u0005[גם כן]\u0006 \u0003לא לישלם\u0004 \u0005[ישלם]\u0006 שהרי זה פחות מן השיעור הראוי להתחייב בו, \u0003ואי דאית\u0004 \u0005[ואם יש]\u0006 \u0003בה שוה פרוטה\u0004 — \u0003חומש נמי לישלם\u0004 \u0005[גם כן שישלם]!\u0006 ומשיבים: \u0003לעולם\u0004 תפרש \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה שוה פרוטה, ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003כיון דלית ביה\u0004 \u0005[שאין בו]\u0006 בדבר הנאכל \u0003כזית\u0004 — \u0003משלם\u0004 רק את \u0003הקרן ואינו משלם את החומש.\u0004","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003רב פפא הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שאמרנו ש\u0003לא כאבא שאול\u0004 היא, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כאבא שאול האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003כיון שיש בה שוה פרוטה\u0004 חייב לשלם, \u0003אף על גב דלית ביה\u0004 \u0005[אף על פי שאין בה]\u0006 \u0003כזית אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא\u0004 אין זו הוכחה: \u0003אפילו תימא\u0004 \u0005[תאמרו]\u0006 שהלכה זו כ\u0003אבא שאול, אבא שאול תרתי בעי\u0004 \u0005[שתים הוא צריך]\u0006 כלומר הוא דורש שיהא גם שיעור כזית וגם שווה פרוטה.","ושואלים: \u0003ומי בעי\u0004 \u0005[והאם\u0006 אמנם \u0005צריך]\u0006 \u0003אבא שאול תרתי\u0004 \u0005[שתים]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אבא שאול אומר: את שיש בו שוה פרוטה — חייב בתשלומין\u0004 עליו, ו\u0003את שאין בו שוה פרוטה — אינו חייב בתשלומין. אמרו לו\u0004 חכמים: \u0003לא אמרו\u0004 דין של \u0003שוה פרוטה אלא לענין מעילה\u0004 בקודש \u0003בלבד, אבל לתרומה — אינו חייב עד שיהא בו כזית. ואם איתא\u0004 \u0005[ואם\u0006 אמנם \u0005יש]\u0006 מקום להנחה שאבא שאול דורש את שני הדברים כאחד לשון זו איננה מדוייקת, ולא היו חכמים צריכים לומר \"עד שיהא בו כזית\", אלא \u0003\"כיון שיש בו כזית\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר].\u0006 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 היא ונדחו דברי רב פפא.","ומעירים: כי \u0003אף רב פפא הדר ביה\u0004 \u0005[חזר בו]\u0006 מפירוש זה. \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]\u0006 \"נפש כי תמעול מעל וחטאה בשגגה מקדשי ה' והביא את אשמו לה' איל תמים מן הצאן בערכך כסף שקלים בשקל הקודש לאשם\" (ויקרא ה, טו), ומפרשים: \u0003\"וחטאה בשגגה\" — פרט למזיד\u0004 במעילה. \u0003והלא דין הוא\u0004 שלכאורה אפשר ללמוד את הדבר בקל וחומר, \u0003ומה שאר מצו‍ת\u0004 לא תעשה \u0003שחייב בהן כרת\u0004 במזיד — \u0003פוטר בהן את המזיד\u0004 מלהביא קרבן, \u0003מעילה שאין בה כרת\u0004 במזיד \u0003אינו דין שפטר\u0004 בה \u0003את המזיד?\u0004","ודוחים: \u0003לא אם אמרת בשאר מצו‍ת — שכן לא חייב בהן מיתה\u0004 בידי שמים, \u0003תאמר במעילה\u0004 שאין בה כרת, אבל עונשה \u0003שחייב בה מיתה\u0004 בידי שמים, וכיון שאין ללמוד מן הסברה \u0003תלמוד לומר\u0004 מן הכתוב עצמו \u0003\"בשגגה\" — פרט למזיד.\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרב חייא בר אבין\u0004 תמוהה ברייתא זו: כי \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003מעיקרא אלימא ליה כרת\u0004 \u0005[מתחילה היה תקיף,\u0006 חמור \u0005בעיניו\u0006 עונש \u0005הכרת]\u0006 שהניח בפשטות שאיסור מעילה שאין עונשו כרת קל יותר. \u0003ולבסוף אלימא ליה מיתה\u0004 \u0005[תקיפה בעיניו המיתה]\u0006 שהוא אומר שאין ללמוד משאר עבירות שאין עונשן מיתה בידי שמים!","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 רב חייא בר אבין, אפשר להחזיק בדעה המקובלת כי כרת חמור ו\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003לא אם אמרת בשאר מצו‍ת — שכן לא חייב בהן\u0004 אדם \u0003מיתה\u0004 על אכילת \u0003פחות מכזית, תאמר במעילה — שחייב בה מיתה\u0004 אף \u0003בפחות מכזית. ואמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: \u0003תנוח דעתך שהנחת את דעתי\u0004 ותרצת לי קושי חמור זה. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 רב חייא בר אבין: \u0003מאי ניחותא\u0004 \u0005[מה הנוחות\u0006 בדבר זה\u0005]\u0006 \u0003דרבה ורב ששת שדו ביה נרגא\u0004 \u0005[קוצצים אותו בגרזן]\u0006 כלומר הם מפריכים את תירוצי זה, וטוענים כנגדו: \u0003מאן שמעת ליה דאמר\u0004 \u0005[מי\u0006 איזה חכם \u0005שמעת אותו שאמר]\u0006"],["שדינו של מי ש\u0003הזיד במעילה במיתה\u0004 — שיטת \u0003רבי היא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הזיד במעילה, רבי אומר:\u0004 דינו \u0003במיתה\u0004 בידי שמים, \u0003וחכמים אומרים: באזהרה,\u0004 שעובר על מצוות לא תעשה בלבד שדינו כרגיל במלקות.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רבי,\u0004 מהיכן למד דבר זה שאינו מפורש בכתוב? \u0003אמר ר' אבהו: גמר\u0004 \u0005[למד]\u0006 בגזירה שוה \u0003\"חטא\" \"חטא\" מתרומה,\u0004 שנאמר \"חטא\" במעילה \"נפש כי תמעול מעל וחטאה בשגגה מקדשי ה'\" (ויקרא ה, טו), ונאמר \"חטא\" בתרומה \"ולא ישאו עליו חטא ומתו בו כי יחללוהו (ויקרא כב, ט), ולמד: \u0003מה תרומה\u0004 עונשה \u0003במיתה — אף מעילה\u0004 עונשה \u0003במיתה.\u0004","\u0003ומינה\u0004 \u0005[ומתוך]\u0006 גזירה שוה זו עצמה נלמד שיש להשוות את הדברים בשלימות: \u0003מה תרומה\u0004 אין נענש עליה אלא \u0003בכזית אף מעילה\u0004 אין נענש עליה אלא \u0003בכזית,\u0004 ואם כן, אי אפשר לפרש את הברייתא לפי שיטת אבא שאול!","\u0003ומתקיף לה\u0004 \u0005[ומקשה עליה]\u0006 \u0003רב פפא\u0004 על דחיה זו של רב ששת ורבה: \u0003ממאי\u0004 \u0005[מהיכן]\u0006 יודע אתה ש\u0003רבי כרבנן סבירא ליה\u0004 \u0005[כ\u0006שיטת \u0005חכמים הוא סבור]\u0006 שתרומה אין חייבים עליה אלא בכזית? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003כאבא שאול סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר יש בה שוה פרוטה אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה כזית\u0004 חייב עליה. ואם סבור רבי כאבא שאול, ממילא אפשר לפרש היטב את הברייתא התמוהה וללמוד מעילה מתרומה, שאם יש בה שוה פרוטה אף אם אין בה כזית — חייב, ואין לדחות איפוא את תירוצו של רב חייא בר אבין.","ולענין שהזכרנו קודם; \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב פפא הוא\u0004 עצמו ש\u0003אמר\u0004 ש\u0003אבא שאול תרתי בעי\u0004 \u0005[שתים הוא צריך]\u0006 גם שוה פרוטה וגם שיעור כזית, \u0003אלא שמע מינה: הדר ביה\u0004 \u0005[אלא למד מכאן שחזר בו]\u0006 רב פפא מהסברו זה לשיטת אבא שאול.","\u0003מר בריה דרבנא אמר\u0004 שאת הקושי בברייתא לענין מעילה אפשר לפרש כך \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כלומר, יש לתקן את הלשון: \u0003לא אם אמרת בשאר מצו‍ת — שלא עשה בהן\u0004 וחייב קרבן את העושה מלאכה בשוגג \u0003שאין מתכוין\u0004 לאותה מלאכה, כמו את העושה מלאכה בשוגג ו\u0003מתכוין\u0004 לאותה מלאכה, שהרי \u0003אם נתכוין\u0004 בשבת \u0003לחתוך\u0004 דבר שהוא \u0003תלוש\u0004 ואין איסור תורה כשחותכו \u0003וחתך\u0004 בטעות \u0003את המחובר\u0004 לקרקע, הרי הוא \u0003פטור\u0004 כיון שלא נתכוון לעבירה, \u0003תאמר במעילה\u0004 שמחמירים בה, \u0003שאם נתכוין להתחמם בגיזי\u0004 צמר \u0003חולין\u0004 ובשל טעות או חוסר ידיעה \u0003נתחמם בגיזי עולה — שמעל,\u0004 הרי שחמורה מעילה מעבירות אחרות שעוברים בה אף ללא כל ידיעה וכוונה.","\u0003רב נחמן בר יצחק אמר: הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין את הברייתא: \u0003לא אם אמרת בשאר מצו‍ת, שכן לא מתחייב בהן שאין מתעסק\u0004 בדבר המותר ולבסוף שגג באיסור \u0003כמתעסק,\u0004 כגון אם נשוה להלכות שבת \u0003שאם נתכוין להגביה את\u0004 הדבר \u0003התלוש\u0004 ממקומו, ונזדמן שבסכין שבידו \u0003חתך\u0004 אגב כך \u0003את המחובר — שפטור\u0004 כיון שלא התכוון כלל לעשיה זו. \u0003תאמר במעילה, שאם הושיט ידו לכלי ליטול חפץ\u0004 ושלא במתכוון ושלא בידיעתו \u0003סך ידו בשמן של קודש — שמעל\u0004 ולכן הרי שחמורה מעילה משאר עבירות, שאפילו המתעסק בדבר אחר ובתוך כך מעל — הרי זה חייב בקרבן.","בברייתא שצוטטה קודם \u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003במה דברים אמורים — במפריש תרומה והחמיצה\u0004 בפסח ואכלה, שנחלקו האם צריך לשלם עבורה אם לאו, \u0003אבל הפריש חמץ תרומה — דברי הכל אינה קדושה\u0004 תרומה זו.","מתחילה שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שהמפריש דבר שאין בו ערך איננו נתפס בקדושת תרומה? \u0003אמר רב נחמן בר יצחק: אמר קרא\u0004 \"ראשית דגנך תירושך ויצהרך וראשית גז צאנך תתן לו\" (דברים יח, ד), ונדייק מן המקרא \u0003\"תתן לו\" — ולא לאורו.\u0004 כלומר, יש לתת לכהן דבר שיוכל להשתמש בו, ולא שהוא צריך לשורפו, שאפילו לדעת המתירים שימוש בחמץ בפסח על ידי הנאה, הכל מודים שאסור באכילה ואין מפרישים דבר כגון זה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 שנינו: \u0003אין תורמין מן\u0004 התרומה \u0003הטמאה\u0004 עבור תרומה \u0003טהורה, ואם תרם בשוגג\u0004 — \u0003תרומתו תרומה. ואמאי\u0004 \u0005[ומדוע]\u0006 תהא זו תרומה? \u0003לימא\u0004 \u0005[שיאמר]\u0006 הכהן: הרי לא נתקיים \u0003\"לו\" ולא לאורו,\u0004 שתרומה טמאה ראויה רק לשריפה, ואיננה איפוא תרומה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בתרומה טמאה \u0003היתה לו שעת הכושר\u0004 שהרי היתה שעה מסויימת בה היתה התבואה טהורה וראויה וכשרה להיות תרומה. \u0003הכא\u0004 \u0005[כאן]\u0006 בחמץ \u0003לא היתה לו שעת הכושר.\u0004","ושואלים: וחמץ ש\u0003לא היתה לו שעת הכושר\u0004 אפילו בפסח \u0003היכי דמי\u0004 \u0005[איך יכול להיות]\u0006 \u0003כגון דאחמיץ\u0004 \u0005[שהחמיץ]\u0006 \u0003ב\u0004היותו עדיין \u0003מחובר\u0004 לקרקע וכל זמן חיבורו עדיין אינו ראוי להיעשות תרומה, \u0003אבל\u0004 אם \u0003אחמיץ\u0004 \u0005[החמיץ]\u0006 \u0003בתלוש — הכי נמי דקדשא\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שקדשה]\u0006 תרומה זו אף כי מלשון הברייתא נראה שכל תרומת חמץ אינה תרומה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 הדבר למרות התמיהה. וכמליצת הכתוב \u0003\"בגזירת עירין פתגמא ובמאמר קדישין שאלתא\"\u0004 (דניאל ד, יד) \u0005[בגזירת המלאכים הדבר ובמאמר הקדושים השאלה],\u0006 \u0003וכן מורין\u0004 בבית המדרש \u0003כוותי\u0004 \u0005[כמותי,\u0006 כשיטתי\u0005]\u0006 למרות התמיהה שבדבר.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 לשם \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004"],["\u0003אמר: אמר קרא \"ראשית\"\u0004 משמעו — \u0003ששיריה ניכרין לישראל\u0004 כלומר שנשאר גם חלק אחר, הראוי להיאכל לישראל, \u0003ויצתה\u0004 תרומה \u0003זו שאין שיריה ניכרין\u0004 שהרי כולה חמץ, ולכן אף לאחר שנתרמה התרומה, אסורים שייריה באכילה ולכן אין להפריש ממנו תרומה.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אחא בר רב עויא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא ויתיב\u0004 \u0005[וישב]\u0006 \u0003ואמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: ענבים שנטמאו — דורכן\u0004 בשיעור \u0003פחות פחות מכביצה, ויינן\u0004 היוצא מהן \u0003כשר לנסכין\u0004 שלא נטמא כלל, וכשר אף לקדשים. \u0003אלמא קסבר\u0004 \u0005[מכאן סבור הוא]\u0006 ר' יוחנן: \u0003משקין מיפקד פקידי\u0004 \u0005[מופקדים,\u0006 שמורים בענב\u0005]\u0006 שהמיץ שבענבים אינו נחשב כחלק מגופם של הענבים אלא כאילו היה רק שמור בתוכם כבכלי קיבול, ולכן \u0003לאימת קא מיטמאי\u0004 \u0005[מתי נטמאים]\u0006 המשקין, היין, מן הענבים — \u0003לכי סחיט להו\u0004 \u0005[כאשר סוחט אותם]\u0006 אבל קודם לכן היה המיץ שבענב טהור שלא הוא אלא בשר הענב נטמא. אולם \u0003לכי סחיט להו ליתיה לשיעוריה\u0004 \u0005[כאשר סוחט אותם אין כאן\u0006 בבשר הענב \u0005שיעורו\u0006 הראוי\u0005]\u0006 שבפחות מכביצה אינו מטמא טומאת אוכלין.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 \u0003כביצה\u0004 שלימה \u0003נמי\u0004 \u0005[גם כן]\u0006 יסחוט שהרי אינו יכול להיטמא? \u0003דהתנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 \u0003טמא מת שסחט זיתים וענבים\u0004 על ידי פשוטי כל עץ \u0003כביצה מכוונת\u0004 (בדיוק) ולא נגע במשקים עצמם — \u0003טהורין,\u0004 שכאשר ייסחט המיץ מהם לא יהא בבשרם עוד שיעור כביצה. ומדוע לא התיר ר' יוחנן אלא בפחות מביצה? ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר במקרה של \u0003דאי עבד\u0004 \u0005[שאם עשה,\u0006 שכבר נעשה מעשה\u0005],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003לכתחלה.\u0004 ולכתחילה אין עושים אלא בפחות מכביצה, \u0003גזירה דילמא אתי למיעבד\u0004 \u0005[שמא יבוא לעשות]\u0006 \u0003יותר מכביצה,\u0004 ואז ייטמא הכל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: מאן ציית\u0004 \u0005[מי יציית\u0006 יקשיב] \u0003לך ולר' יוחנן רבך\u0004 בענין זה? \u0003וכי טומאה שבהן\u0004 שבמיץ הענבים, \u0003להיכן הלכה? אלמא קא סבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור הוא]\u0006 רב חסדא: \u0003משקין מיבלע בליעי\u0004 \u0005[מובלעים]\u0006 בתוך הענב וכחלק ממנו הם. \u0003וכיון דאיטמו ליה אוכלא\u0004 \u0005[שנטמא לו האוכל]\u0006 בשר הענב, \u0003איטמו ליה\u0004 \u0005[נטמאו להם]\u0006 אף ה\u0003משקין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא: \u0003ואת לא תיסברא\u0004 \u0005[ואתה אינך סבור]\u0006 ש\u0003משקין\u0004 רק \u0003מיפקד פקידי\u0004 \u0005[מופקדים,\u0006 שמורים\u0005]\u0006 הם בתוך הענב? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003טמא מת שסחט זיתים וענבים\u0004 אם היתה מידתם \u0003מכוונת כביצה — טהורין. אי אמרת בשלמא מיפקד פקידי\u0004 \u0005[נניח אם אומר אתה\u0006 שהמשקין רק \u0005מופקדים\u0006 שם\u0005] —\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003טהורין\u0004 הם, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003מיבלע בליעי\u0004 \u0005[\u0006שהמשקין \u0005מובלעים\u0006 שם\u0005]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 הם \u0003טהורין?\u0004 שבשעה שנטמא בשר הענב, נטמאו אף המשקים המחוברים ובלועים בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בענבים שלא הוכשרו\u0004 לטומאה, שלא נפלו עליהם משקים להכשירם לכך. \u0003לאימת מתכשרי, לכי סחיט להו\u0004 \u0005[מתי מוכשרים הם\u0006 לקבל טומאה, \u0005כאשר סוחט אותם]\u0006 והמיץ יוצא ומכשירם. ואולם \u0003כי סחיט להו בציר להו שיעורא\u0004 \u0005[כאשר הוא סוחט אותם מתמעט להם שיעורם]\u0006 מכביצה ושוב אינם ראויים להיטמא, \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כן],\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003הא למה זה דומה — לתרומת תותין, זיתים וענבים שנטמאה, שאין לו בה לא היתר אכילה ולא היתר הסקה,\u0004 ואולם לפי מה שאמר ר' יוחנן \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003היתר אכילה נמי אית ביה\u0004 \u0005[גם כן יש בו],\u0006 \u0003דאי בעי\u0004 \u0005[שאם ירצה]\u0006 \u0003דריך להו\u0004 \u0005[ידרוך אותם]\u0006 \u0003פחות פחות מכביצה\u0004 ויהיו מותרים אף לאוכלם.","\u0003אמר רבא:\u0004 אפשר לדחות ראיה זו, שאמנם עקרונית אפשר לעשות תקנה זו, אלא \u0003גזירה דילמא אתי בהו\u0004 \u0005[שמא יבוא בהם]\u0006 \u0003לידי תקלה\u0004 שאם ישהה את הפירות הללו ישכח ויאכל תרומה טמאה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ומי חיישינן\u0004 \u0005[והאם חוששים אנו]\u0006 \u0003לתקלה\u0004 כגון זו? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מדליקין בפת ובשמן של תרומה שנטמאת,\u0004 משמע שאיננו חוששים שמא בינתיים ישכח ויבוא לאכול מהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: כשהתירו \u0003פת\u0004 — מדובר ש\u0003זריק ליה\u0004 \u0005[שזורק אותה]\u0006 \u0003בין העצים\u0004 העשויים להסקה ונמאסת, ושוב אינה ראויה לאכילה. \u0003שמן של תרומה — רמי ליה\u0004 \u0005[משליך אותה]\u0006 \u0003בכלי מאוס\u0004 שלא יבואו לשתות ממנה.","\u0003גופא\u0004 \u0005[לגוף]\u0006 הלכה זו שנינו: \u0003מדליקין בפת ובשמן של תרומה שנטמאת.\u0004 וכן הוסיפו חכמים הגבלה, \u0003אביי אמר\u0004 אותה \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה, ורבא אמר\u0004 בשם חכמים \u0003דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' יצחק בר מרתא אמר רב הונא: לא שנו\u0004 שמסיקים \u0003אלא\u0004 ב\u0003פת\u0004 ממש, \u0003אבל חיטי\u0004 \u0005[\u0006ב\u0005חיטים]\u0006 שנטמאו \u0003לא\u0004 מסיקים, \u0003שמא יבא בהן לידי תקלה\u0004 שישכח ויאכלן, שהרי חיטים אינן נמאסות מאכילה על ידי הנחתן במקום מאוס. \u0003ור' יוחנן אמר: אפילו חיטי\u0004 \u0005[חיטים]\u0006 יכול להשתמש בהם להסקה. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע\u0006 מתיר\u0005]?\u0006 \u0003ניחוש דילמא אתי בהן\u0004 \u0005[נחשוש שמא יבוא בהן]\u0006 \u0003לידי תקלה?\u0004 ומתרצים כפי ש\u0003אמר רב אשי\u0004 בענין אחר:"],["\u0003בשליקתא ומאיסתא\u0004 \u0005[בשלוקות ומאוסות],\u0006 שמבשלן לאחר שנטמאו ואחר כך משליכן במקום מאוס שאין לחשוש שמא יבוא לאוכלן, \u0003הכא נמי בשליקתא ומאיסתא\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005בשלוקות ומאוסות].\u0006 ושואלים: \u0003והיכא איתמר\u0004 \u0005[והיכן נאמרה]\u0006 במקור הלכה זו של \u0003רב אשי? אהא\u0004 \u0005[על זו]\u0006 ש\u0003אמר רבי אבין בר רב אחא אמר ר' יצחק: אבא שאול גבל\u0004 (האיש המגבל את הבצק) \u0003של בית רבי היה, והיו מחמין\u0004 \u0005[מחממים]\u0006 \u0003לו\u0004 מים \u0003חמין\u0004 לגיבול על ידי שהיו שורפים \u0003חיטין של תרומה טמאה,\u0004 שהיו קונים אותם מן הכהנים במחיר מוזל כדי \u0003ללוש בהן עיסה בטהרה.\u0004 ושאלו: \u0003אמאי\u0004 \u0005[מדוע]\u0006 עשו כן? \u0003ניחוש דילמא אתי בהו\u0004 \u0005[נחשוש שמא יבוא בהן]\u0006 \u0003לידי תקלה\u0004 ושמא בטעות יקחו מן החיטין הללו ויאכלום, על זה \u0003אמר רב אשי\u0004 שמדובר \u0003בשליקתא ומאיסתא\u0004 \u0005[בשלוקות ומאוסות]\u0006 שלא יבואו לאוכלן, ואינן ראויות אלא להסקה.","כיון שדובר בדרכי השימוש בתרומה טמאה, מביאים עוד הלכות שונות בנושא זה. מסופר, \u0003אביי בר אבין ור' חנניא בר אבין תנו\u0004 \u0005[שנו]\u0006 במסכת \u0003תרומות בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רבה. פגע בהו\u0004 \u0005[פגש אותם]\u0006 \u0003רבא בר מתנה, אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי אמריתו\u0004 \u0005[מה אומרים אתם]\u0006 מה דברי חידוש שמעתם במסכת \u0003תרומות\u0004 שלומדים \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003מר\u0004 \u0005[אדוננו,\u0006 רבה\u0005]?\u0006 א \u0003מרו ליה\u0004 \u0005[לו]:\u0006 \u0003ומאי קשיא לך\u0004 \u0005[ומה קשה לך]\u0006 שוודאי שואל אתה שאלה זו ביחס לבעיה שאתה מתקשה בה, \u0003אמר להו תנן\u0004 \u0005[להם שנינו\u0006 במשנה\u0005]\u0006 במסכת תרומות: \u0003שתילי תרומות שנטמאו ושתלן, טהורים מלטמא\u0004 שכיון ששתלם בטלה טומאתם, \u0003ואסורין מלאכול בתרומה,\u0004 והשאלה היא: \u0003וכי מאחר שטהורין מלטמא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אסורים מלאכול?\u0004 שהרי הן מעתה כשאר תרומה טהורה.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבה\u0004 בפירוש הדבר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אסורין\u0004 מלאכול — משמעו ש\u0003אסורין לזרים.\u0004 שמי שאינו כהן אסור לאכול אותם, לא מפני הטומאה אלא מפני קדושת תרומה שבהן שאף ששתלם לא פקעה מהן קדושתם. על תירוץ זה הקשה רבא בר מתנה: אם כן \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בהלכה זו — ש\u0003גידולי תרומה תרומה\u0004 שאף הגידולים יש בהם קדושת תרומה, אולם אם כן אין בכך כל חידוש, הרי \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה במפורש: \u0003גידולי תרומה תרומה\u0004 ומה הטעם בחזרה על הלכה ידועה?!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003גידולי גידולין,\u0004 שפה מדובר לא בגידולי התרומה עצמה אלא בגידולי גידולים — בצמחים חדשים שצמחו מתוך גידולי תרומה הראשונים, \u0003 ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו] \u0006 \u0003בדבר שאין זרעו כלה,\u0004 כלומר במקרה שזרע צמח שאינו נרקב באדמה אלא רק מוסיף וגדל בה כגון בצלים או שומים, שבאלה אף גידולי גידולים אסורים. הרי \u0003הא נמי תנינא\u0004 \u0005[זה גם כן שנינו\u0006 במשנה\u0005]:\u0006 \u0003הטבל\u0004 (תבואה שהתחייבה במעשר ולא הופרשו ממנה תרומות ומעשרות) — \u0003גידוליו מותרין,\u0004 אימתי — \u0003בדבר שזרעו כלה. אבל בדבר שאין זרעו כלה — אפילו גידולי גידולין אסורין באכילה\u0004 עד שיעשרם. ואם כן אף בדין זה אין כל חידוש ואין טעם איפוא להשמיעו במשנה נוספת. \u0003אישתיקו\u0004 \u0005[שתקו]\u0006 ולא מצאו תשובה.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מידי שמיע לך בהא\u0004 \u0005[וכי דבר שמעת ב\u0006ענין \u0005זה]\u0006 ושמא אתה יודע תירוץ לדבר? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אסורין — אסורין לכהנים,\u0004 וטעם האיסור — \u0003הואיל ואיפסילו להו\u0004 \u0005[ונפסלו להם]\u0006 \u0003בהיסח הדעת,\u0004 שדבר של תרומה או קודש שאין שומרים אותו ומסיחים את הדעת מלשומרו נחשב כטמא. ואם כן, אף שתילי תרומה אלה, כיון שנטמאו פעם ראשונה — הסיחו דעת מהם, ולכן אף כשגדלו פסולים משום היסח הדעת.","ושואלים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר היסח הדעת פסול הגוף הוי\u0004 \u0005[הוא],\u0006 כלומר שפסול היסח הדעת אינו נובע מתוך חשש טומאה אלא הוא ענין פסול לעצמו. שגזרו שדבר קודש שלא נשמר נפסל, אף אם ברור שלא נטמא. ולשיטה זו \u0003שפיר\u0004 \u0005[יפה]\u0006 מדוע פסולים הגידולים, \u0003אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר היסח הדעת פסול טומאה הוי\u0004 \u0005[הוא]\u0006 שאנו חוששים רק שמא נטמא, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?!\u0006 שהרי במשנה זו אמרנו שעל ידי שתילה נטהרו השתילים אפילו מטומאה ודאית, כל שכן שנטהרו מחשש טומאה שבהיסח הדעת!","כיון שעסקו בנושא מביאים מה \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בשאלה זו: \u0003היסח הדעת\u0004 מה מהותו? \u0003ר' יוחנן אמר: פסול טומאה הוי\u0004 \u0005[הוא]\u0006 שחוששים שמא נטמא החפץ בלא יודעין ור' \u0003שמעון בן לקיש אמר: פסול הגוף הוי\u0004 \u0005[הוא]\u0006 ופסול כשלעצמו.","ומבארים משהו מתוצאות המחלוקת העקרונית הזו: \u0003ר' יוחנן אמר: פסול טומאה הוי\u0004 \u0005[הוא]\u0006 \u0003שאם יבא אליהו ויטהרנה\u0004 שיאמר בבירור שבחפץ זה לא נגעה טומאה — \u0003שומעין לו\u0004 ומטהרים, שהרי לא פסלנו אלא מתוך חוסר ידיעת העובדות. ואילו \u0003ר' שמעון בן לקיש אומר: פסול הגוף הוי\u0004 \u0005[הוא],\u0006 \u0003שאם יבא אליהו ויטהרנה — אין שומעין לו,\u0004 שכן אין הדבר תלוי בשאלה האם נטמא או לא.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש\u0004 ממה ששנינו בתוספתא, \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא אומר: לול\u0004 (כעין חור) \u0003קטן היה בין כבש\u0004 (השיפוע שעולים בו אל המזבח) \u0003למזבח, במערבו של כבש, ששם היו זורקים פסולי חטאת העוף\u0004 שנפסלו בשל חששות שונים כגון בשל היסח הדעת, כדי \u0003שתעובר צורתם,\u0004 שיתקלקלו כליל בגלל שהייתם שם עד הבוקר הבא, ואז בודאי נפסלים כי הושארו (לנו) מעבר לזמן הראוי להם ודינם בשריפה מן התורה, ואז \u0003יוצאין לבית השריפה.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהיסח הדעת \u0003פסול טומאה הוי\u0004 \u0005[הוא],\u0006 \u0003משום הכי בעי\u0004 \u0005[כך צריך]\u0006 ב\u0003עיבור צורה,\u0004 שכן פסולי החטאת פסולים רק מספק, ו\u0003שמא יבא אליהו ויטהרנה, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003פסול הגוף\u0004 הוא, אם כן \u0003למה לי עיבור צורה?\u0004 דיו בטומאת היסח הדעת שהיתה בו ואינו צריך לעיבור צורה עוד, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003זה הכלל:\u0004"],["\u0003כל\u0004 קרבן \u0003שפסולו\u0004 הוא \u0003בגופו\u0004 בגוף הבשר — \u0003ישרף מיד,\u0004 ואם היה פסולו \u0003בדם\u0004 וכגון שנשפך, או שהיה פסולו \u0003בבעלים\u0004 וכגון שנטמאו — \u0003תעובר צורתן ויוצאין לבית השריפה. אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 ר' ישמעאל בנו של ר' יוחנן בן ברוקה כשיטת ה\u0003תנא\u0004 שנשנו דבריו \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבה בר אבוה הוא\u0004 ש\u0003אמר: אפילו פיגול טעון עיבור צורה.\u0004 שאפילו פסול כזה שבתורה נאמר במפורש שיש לשורפו, גם הוא טעון שתעובר צורתו עד למחרת.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 מברייתא אחרת, שנינו: \u0003נטמא או שנפסל הבשר, או שיצא חוץ לקלעים\u0004 (חוץ מאותן מחיצות, תחומים שראוי לו להיות בהם), \u0003ר' אליעזר אומר: יזרוק\u0004 את הדם של אותם הקרבנות, שלדעתו אין זריקת הדם תלויה כלל בבשר הקרבנות, \u0003ר' יהושע אומר: לא יזרוק\u0004 שאין זריקת הדם אלא אם כן הבשר קיים וכשר לקרבן. \u0003ומודה ר' יהושע שאם זרק\u0004 את הדם בכל זאת — \u0003הורצה\u0004 הקרבן.","ומעתה נברר \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003נפסל\u0004 זה שנזכר כאן? \u0003לאו\u0004 \u0005[האם לא]\u0006 שנפסל \u0003בהיסח הדעת?\u0004 שהרי פסול טומאה ויציאה מחוץ לקלעים נאמרו במפורש! \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהיסח הדעת \u0003פסול טומאה הוי\u0004 \u0005[הוא],\u0006 \u0003היינו דמשכחת לה דמרצי\u0004 \u0005[זהו שמצאנו אותה\u0006 אפשרות להכשיר מפני טעם \u0005שמרצה]\u0006 \u0003ציץ, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003פסול הגוף הוי\u0004 \u0005[הוא]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003הורצה\u0004 קרבן זה לדעת ר' יהושע? הלוא פסול הוא!","ודחה ריש לקיש: לא, פסול זה אינו פסול היסח הדעת אלא \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003נפסל\u0004 ששנינו, משמעו \u0003נפסל בטבול יום\u0004 כי טבול יום הנוגע בדבר אינו גורם לו טומאה (לטמא אחרים) אלא רק פוסלו (טומאה רק לעצמו). ושואלים: \u0003אי הכי היינו\u0004 \u0005[אם כך הרי זה]\u0006 כשאר \u0003טמא!\u0004 ומה ההבדל בין טומאה זו וטומאה אחרת שכבר נשנתה קודם בברייתא? ומשיבים: \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003טמא\u0004 נמנו כאן, טומאה גמורה המטמאה גם אחרים, ופסול טומאה שהיא טומאה של הדבר עצמו בלבד.","\u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רבין\u0004 לארץ ישראל \u0003אמרה לשמעתיה קמיה\u0004 \u0005[אמר את ההלכה\u0006 הזו של רב ששת \u0005לפני]\u0006 \u0003ר' ירמיה, ואמר\u0004 ר' ירמיה: \u0003בבלאי טפשאי\u0004 \u0005[בבליים טפשים],\u0006 \u0003משום דיתבי בארעא דחשוכא אמריתון שמעתתא דמחשכו\u0004 \u0005[שיושבים בארץ חשוכה אומרים אתם הלכות חשוכות],\u0006 וכי \u0003לא שמיע לכו הא\u0004 \u0005[שמעתם\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר' שמעון בן לקיש משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אושעיא:\u0004","\u0003מי החג\u0004 מים של ניסוך המים בחג הסוכות שנשאבו מבעוד יום בכלי כדי לנסכם למחרת ו\u0003נטמאו,\u0004 אם \u0003השיקן\u0004 כלומר הכניסם בתוך מקוה מים טהורים באופן שהמים שבכלי נוגעים (משיקים) למי המקוה, \u0003ואחר כך הקדישן\u0004 — \u0003טהורין, הקדישן ואחר כך השיקן\u0004 — \u0003טמאים.\u0004","ויש לשאול: \u0003מכדי\u0004 \u0005[הרי]\u0006 אופן זה של טהרת המים הוא כעין \u0003זריעה נינהו\u0004 \u0005[אותם],\u0006 שאנו דנים את המים בהשקתם וחיבורם למי המקוה כזרעים שנזרעו באדמה, שחזרו למקומם הראשון ומשום כך נטהרים. ואם כן \u0003מה לי השיקן ואחר כך הקדישן, מה לי הקדישן ואחר כך השיקן? אלמא\u0004 \u0005[מכאן]\u0006 נלמד כי: \u0003אין זריעה להקדש\u0004 שדבר של הקדש אין לסמוך בו על טהרה זו שבדרך זריעה. ואם כן אף \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003אין זריעה לתרומה\u0004 שאין טומאת התרומה מתבטלת בזריעה ולכן אפשר להסביר את הברייתא שגידולי התרומה אסורים לזרים מטעם תרומה.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב דימי וקאמר לה להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 של רב אושעיא לענין השקה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 האם מה שאמר רב אושעיא שאין השקה מועילה בהקדש הוא רק כאשר \u0003הקדישן\u0004 את המים והכניסם \u0003בכלי\u0004 שרת \u0003קאמר\u0004 \u0005[אמר],\u0006 \u0003אבל\u0004 אם הקדישם רק על ידי דיבור \u0003בפה לא עבוד רבנן\u0004 \u0005[עשו חכמים]\u0006 \u0003מעלה\u0004 יתירה בהם, והם נטהרים בהשקה כשאר משקים שנטמאו. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004קדושת \u0003פה נמי עבוד רבנן\u0004 \u0005[גם כן עשו חכמים]\u0006 \u0003מעלה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי: \u0003זו לא שמעתי,\u0004 אבל \u0003כיוצא בה שמעתי.\u0004 ש\u0003אמר ר' אבהו אמר ר' יוחנן: ענבים שנטמאו, דרכן ואחר כך הקדישן — טהורין,\u0004 שלשיטתו אין היין שבענב נטמא על ידי בשר הפרי. \u0003הקדישן ואחר כך דרכן — טמאין,\u0004 שעשו חכמים מעלה בקדשים שייחשבו אף המשקים טמאים. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ענבים,\u0004 ש\u0003קדושת פה נינהו\u0004 \u0005[הם]\u0006 שהרי אם מונחים הענבים בתוך כלי שרת אינם קדשים בכך אלא על ידי הקדשתם בפה, \u0003ואפילו הכי, עבוד רבנן\u0004 \u0005[כך, עשו חכמים]\u0006 \u0003מעלה\u0004 שלא ייחשבו טהורים לאחר הקדשתם.","\u0003אמר רב יוסף:\u0004 אין להוכיח מכאן, \u0003ענבים קאמרת\u0004 \u0005[אומר אתה]\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בענבים של תרומה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ש\u0003קדושת פה דידהו\u0004 \u0005[שלהם]\u0006 \u0003כקדושת כלי דמיא\u0004 \u0005[נחשבת]\u0006 שהרי בהפרשה לתרומה אין קידוש התרומה נעשה בכלי. \u0003אבל הני דבעי\u0004 \u0005[אלה,\u0006 כגון מי הנסכים, \u0005שצריכים]\u0006 \u0003כלי\u0004 להקדישם קדושה נוספת, אם הקדישם \u0003בפה לא עבוד רבנן\u0004 \u0005[עשו חכמים]\u0006 \u0003מעלה,\u0004 ואם כן אין לפתור את שאלתו של אביי.","על ההלכה שאמר ר' יוחנן, בטהרת יין היוצא מענבים שנטמאו, תוהים: \u0003\"דרכן\" — ואפילו טובא\u0004 \u0005[הרבה]\u0006 ענבים יחד?! \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: ענבים שנטמאו — דורכן פחות פחות מכביצה,\u0004 שכן אז אין בענבים כדי שיעור לטמא טומאת אוכלים. ואילו מדבריו כאן משמע שאפשר לדרוך כל כמות של ענבים!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ זה: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר שדרכן \u0003פחות פחות מכביצה. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003התם\u0004 \u0005[שם]\u0006 מדובר ש\u0003נגעו להו\u0004 \u0005[להם]\u0006 הענבים בדבר שהוא \u0003ראשון\u0004 לטומאה, \u0003דהוו להו אינהו\u0004 \u0005[שנעשו הם עצמם]\u0006 \u0003שני\u0004 ומשקה הנוגע בשני הריהו נעשה מדברי חכמים ראשון לטומאה. ולכן יש להיזהר שלא לדרוך יותר מכביצה. \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר ש\u0003נגעו בשני\u0004 לטומאה \u0003דהוו להו\u0004 \u0005[שנעשו להם]\u0006 \u0003שלישי\u0004 והמשקה היוצא מהם ונוגע בהם אינו נטמא כלל.","\u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אף אנחנו גם כן שנינו]\u0006 שעשו חכמים מעלה בטהרת קדשים. ששנינו: נאמר \u0003\"\u0004ולקחו לטמא מעפר שריפת החטאת \u0003ונתן עליו מים חיים אל כלי\"\u0004 (במדבר יט, יז), ואמרו: מים חיים — \u0003שתהא חיותן בכלי\u0004 שצריך שהמים יישאבו במישרין מן המעין אל הכלי בו מקדשים אותם. ומצד שני נאמר \u0003\"ונתן\"\u0004 ומשמעו אף שישפוך את המים אל כלי אחר, \u0003אלמא\u0004 \u0005[מכאן]\u0006 שמים אלה \u0003תלושין נינהו\u0004 \u0005[הם]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מחוברין נינהו\u0004 \u0005[הם]\u0006 שכפי שאמרנו צריכה להיות חיותם בכלי — מן המעיין!"],["\u0003אלא\u0004 יש לומר כי זו היא רק \u0003מעלה,\u0004 שמן התורה מותר שיהיו המים שאובים בכלי אחד ויכולים להינתן לקידושם בכלי אחר, והוסיפו חכמים הידור ומעלה בהם שבאותו כלי שנשאבים בו מן המעין בו יהיו מתקדשים, ואף מצאו רמז וסמך לדבריהם בפסוק שבתורה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מעלה\u0004 עשו חכמים שדבר מוקדש שנטמא לא תהא לו טהרה אף בזריעה.","\u0003אמר רב שימי בר אשי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כעין זו: זב או מצורע שנטהר, \u0003טבל\u0004 ביום \u0003ועלה — מיד אוכל במעשר. העריב שמשו\u0004 ובא הלילה — \u0003אוכל בתרומה.\u0004 ונדייק: \u0003בתרומה — אין\u0004 \u0005[כן]\u0006 אוכל, אבל \u0003בקדשים — לא. אמאי\u0004 \u0005[מדוע]\u0006 הלוא \u0003טהור הוא,\u0004 ומדוע לא יאכל? \u0003אלא, מעלה\u0004 עשו חכמים בקדשים שלא יאכלם עד לאחר הבאת קרבן טהרה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 עשו \u0003מעלה.\u0004","\u0003אמר רב אשי אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 שעשו חכמים מעלה, ששנינו: נאמר \"והבשר אשר יגע בכל טמא לא יאכל באש ישרף והבשר כל טהור יאכל בשר\" (ויקרא ז, יט), \u0003\"והבשר\" — לרבות את העצים\u0004 של המקדש \u0003ולבונה\u0004 של הקטורת שהם מקבלים טומאה. ויש לשאול: \u0003עצים ולבונה בני איטמויי נינהו\u0004 \u0005[קבלת טומאה הם]?!\u0006 הלוא אין טומאה חלה אלא על מאכלים ומשקאות! \u0003אלא מעלה\u0004 עשו חכמים מפני הקדושה שבהם, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בטהרת משקים עשו חכמים \u0003מעלה\u0004 בקדשים.","\u0003אלו דברים\u0004 ממיני התבואה \u0003שאדם יוצא בהן ידי חובתו\u0004 בליל ראשון של \u0003פסח\u0004 אם עשה מהם מצה: \u0003בחטים, ובשעורים, בכוסמין ובשיפון, ובשיבולת שועל. ויוצאין\u0004 חובת מצה לא רק באכילת חולין המתוקנים כראוי להם, אלא גם \u0003בדמאי\u0004 (תבואה שלא ברור אם הופרש ממנה מעשר) \u0003ובמעשר ראשון שנטלה\u0004 ממנו \u0003תרומתו\u0004 הראויה להנתן לכהן, \u0003ובמעשר שני\u0004 או \u0003הקדש שנפדו. והכהנים\u0004 יכולים לעשות מצה \u0003בחלה\u0004 (חלק העיסה הניתן לכהנים) ולצאת בה ידי חובה או \u0003בתרומה\u0004 שהרי להם היא מותרת באכילה.","\u0003אבל\u0004 אין יוצאים \u0003לא\u0004 במצה של \u0003טבל\u0004 (שלא הופרשו ממנה תרומות ומעשרות) \u0003ולא במעשר ראשון שלא נטלה\u0004 ממנו \u0003תרומתו\u0004 לכהנים, \u0003ולא במעשר שני והקדש שלא נפדו.\u0004 ועוד אמרו: \u0003חלות\u0004 מצות הנספחות לקרבן \u0003התודה\u0004 וכן \u0003רקיקי נזיר\u0004 שהן מצות שעושים עבור הנזיר, אם \u0003עשאן לעצמו\u0004 כדי להביאן עם קרבנו — \u0003אין יוצאין בהן\u0004 ידי חובת מצה, אפילו עשאן ממש לצורך זה. \u0003עשאן למכור בשוק\u0004 שיקנו ממנו הצריכים לקרבן זה חלות ורקיקי מצות — \u0003יוצאין בהן\u0004 אף חובת מצה בפסח.","תחילה מבררים את שמות הצמחים שהוזכרו במשנה. \u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003כוסמין\u0004 — \u0003מין חיטין\u0004 הם, \u0003שבולת שועל ושיפון — מין שעורין\u0004 הם. וביאור המילים שלא היו ידועות: \u0003כוסמין\u0004 הם הקרויים בארמית \u0003גולבא, שיפון\u0004 קרוי \u0003דישרא, שיבולת שועל\u0004 היא הנקראת \u0003שבילי תעלא.\u0004 מן המשנה אפשר לדייק: \u0003הני\u0004 \u0005[אלה]\u0006 המינים — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003אורז ודוחן — לא.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שאין לעשות מצה מאורז ודוחן? \u0003אמר ר' שמעון בן לקיש, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, וכן תנא\u0004 \u0005[שנה]\u0006 \u0003דבי\u0004 \u0005[שנה\u0006 החכם ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר בן יעקב: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות\u0004 לחם עוני\u0003\"\u0004 (דברים טז, ג), וכך דורשים את הכתוב: \u0003דברים הבאים לידי חימוץ — אדם יוצא בהן ידי חובתו במצה\u0004 אם שמרם מלהיות חמץ, \u0003יצאו אלו\u0004 אורז ודוחן וכיוצא בהם שגם אם עשו מהם קמח ונתנו בהן מים \u0003שאין באין לידי חימוץ אלא לידי סירחון\u0004 ואינם תופחים ומחמיצים כחמץ דגן.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' יוחנן בן נורי\u0004 ש\u0003אמר: אורז מין דגן הוא\u0004 לכל דבר, \u0003וחייבין על חימוצו כרת\u0004 שהוא כשאר מיני דגן שהחמיצו. \u0003דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוחנן בן נורי אוסר\u0004 לאכול \u0003אורז ודוחן\u0004 אם בישלם בפסח \u0003מפני שקרוב להחמיץ.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 מה משמעות הביטוי \u0003\"שקרוב להחמיץ\"?\u0004 האם הכוונה \u0003דקדים\u0004 \u0005[שהוא מקדים]\u0006 \u0003ומחמיץ\u0004 וממהר לכך אף יותר מחיטה ושעורה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 משמעו: \u0003\"קרוב להחמיץ\" — הוי\u0004 \u0005[נהיה],\u0006 אולם \u0003חמץ גמור — לא הוי\u0004 \u0005[נהיה]\u0006 כלומר אף הוא מסכים שאינו מחמיץ כשאר דגנים ואין חייבים כרת על חימוצו ואין לעשות ממנו מצה לכתחילה.","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוחנן בן נורי: אורז מין דגן הוא וחייבין על חימוצו כרת, ואדם יוצא בו ידי חובתו בפסח,\u0004 ומכאן ברור שלדעתו אורז מחמיץ לגמרי כמו שאר תבואות. ו\"קרוב להחמיץ\" שבדבריו משמעו, שהוא ממהר להחמיץ.","\u0003וכן היה ר' יוחנן בן נורי אומר: קרמית\u0004 שאף היא מין ממיני דגני הבר \u0003חייבת בחלה\u0004 כשם שיש להפריש חלה לכהן מעיסות של שאר מיני דגן. ושאלו: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003קרמית\u0004 זו? \u0003אמר אביי:\u0004 היא הצמח הקרוי \u0003שיצניתא,\u0004 אף שם זה לא היה ידוע לכל, ושאלו \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003שיצניתא\u0004 זו? \u0003אמר רב פפא: שיצניתא דמשתכחא ביני כלניתא\u0004 \u0005[השיצנית הנמצאת בין הכלניות].\u0006","\u0003אמר רבה בר בר חנה אמר ריש לקיש: עיסה שנילושה ביין ושמן ודבש — אין חייבין על חימוצה כרת,\u0004 שמשקה שאינו מים אינו גורם לבצק להיות חמץ. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אידי בר אבין ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב אידי בר אבין וקא\u0004 \u0005[והיה]\u0006 \u0003מנמנם,\u0004 ובינתיים שוחחו התלמידים ביניהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ריש לקיש\u0004 שאין חייבים על חימוצה כרת?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"לא תאכל עליו חמץ\u0004 שבעת ימים תאכל עליו מצות \u0003\",\u0004 והוא למד מהשוואה ומסמיכות זו של חמץ ומצות באופן זה: \u0003דברים שאדם יוצא בהן ידי חובתו במצה\u0004 הם אלה ש\u0003חייבין על חימוצו כרת, והא\u0004 \u0005[וזו]\u0006 \u0003הואיל ואין אדם יוצא בה ידי חובתו\u0004 במצה, \u0003דהויא ליה\u0004 \u0005[שהרי היא]\u0006 \u0003\"מצה עשירה\".\u0004 שהרי התורה קראה למצות \"לחם עוני\" ועיסה שנילושה ביין שמן ודבש אינה בגדר לחם עוני, ואין יוצאים בה חובת מצה — על כן גם \u0003אין חייבין על חימוצה כרת.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא\u0004 על שיטה זו; שנינו שאם לקח אדם דבר מאפה ו\u0003המחהו\u0004 (המיס אותו במים) \u0003וגמעו\u0004 בפסח, \u0003אם חמץ הוא — ענוש כרת, ואם מצה הוא — אין אדם יוצא ידי חובתו בפסח\u0004 שאין בגמיעה זו משום גדר אכילה ואינה נחשבת כאכילת מצה. ואם כן, \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 במקרה זה, ש\u0003אין אדם יוצא ידי חובתו במצה\u0004 זו שנמחתה, ובכל זאת \u0003חייבין על חימוצו כרת?\u0004 ואם כן הכלל שקבע רב פפא איננו נכון!","בינתיים \u0003איתער בהו\u0004 \u0005[התעורר]\u0006 \u0003רב אידי בר אבין\u0004 למשמע דבריהם, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דרדקי\u0004 \u0005[ילדים,\u0006 תינוקות\u0005]\u0006 \u0003היינו טעמא\u0004 \u0005[זהו טעמו]\u0006 של \u0003ריש לקיש משום דהוו להו\u0004 \u0005[שיש להם]\u0006 שמן ודבש הריהם \u0003מי פירות\u0004 בלבד,"],["\u0003ומי פירות אין מחמיצין\u0004 ואף שניתנים לאפיה אין עיסה הנעשית על ידיהם נחשבת כחמץ לכל דבר.","ומעתה מבארים את פרטי הדברים במשנה. שנינו ש\"אדם \u0003יוצא\u0004 ידי חובת מצה \u0003בדמאי ובמעשר\u0004 ראשון\". ותוהים: \u0003דמאי, והא\u0004 \u0005[והרי]\u0006 הוא \u0003לא חזי ליה\u0004 \u0005[ראוי לו]\u0006 לאכול, שהרי אסרו חכמים לאכול דמאי בלא תיקון (הפרשה)! ומשיבים: \u0003כיון דאי בעי מפקר לנכסיה\u0004 \u0005[שאם ירצה להפקיר את נכסיו],\u0006 \u0003הוי\u0004 \u0005[והריהו]\u0006 \u0003עני, ו\u0004הינו \u0003אוכל דמאי, השתא נמי חזי ליה\u0004 \u0005[עכשיו גם כן\u0006 שלא הפקיר \u0005ראוי לו]\u0006 לצאת בו ידי חובה בדיעבד, שאין זו אלא חובה מדברי סופרים.","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאכילין את העניים דמאי, ו\u0004כן מאכילים \u0003את אכסניא\u0004 (את החיילים הישראלים הבאים להתאכסן) ב\u0003דמאי. ואמר רב הונא: תנא\u0004 \u0005[שנינו]\u0006 \u0003בית שמאי אומרים: אין מאכילין את העניים דמאי ואת האכסניא דמאי, ובית הלל אומרים: מאכילין,\u0004 ומכאן נבין שאיסור הדמאי אינו איסור גמור כמו טבל שאין לו היתר, אלא תיקון חכמים שבמקרים מסויימים לא עמדו על שמירתו.","ועוד שנינו במשנה: ש\u0003מעשר ראשון שנטלה תרומתו\u0004 וניתנה לכהן — יוצאים בו ידי חובת מצה. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ש\u0003כיון שנטלה תרומתו חולין הוי\u0004 \u0005[הוא]\u0006 ומה החידוש שבדבר?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003שהקדימו\u0004 הלוי לכהן \u0003בשיבלים.\u0004 כי כרגיל מקבל הלוי את המעשר הראשון לאחר שנטל הכהן מן התבואה תרומה גדולה, ואילו במקרה זה הקדים הלוי את הכהן וקיבל את המעשר לפני הפרשת התרומה \u0003ונטלה הימנו\u0004 ממעשר זה \u0003תרומת מעשר\u0004 שהפריש הלוי כדי להתיר לו את המעשר באכילה, אבל \u0003לא נטלה הימנו תרומה גדולה,\u0004 והכהן יקח תרומה ממה שנשאר אחר נטילת המעשר על ידי הלוי ובכך החידוש, וכדברי \u0003ר' אבהו\u0004","ש\u0003אמר ר' אבהו אמר ר' שמעון בן לקיש: מעשר ראשון שהקדימו\u0004 הלוי \u0003בשיבלים\u0004 אף על פי שבכך צימצם את כמות התבואה שבשדה ובאופן יחסי אף את כמות התרומה גדולה שצריכה להינטל ממנה — \u0003פטור\u0004 מהפרשת \u0003תרומה גדולה\u0004 מן החלק היחסי שבו גדלה כמות המעשר ראשון על חשבון התרומה גדולה, \u0003שנאמר \"\u0004ואל הלויים תדבר ואמרת אליהם כי תקחו מאת בני ישראל את המעשר אשר נתתי לכם מאתם בנחלתכם \u0003והרמתם ממנו תרומת ה' מעשר מן המעשר\"\u0004 (במדבר יח, כו), ודורש: \u0003מעשר מן המעשר אמרתי לך\u0004 להפריש, \u0003ולא תרומה גדולה ותרומת מעשר מן המעשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אלא מעתה\u0004 אם נקבל את הוראת פסוק זה, \u0003אפילו הקדימו בכרי\u0004 כאשר כבר העמיד בעל הבית את הדגן בכרי מסודר, \u0003נמי ליפטר\u0004 \u0005[גם כן שיפטר]\u0006 מנתינת תרומה גדולה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עליך\u0004 על טענה כגון זו \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"מכל מתנתיכם תרימו את כל תרומת ה'\u0004 מכל חלבו את מקדשו ממנו\u0003\"\u0004 (במדבר יח, כט), שהלויים חייבים לתת לכהן מכל מתנותיהם שלהם.","ושואלים: \u0003ומה ראית\u0004 להעמיד את הפסוקים באופן שאם הקדים הלוי בעוד התבואה בשבלים אינו חייב בהפרשת תרומה, ואם הקדימו בכרי — חייב?! ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 שחייב — הוא משום שכבר \u0003אידגן\u0004 \u0005[נעשה דגן],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 שאינו חייב — הוא משום שעדיין \u0003לא אידגן\u0004 \u0005[נעשה דגן].\u0006 כי תבואה שסודרה בכרי קרויה כבר בלשון התורה דגן, וחובת התרומה מפורשת בתורה שהיא מן הדגן, ומשחלה חובת הפרשת התרומה, חל החיוב להקדים נתינה לכהן ואחר כך ללוי, ואם מקדים הלוי ונוטל חייב אז לתת מחלקו גם תרומה גדולה לכהן.","במשנה שנינו כי \u0003מעשר שני והקדש שנפדו\u0004 יוצאים בהם ידי חובת מצה. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הרי הם כשאר חולין! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה \u0003שנתן את הקרן\u0004 של פדיון המעשר או ההקדש, \u0003ו\u0004עדיין \u0003לא נתן את החומש,\u0004 שהפודה מעשר או הקדש צריך להוסיף חומש. \u0003וקא משמע לן\u0004 \u0005[והשמיע לנו]\u0006 בכך ש\u0003אין חומש מעכב,\u0004 שאף שיש חובה לשלם, מכל מקום כיון שנתן את הקרן, שוב אין קדושה בדבר שנפדה.","שנינו עוד כי \u0003הכהנים\u0004 יוצאים \u0003בחלה ובתרומה,\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 שכיון שהכהן רשאי לאכול חלה ותרומה מדוע לא ייצא בה ידי חובת מצה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מצה שוה לכל אדם בעינן\u0004 \u0005[צריכים אנו]\u0006 ומצה שכל ישראל אינם רשאים לאכלה אף כהנים אין יוצאים בה חובת מצה, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 מכפילות הלשון בפסוק \u0003\"מצות\" \"מצות\" ריבה\u0004 שכל מיני מצות בכלל זה, אף מצות שמותרות רק לאנשים מסויימים בלבד.","במשנה למדנו: \u0003אבל\u0004 אין אדם יוצא ידי חובת מצה \u0003בטבל.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן\u0005]\u0006 הרי טבל אסור באכילה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003בטבל טבול\u0004 (שאיסור טבל חל עליו) רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 כגון \u0003שזרעו בעציץ שאינו נקוב.\u0004 שמן התורה דבר הצומח בעציץ כזה אין בו איסור טבל, ואין חובת ההפרשה ממנו אלא מדברי סופרים, והם העמידו דבריהם שלא ייצא במצה הנעשית מטבל כזה.","שנינו עוד במשנה ש\u0003לא\u0004 יוצאים ידי חובה \u0003במעשר ראשון שלא נטלה תרומתו.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן מאליו\u0005]\u0006 הרי אסור הוא באכילה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003שהקדימו בכרי\u0004 ו\"שלא נטלה תרומתו\", הכוונה לתרומה גדולה.","\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שדין זה יהא \u0003כ\u0004מו ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי\u0004 שאף במקרה זה פטור מהפרשת תרומה, לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כדשני ליה\u0004 \u0005[כפי שתירץ לו]\u0006 שאף במקרה זה יש חיוב להפריש, וקודם הפרשה הריהו אסור באכילה.","שנינו ש\u0003לא\u0004 יוצאים ידי חובת מצה \u0003במעשר שני והקדש שלא נפדו.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהרי הם אסורים באכילה!","ומשיבים: \u0003לעולם\u0004 מדובר כאן ש\u0003נפדו, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003ש\"לא נפדו\"\u0004 — הכוונה \u0003שלא נפדו כהלכתן\u0004 כגון \u0003מעשר שני שפדאו על גב\u0004 (על ידי) \u0003אסימון. דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר\u0004 בפדיון מעשר: \"ונתת בכסף וצרת הכסף בידך והלכת אל המקום אשר יבחר ה' אלוהיך בו\" (דברים יד, כה), ודרשו חכמים: \u0003\"וצרת הכסף\"\u0004 שכסף זה צריך להיות \u0003דבר שיש לו צורה\u0004 כלומר: מטבע שיש עליה טביעה.","וכן \u0003הקדש — שחיללו\u0004 שלא כיאות \u0003על גבי\u0004 (על ידי) \u0003קרקע, דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר: \"ונתן הכסף וקם לו\"\u0004 ואם לא נתן כסף ממש אלא רק החליף (חילל) את ההקדש על קרקע — אין זה מועיל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול יוצא אדם ידי חובתו\u0004 לאכילת מצה \u0003בטבל שלא נתקן.\u0004 מתחילה מבררים את הלשון התמוהה: \"טבל שלא נתקן\", הרי \u0003כל טבל נמי\u0004 \u0005[גם כן]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא נתקן!\u0004","\u0003אלא\u0004 יש להבין כך: \u0003בטבל שלא נתקן כל צרכו.\u0004 כיצד? \u0003שנטלה ממנו תרומה גדולה\u0004 אבל \u0003לא נטלה ממנו תרומת מעשר,\u0004 או שניטל ממנו \u0003מעשר ראשון ולא\u0004 ניטל ממנו \u0003מעשר שני ואפילו\u0004 תבואה שלא ניטל ממנה \u0003מעשר עני\u0004 אף שאין בו קדושה ואינו אלא מתנה לעניים, עדיין נחשבת תבואה זו לטבל, \u0003מנין\u0004 שאיננו יוצא בטבל כזה משום מצה?","\u0003תלמוד לומר \"לא תאכל עליו חמץ\u0004 שבעת ימים תאכל עליו מצות\u0003\"\u0004 (דברים טז, ג), \u0003מי שאיסורו משום \"בל תאכל עליו חמץ\"\u0004 יוצאים בו ידי חובת מצה אם שמרוהו מחימוץ, \u0003יצא זה שאין איסורו משום \"בל תאכל חמץ\" אלא משום \"בל תאכל טבל\".\u0004 על ברייתא זו תוהים: כיצד יתכן שאין בטבל איסור משום \"בל תאכל חמץ\"?","\u0003ואיסורא\u0004 \u0005[ואיסור]\u0006 אכילת \u0003חמץ להיכן אזלא\u0004 \u0005[הלך]?\u0006 \u0003אמר רב ששת: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כ\u0006שיטת \u0005מי היא],\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: אין איסור חל על איסור,\u0004 שדבר שחל עליו איסור אחד (כגון תבואה שהיא טבל), אין איסורים נוספים יכולים לחול עליו, וממילא אין איסור חמץ חל על איסור טבל. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004"],["\u0003האוכל נבלה ביום הכפורים\u0004 בשוגג \u0003פטור\u0004 מלהביא קרבן חטאת על אכילה ביום הכיפורים, משום שאין האיסור הנוסף של אכילה ביום הכיפורים חל על איסור הנבילה, ויש בה איפוא רק איסור אחד בלבד.","\u0003רבינא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שברייתא זו היא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שאיסור חל על איסור, וכך יש להבין: \u0003מי שאיסורו משום בל תאכל חמץ בלבד\u0004 יוצא בו ידי חובת מצה, \u0003יצא זה שאין איסורו משום בל תאכל חמץ בלבד, אלא אף משום בל תאכל טבל.\u0004","הסבר זה דוחים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"בלבד\" כתיב\u0004 \u0005[כתוב]?\u0006 הלוא מלה זו העקרונית בפירוש זה, לא נאמרה בברייתא. \u0003אלא מחוורתא\u0004 \u0005[ברור כ\u0006שיטת\u0005]\u0006 \u0003רב ששת\u0004 שצריך לייחס את הברייתא לר' שמעון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול יוצא אדם ידי חובתו\u0004 בפסח \u0003במעשר שני בירושלים, תלמוד לומר \"לחם עני\"\u0004 (דברים טז, ג), והרי זה בדומה ל\"לחם אוני\", וכוונתו: \u0003מה שנאכל באנינות,\u0004 כלומר לחם כזה שמותר לאוכלו גם בזמן אבילות. מה שאין כן מעשר שני \u0003יצא זה שאינו נאכל באנינות\u0004 (כאמור בתורה \"לא אכלתי באוני ממנו\", דברים כו, יד) \u0003אלא בשמחה,\u0004 אלו \u0003דברי ר' יוסי הגלילי.\u0004","\u0003ר' עקיבא אומר:\u0004 מתוך שנאמר \u0003\"מצות\" \"מצות\" ריבה\u0004 הכתוב, ללמד שכל מיני מצות מותרים בפסח. ושואלים: \u0003אם כן,\u0004 לשיטה זו \u0003מה תלמוד לומר\u0004 מה מלמדת ההדגשה \u0003\"לחם עני\"?\u0004 ומשיבים: \u0003פרט לעיסה שנילושה ביין, שמן, ודבש,\u0004 שאיננה מאכל עניים, ולכן אינה ראויה למצה של מצוה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא?\u0004 ומשיבים שהוא אומר: \u0003מי כתיב\u0004 \u0005[האם כתוב]\u0006 \u0003\"לחם עוני\"\u0004 שנלמד מכאן ענין אנינות? \u0003\"עני\" כתיב\u0004 \u0005[כתוב],\u0006 וכוונתו — לחם הראוי לעני.","\u0003ור' יוסי הגלילי\u0004 אומר בתשובה לכך: \u0003מי קרינן\u0004 \u0005[האם קוראים אנו]\u0006 \u0003\"עני\",\u0004 הלוא אין זו דרך הקריאה של פסוק זה! \u0003\"עוני\" קרינן\u0004 \u0005[קוראים אנו]\u0006 לרמז: דחק, צרות, וצער. \u0003ור' עקיבא\u0004 אומר בתשובה לכך: \u0003האי דקרינן ביה\u0004 \u0005[זה שאנו קוראים בו]\u0006 \u0003\"עוני\",\u0004 יש להבינו \u0003כ\u0004דברי \u0003שמואל.\u0004 ש\u0003אמר שמואל: \"לחם עני\"\u0004 משמעו: \u0003לחם שעונין\u0004 (אומרים) \u0003עליו דברים הרבה\u0004 — רמז לאמירת הגדה של פסח.","לעצם שיטת ר' עקיבא שואלים: \u0003ו\u0004כי \u0003סבר ר' עקיבא עיסה שנילושה ביין, שמן, ודבש לא\u0004 יוצאים בה ידי חובת מצה בפסח? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין לשין עיסה בפסח ביין ושמן ודבש. ואם לש, רבן גמליאל אומר: תשרף מיד\u0004 שהיא ממהרת להחמיץ, \u0003וחכמים אומרים\u0004 שאף שממהרת להחמיץ ניתן לשומרה מחימוץ, ולכן \u0003יאכל. ואמר ר' עקיבא: שבתי היתה\u0004 כלומר יום שבו היה תורו לשמש את רבותיו היתה שבת שבפסח (ריבב\"ן) \u0003אצל ר' אליעזר ור' יהושע, ולשתי להם עיסה ביין ושמן ודבש, ולא אמרו לי דבר.\u0004","\u0003ואף על פי שאין לשין\u0004 עיסה ביין ושמן ודבש, \u0003מקטפין בו\u0004 (מורחים אותם על העיסה מלמעלה). ומעירים: במשפט זה \u0003אתאן לתנא קמא\u0004 \u0005[באנו ל\u0006שיטת \u0005התנא הראשון]\u0006 שאסר ללוש באלה, ולדבריו מתייחסת התוספת שמותר בכל זאת לקטף. \u0003וחכמים אומרים: את שלשין בו — מקטפין בו, ואת שאין לשין בו — אין מקטפין בו. ושוין\u0004 כולם בדעתם \u0003שאין לשין את העיסה\u0004 במים \u0003פושרין,\u0004 שהיא ממהרת ביותר להחמיץ. בכל אופן נלמד מכאן שר' עקיבא עצמו עשה מצות מיין ושמן ודבש!","ודוחים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' עקיבא שאין יוצאין במצה כזו — מדובר \u0003ביום טוב ראשון,\u0004 שיש מצות עשה מיוחדת של אכילת מצה, ולא רק חובה להמנע מחמץ. \u0003הא\u0004 \u0005[זו]\u0006 שעשה את העיסה בשמן יין ודבש — מדובר \u0003ביום טוב שני\u0004 של פסח, כאשר אין חיוב אכילת מצה אלא רק ציווי להימנע מאכילת חמץ, ומצה עשירה אינה חמץ.","\u0003כ\u0004מו ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יהושע לבניה\u0004 \u0005[לבניו]:\u0006 בליל \u0003יומא קמא\u0004 \u0005[יום ראשון]\u0006 של פסח \u0003לא תלושו לי\u0004 עיסה \u0003בחלבא\u0004 \u0005[בחלב],\u0006 \u0003מכאן ואילך לושו לי בחלבא\u0004 \u0005[בחלב].\u0006 ומקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 בכל ימות השנה \u0003אין לשין את העיסה בחלב, ואם לש — כל הפת אסורה. מפני הרגל עבירה;\u0004 שמא יבוא לאכול פת זו עם בשר. \u0003אלא\u0004 יש להבין כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 בליל \u0003יומא קמא\u0004 \u0005[יום ראשון]\u0006 של פסח \u0003לא תלושו לי בדובשא\u0004 \u0005[בדבש],\u0006 \u0003מכאן ואילך לושו לי בדובשא\u0004 \u0005[בדבש].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 אפשרות נוספת: \u0003לעולם בחלבא\u0004 \u0005[בחלב]\u0006 אמר, אלא \u0003כ\u0004פי ש\u0003אמר רבינא:\u0004 בצורה של \u0003כעין תורא\u0004 \u0005[השור] —\u0006 \u0003שרי\u0004 \u0005[מותר].\u0006 שאם עושה עיסה בצורת עיגול קטן מיוחדת כעינו של השור — מותר, שמבחינים שאין זה לחם רגיל — ומותר ללושו אף בחלב, שכן לא יבואו לטעות בו. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר שאמר להם לעשות בשינוי \u0003כעין תורא\u0004 \u0005[השור].\u0006","דרך אגב הוזכרה בברייתא הקודמת: \u0003ושוין (הכל מסכימים) שאין לשין את העיסה בפושרין,\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003ממנחות, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל המנחות נילושות בפושרין ומשתמרין שלא יחמצו.\u0004 ומשיבים; יש לחלק: \u0003אם אמרו\u0004 שמותר לאפות בפושרים \u0003בזריזין\u0004 (בכהנים), \u0003יאמרו בשאין זריזין?\u0004 שהכהנים זריזים ובקיאים בעבודת הקודש ויזהרו מאד, ולא כל אדם יכול לעשות כן בלא להיכשל.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שסומכים על זריזות הכהנים, \u0003מילתת נמי לתית\u0004 \u0005[שאף ילתתו אותם]\u0006 שישרו את החיטין במים כדי לסייע בקילוף קליפתן! \u0003אלמה\u0004 \u0005[מפני מה]\u0006 \u0003אמר ר' זירא אמר רבה בר ירמיה אמר שמואל: חטין של מנחות אין לותתין אותה!\u0004 ומשיבים: \u0003לישה בזריזין איתא\u0004 \u0005[ישנה]\u0006 כי לישת המנחות נעשית על ידי כהנים, אולם \u0003לתיתה ליתא\u0004 \u0005[לא נעשית]\u0006 \u0003בזריזין\u0004 שאין לותתים וטוחנים את חיטי המנחות במקדש עצמו אלא מחוץ לו על ידי זרים, ועליהם אין לסמוך.","ושואלים: \u0003ולישה\u0004 עצמה \u0003מי איתא\u0004 \u0005[האם ישנה]\u0006 \u0003בזריזין\u0004 דוקא? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \"ונפש כי תקריב קרבן מנחה לה' סולת יהיה קרבנו \u0003ויצק עליה שמן\u0004 ונתן עליה לבונה \u0003והביאה אל בני אהרן הכהנים וקמץ\u0004 משם מלא קומצו מסלתה ומשמנה על כל לבונתה\" (ויקרא ב, א-ב), ומלשון הכתוב נלמד כי \u0003מקמיצה ואילך מצוות כהונה, לימד על יציקה ובלילה שכשירה בכל אדם\u0004 והיא עצמה באה אחרי לישה!","ומשיבים: \u0003לישה, נהי\u0004 \u0005[אף על פי]\u0006 ש\u0003בזריזין ליתא\u0004 \u0005[איננה],\u0006 \u0003במקום זריזים איתא\u0004 \u0005[ישנה],\u0006 כלומר אף אם היא נעשית על ידי זר, מכל מקום היא נעשית במקדש עצמו. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בלילה כשירה בזר,\u0004 אולם אם עשאוה \u0003חוץ לחומת העזרה, פסולה. לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003לתיתה,\u0004 ש\u0003אינה בזריזין,\u0004 ואף \u0003לא במקום זריזין.\u0004","ושואלים עוד: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003ממנחת העומר\u0004 שאף בה יש להיזהר מן החמץ? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003מנחת העומר לותתין אותה וצוברין אותה\u0004 ואין חוששים שמא תחמיץ! ומשיבים: דבר הנעשה ב\u0003ציבור שאני\u0004 \u0005[שונה],\u0006 שיש בית דין הממונה על כך, וודאי נזהרים בו זהירות יתירה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: \u0003יכול יוצא אדם ידי חובתו ב\u0004מצה על ידי חיטים של \u0003בכורים? תלמוד לומר \"בכל מושבתיכם תאכלו מצות\"\u0004 (שמות יב, כ), ונלמד מכאן: \u0003מצה הנאכלת בכל מושבותיכם\u0004 היא שיוצאים בה, \u0003יצאו\u0004 מכלל זה \u0003בכורים שאין נאכלים בכל מושבותיכם אלא בירושלים\u0004 בלבד, אלו \u0003דברי ר' יוסי הגלילי.\u0004","\u0003ר' עקיבא אומר:\u0004 לא זה הטעם, אלא \u0003מצה ומרור,\u0004 שלמדים הלכה זו בדרך היקש, שהכתוב השוה מצה ומרור; \u0003מה מרור שאינו בכורים,\u0004 שאין מביאים ביכורים אלא משבעת המינים ואין מרור בכללם, \u0003אף מצה\u0004 דווקא זו \u0003שאינה בכורים. אי\u0004 \u0005[או]\u0006 שמא תבוא לטעון: \u0003מה מרור שאין במינו בכורים — אף מצה\u0004 יצטרך למצוא מין מצה \u0003שאין במינה בכורים\u0004 (כגון כוסמת)!"],["\u0003אוציא חיטין ושעורין שיש במינן ביכורים\u0004 ולא יעשו מהם מצות. \u0003תלמוד לומר: \"מצות מצות\" ריבה\u0004 — שאפשר לצאת בכל דבר הקרוי מצה. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 אמנם \u0003\"מצות מצות\" ריבה\u0004 הכתוב, אם כן, \u0003אפילו\u0004 מצות שנעשו מחיטי \u0003ביכורים נמי\u0004 \u0005[גם כן]\u0006 בכלל זה! ומשיבים: אמנם כן הוא, ו\u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003ר' עקיבא\u0004 מדבריו ואף הוא לומד מן הכתוב \"בכל מושבותיכם\".","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003יכול יצא אדם ידי חובתו\u0004 במצת \u0003ביכורים — תלמוד לומר \"בכל מושבתיכם תאכלו מצות\"\u0004 משמעו: \u0003מצה הנאכלת בכל מושבות\u0004 יוצאים בה, ו\u0003יצאו ביכורים שאינן נאכלין בכל מושבות אלא בירושלים\u0004 בלבד. \u0003יכול שאני מוציא אף מעשר שני\u0004 מכלל הראוי למצה \u0003תלמוד לומר: \"מצות מצות\" ריבה.\u0004","ושואלים: \u0003ומה ראית לרבות מעשר שני\u0004 מלשון \"מצות מצות\" \u0003ולהוציא ביכורים?\u0004 ומשיבים: \u0003מרבה אני מעשר שני שיש לו\u0004 באופן כלשהו \u0003היתר בכל מושבות,\u0004 כדברי \u0003ר' אליעזר\u0004 המובאים להלן \u0003ומוציא אני ביכורים שאין להן\u0004 כלל \u0003היתר בכל מושבות.\u0004","ש\u0003אמר ר' אליעזר: מנין למעשר שני שנטמא שפודין אותו אפילו\u0004 היה \u0003בירושלים,\u0004 וכיון שנפדה מותר איפוא להוציאו משם, \u0003תלמוד לומר\u0004 שנאמר במקרא \"וכי ירבה ממך הדרך \u0003כי לא תוכל שאתו\u0004 כי ירחק ממך המקום אשר יבחר ה' אלהיך לשום שמו שם כי יברכך ה' אלהיך\" (דברים יד, כד),","ולמדנו בגזירה שוה ש\u0003אין \"שאת\" אלא אכילה — שנאמר \"וישא משאת מאת פניו\"\u0004 (בראשית מג, לד), והוא מפרש איפוא \"לא תוכל שאתו\" — לא תוכל לאכלו, שמעשר שנטמא ואי אפשר לאכלו אף הוא יש לו תקנה על ידי פדיון כמעשר המצוי במקום רחוק, ואם כן נמצא שיש תקנה למעשר שני שייאכל בכל מושבות ישראל.","ולענייננו: את \u0003מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר במעשר שני נפיק ביה\u0004 \u0005[יוצא בו]\u0006 ידי מצה? \u0003ר' עקיבא\u0004 הוא, ובכל זאת \u0003קממעיט להו\u0004 \u0005[הוא ממעט אותם]\u0006 את ה\u0003ביכורים\u0004 ממה שנאמר \u0003\"בכל מושבתיכם\", שמע מינה הדר ביה\u0004 \u0005[נלמד מכאן\u0006 ש\u0005חזר בו]\u0006 ואף הוא לומד הלכה זו כדרך שלמד אותה ר' יוסי הגלילי.","ושואלים: \u0003ור' יוסי הגלילי\u0004 מדוע למד הוא מ\"בכל מושבותיכם\"? \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו מאותו כתוב ראשון — \u0003\"לחם עני\"\u0004 שהוא לומד ממנו שמצה נעשית רק ממה \u0003שנאכל\u0004 אף \u0003באוני, יצא זה\u0004 המעשר \u0003שאין נאכל אלא בשמחה,\u0004 ומדוע לא ילמד מכך אף ביכורים שאף הם אינם נאכלים אלא בשמחה!","ומשיבים: \u0003סבר ליה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' שמעון\u0004 הסבור שאכילת ביכורים מותרת אף לאונן. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005למדנו\u0006 בברייתא\u0005]:\u0006 \u0003ביכורים אסורין לאונן\u0004 (מי שמת לו מת בו ביום), \u0003ור' שמעון מתיר.\u0004","ומסבירים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא תוכל לאכל בשעריך\u0004 מעשר דגנך ותירושך ויצהרך ובכורות בקרך וצאנך וכל נדריך אשר תדור ונדבותיך ותרומת ידך\u0003\"\u0004 (דברים יב, יז), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"תרומת ידך\" — אלו ביכורים,\u0004 ונמצא \u0003דאיתקש\u0004 \u0005[שהושווה]\u0006 ענין \u0003ביכורים למעשר,\u0004 וכך נלמד: \u0003מה מעשר אסור לאונן\u0004 כמפורש בתורה — \u0003אף ביכורים אסור לאונן.\u0004","\u0003ור' שמעון\u0004 אומר: ביכורים \u0003תרומה קרינהו רחמנא\u0004 \u0005[קרא אותם המקרא]\u0006 ולכן דינם \u0003כתרומה; מה תרומה מותרת לאונן — אף ביכורים מותר לאונן.\u0004","ושואלים: \u0003ור' שמעון נהי דהיקיש לית ליה\u0004 \u0005[אם אמנם שהיקש אין לו]\u0006 ואינו לומד מהיקש לענין זה, אבל \u0003שמחה מיהא מיכתב כתיבא בהו\u0004 \u0005[על כל פנים כתובה בהם]\u0006 בביכורים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בהם \u0003\"ושמחת בכל הטוב\u0004 אשר נתן לך ה' אלהיך ולביתך\u0003\"\u0004 (דברים כו, יא)?","ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 מקרא לא לצוות שיהיו הביכורים נאכלים במצב של שמחה אלא \u0003לזמן שמחה הוא דאתא\u0004 \u0005[שבא]\u0006 ללמדנו, שזמן הבאת ביכורים הוא בזמני השמחה, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 מזמן \u0003העצרת\u0004 (חג השבועות) \u0003ועד החג\u0004 (סוכות) — \u0003מביא\u0004 ביכורים \u0003וקורא\u0004 את הקריאה הכתובה לכך בתורה, שזמן זה הוא זמן שמחה עת קציר ובציר, \u0003מהחג ועד חנוכה\u0004 אמנם \u0003מביא\u0004 ביכורים \u0003ו\u0004אולם \u0003אינו קורא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"לחם עני\" — פרט לחלוט,\u0004 לחם שלאחר אפייה חזר ונתבשל במים חמים ויש בו חשיבות, \u0003ולאשישה\u0004 (עוגה גדולה ויפה). \u0003יכול לא יצא אדם ידי חובתו\u0004 באכילת מצה \u0003אלא בפת הדראה\u0004 (פת קיבר, מקמח גס) \u0003תלמוד לומר \"מצות מצות\" — ריבה, ואפילו כמצות של שלמה\u0004 המלך מסולת נקיה, \u0003אם כן מה תלמוד לומר \"לחם עני\"\u0004 — לא להוציא פת נקיה אלא \u0003פרט לחלוט ולאשישה.\u0004","ושואלים: \u0003ומאי משמע דהאי\u0004 \u0005[ומה משמעות שזו]\u0006 \u0003אשישה לישנא דחשיבותא\u0004 \u0005[לשון חשיבות\u0006 היא] \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדוד כשהעלה את הארון \u0003\"ויחלק לכל העם לכל המון ישראל למאיש ועד אשה לאיש חלת לחם אחת ואשפר אחד ואשישה אחת\u0004 וילך כל העם איש לביתו\u0003\"\u0004 (שמואל ב' ו, יט),","\u0003ואמר רב חנן בר אבא: \"אשפר\"\u0004 — שנתן לכל אחד מנת בשר כדי \u0003אחד מששה בפר,\u0004 ו\u0003\"אשישה\"\u0004 — שנתן להם עוגה שכמותה \u0003אחד מששה באיפה.\u0004 ומעירים כי ביאור זה \u0003פליגא\u0004 \u0005[חלוק]\u0006 על פירושו של \u0003שמואל,\u0004 ש\u0003אמר שמואל: \"אשישה\"\u0004 שבפסוק זה כוונתו — \u0003גרבא דחמרא\u0004 \u0005[כד יין],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במפורש: \u0003\"ואהבי אשישי ענבים\"\u0004 (הושע ג, א).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין אופין פת עבה ביום טוב בפסח\u0004 שמפני עוביה עלולה להחמיץ, אלו \u0003דברי בית שמאי,\u0004"],["\u0003ובית הלל מתירין.\u0004 ושאלו: \u0003וכמה\u0004 היא \u0003פת עבה? אמר רב הונא:\u0004 פת שעוביה \u0003טפח, שכן מצינו\u0004 אף \u0003בלחם הפנים\u0004 שאסור שיהא חמץ ובכל זאת עוביו \u0003טפח.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על השוואה זו \u0003רב יוסף: אם אמרו\u0004 להתיר שיעור זה זהו דווקא בלחם הפנים שנעשה בדרך מיוחדת, \u0003ב\u0004כהנים \u0003זריזין\u0004 הנשמרים מחשש חימוץ — \u0003יאמרו ב\u0004שאר אנשים \u0003שאינן זריזין? אם אמרו בפת עמילה\u0004 שעיסתה נילושה היטב מתחילה — \u0003יאמרו בפת שאינו עמילה?\u0004","\u0003אם אמרו\u0004 במאפה שבמקדש שמסיקים בו \u0003בעצים יבשין\u0004 שהובאו למקדש בימות הקיץ וממהרים לבעור, וחומם מרובה, ואין הפת שוהה בתנור כדי שתחמיץ בו — \u0003יאמרו\u0004 בכל אדם שמסיקים \u0003בעצים לחים? אם אמרו בתנור חם\u0004 שבמקדש — \u0003יאמרו בתנור צונן? אם אמרו\u0004 בלחם הפנים שנאפה \u0003בתנור של מתכת\u0004 שמתחמם מהר — \u0003יאמרו בתנור של חרס?\u0004 ואם כן אין ראיה כלל מלחם הפנים לסתם מצה.","\u0003אמר ר' ירמיה בר אבא: שאילית\u0004 \u0005[שאלתי]\u0006 \u0003את רבי ביחוד\u0004 \u0005[המיוחד]\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 \u0003רב. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שבלשון זו אמרו: \u0003רב ירמיה בר אבא אמר רב: שאילית\u0004 \u0005[שאלתי]\u0006 \u0003את רבי ביחוד\u0004 (המיוחד), \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 \u0003רבינו הקדוש\u0004 (ר' יהודה הנשיא) \u0003מאי\u0004 \u0005[מה היא]\u0006 \u0003פת עבה?\u0004 אמר לו: \u0003פת מרובה,\u0004 כלומר, כמות גדולה של בצק בבת אחת. \u0003ואמאי קרו ליה\u0004 \u0005[ומדוע קוראים לה]\u0006 \u0003פת עבה — משום דנפישא\u0004 \u0005[ש\u0006היא \u0005מרובה]\u0006 \u0003בלישה\u0004 והעיסה נראית עבה. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003באתריה דהאי תנא\u0004 \u0005[במקומו של תנא זה]\u0006 \u0003לפת מרובה — פת עבה קרו ליה\u0004 \u0005[קראו לה].\u0006","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 איסור זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דקא טרח טירחא\u0004 \u0005[שהוא טרח טירחה]\u0006 ש\u0003לא צריך\u0004 לה, שהוא לש בבת אחת כמות מרובה ומתיגע בכך הרבה ואין זה נאה לעבוד עבודה מרובה ובלתי נחוצה בחג, אם כך \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 ששנה הלכה זו \u0003בפסח\u0004 דוקא? \u0003אפילו ביום טוב\u0004 אחר \u0003נמי\u0004 \u0005[גם כן]\u0006 יהא אותו הדין!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 הדין שבכל יום טוב אסור, \u0003והאי תנא\u0004 \u0005[ותנא זה]\u0006 \u0003ביום טוב של פסח קאי\u0004 \u0005[היה עומד]\u0006 ודן בהלכותיו, והזכיר אגב כך הלכה זו שאינה מיוחדת אך ורק לחג הפסח. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003בית שמאי אומרים: אין אופין פת עבה ביום טוב, ובית הלל מתירין.\u0004","עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יוצאין\u0004 חובת מצה \u0003בפת נקיה, ו\u0004אף \u0003בהדראה\u0004 (פת קיבר), \u0003ו\u0004בדיעבד אף \u0003בסריקין המצויירין\u0004 (במצות שיש עליהן תבנית ציור) \u0003בפסח, אף על פי שאמרו\u0004 שלכתחילה \u0003אין עושין סריקין המצויירין בפסח. אמר רב יהודה: דבר זה שאל בייתוס בן זונין לחכמים: מפני מה אמרו אין עושין סריקין המצויירין בפסח? אמרו לו: מפני שהאשה שוהה עליה\u0004 לעשות את הציור על גבי המצה לפני אפייתה \u0003ומחמצתה\u0004 בינתיים.","\u0003אמר להם: אפשר יעשנה\u0004 את המצה הזו \u0003בדפוס ויקבענה כיון\u0004 \u0005[מיד]\u0006 ולא יצטרך לשהות בציור! \u0003אמרו לו:\u0004 אם כן נצטרך לחלק בהלכה ש\u0003יאמרו כל הסריקין\u0004 המצוירים — \u0003אסורין,\u0004 אבל \u0003סריקי בייתוס\u0004 שנקבעו בדפוס — \u0003מותרין,\u0004 ולא חילקו חכמים בגזירתם.","\u0003אמר ר' אלעזר בר צדוק: פעם אחת נכנסתי אחר אבא\u0004 צדוק \u0003לבית רבן גמליאל, והביאו לפניו סריקין המצויירין בפסח. אמרתי: אבא,\u0004 וכי \u0003לא כך אמרו חכמים אין עושין סריקין המצויירין בפסח? אמר לי: בני, לא של כל אדם אמרו, אלא של נחתומין אמרו,\u0004 שכיון שהם צריכים למכור את המצות הם מרבים ליפותן, ושמא יחמיצו בתוך כך.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003לא של נחתומין אמרו\u0004 שהם בקיאין וזריזין במלאכתם, \u0003אלא של כל אדם,\u0004 ועל כל פנים בדיעבד אפשר להשתמש במצות אלה. \u0003אמר ר' יוסי: עושין סריקין\u0004 מצויירים \u0003כמין רקיקין\u0004 דקים, \u0003ואין עושין סריקין כמין גלוסקאות\u0004 (עוגיות עבות) שחשש חימוץ מרובה בהן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הסופגנין\u0004 (עוגות העשויות מבצק שנעשה כספוג) \u0003והדובשנין\u0004 (עוגות האפויות בדבש) \u0003ואיסקריטין\u0004 (עוגות רכות ומתובלות) \u0003וחלת המסרת\u0004 (חלה שמטגנין במחבת) \u0003והמדומע\u0004 כלומר, חולין שנתערב בהם משהו של תרומה — כל אלה \u0003פטורים מן החלה.\u0004 מתחילה מבררים את פירוש המילים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003חלת המסרת? אמר ר' יהושע בן לוי: זה חלוט\u0004 (דבר מבושל) שעושין \u0003בעלי בתים\u0004 בצק במחבת עמוקה ואופים אותו כך.","\u0003אמר ריש לקיש: הללו מעשה אילפס הן\u0004 ומה שאינו נעשה בתנור אלא באילפס הוא בישול ולא אפיה ואינו קרוי לחם, ולכן אינו חייב בחלה. \u0003ור' יוחנן אמר:\u0004 אף \u0003מעשה אילפס חייבין\u0004 בהפרשת חלה. \u0003והללו\u0004 (חלת המסרת ועוד) שנפטרו מפני \u0003שעשאן בחמה.\u0004 ולא אפאן באש שאינן קרויות לחם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת ר' שמעון בן לקיש, שנינו: \u0003הסופגנין והדובשנין והאיסקריטין,\u0004 אם \u0003עשאן באילפס — חייבין\u0004 בחלה, ואם עשאן \u0003בחמה — פטורין,\u0004 הרי זו \u0003תיובתיה\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003ר' שמעון בן לקיש! אמר עולא: אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' שמעון בן לקיש\u0004 ש\u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003שהרתיח\u0004 את האילפס באש \u0003ולבסוף הדביק\u0004 בצידי האילפס את מיני המאפה, שדרך אפיה זו היא בדיוק כמאפה תנור ולכן חייבים בחלה.","ושואלים: \u0003אבל אם הדביק ולבסוף הרתיח, מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 שהם \u0003פטורין,\u0004 אם כן \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא: \u0003עשאן בחמה פטורין,\u0004 מדוע לא \u0003ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בה עצמה\u0006 בתוך אותה הלכה\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שעשאן באילפס חייבין \u0003כגון שהרתיח ולבסוף הדביק, אבל הדביק ולבסוף הרתיח — פטורין,\u0004 ומדוע לא השתמש בדוגמה קרובה זו?","ומשיבים: \u0003חסורי מחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא, \u0005וכך יש לשנותה]:\u0006 \u0003במה דברים אמורים שהרתיח ולבסוף הדביק אבל הדביק ולבסוף הרתיח\u0004 — הרי \u0003נעשה כמי שעשאן בחמה ופטורין.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה לענין זה. שנינו: \u0003יוצאין במצה הינא\u0004 (שאינה אפויה כל צורכה) וכן ב\u0003מצה העשויה באילפס.\u0004 הרי שדבר העשוי באילפס, נחשב ללחם! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003שהרתיח\u0004 את האילפס כמו שמרתיחים תנור, \u0003ולבסוף הדביק.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003מצה הינא? אמר רב יהודה אמר שמואל: כל\u0004 מצה \u0003שפורסה\u0004 כשהיא רכה ועם זאת \u0003אין חוטין נמשכין הימנה\u0004 ששוב אינה כבצק. \u0003אמר רבא: וכן\u0004 לענין \u0003לחמי תודה,\u0004 אם נאפו עד לשיעור זה הרי הם כשרים. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי \u0003הכא\u0004 \u0005[כאן]\u0006 לענין מצה \u0003\"לחם\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003והכא\u0004 \u0005[כאן]\u0006 בענין תודה \"לחם\" \u0003כתיב\u0004 \u0005[נאמר],\u0006 ואם דבר נחשב לחם לענין אחד דינו כלחם לכל ענין!","ודוחים: יש בכך משום חידוש, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 בתודה \u0003\"והקריב ממנו\u0004"],["\u0003אחד מכל קרבן\u0004 תרומה לה' לכהן הזורק את דם השלמים לו יהיה\u0003\"\u0004 (ויקרא ז, יד), \u0003\"אחד\"\u0004 משמעו שלם \u0003שלא יטול פרוס. והכא\u0004 \u0005[וכאן]\u0006 כיון שאין הלחם עשוי כתיקונו — \u0003כמאן דפריסא דמיא\u0004 \u0005[כמי שהוא פרוס נחשב],\u0006 שהרי אינו מוצק כראוי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת הוא קרוי לחם.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 שנינו \u0003המעיסה\u0004 (בצק שחלטו אותו במים), \u0003בית שמאי פוטרין\u0004 מלהפריש ממנה חלה \u0003ובית הלל מחייבין.\u0004 ו\u0003החליטה, בית שמאי מחייבין\u0004 בחלה, \u0003ובית הלל פוטרין.\u0004 ושואלים: \u0003איזהו המעיסה ואיזהו החליטה? המעיסה\u0004 נוצרת כאשר שמים \u0003קמח שעל גבי מוגלשין\u0004 (מים רותחים), \u0003החליטה\u0004 — על ידי \u0003מוגלשין שעל גבי קמח.\u0004","\u0003ר' ישמעאל בר' יוסי אומר משום אביו: זה וזה לפטור, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר: \u0003זה וזה לחיוב, וחכמים אומרים: אחד זה ואחד זה\u0004 אם \u0003עשאן באילפס — פטור,\u0004 ואם עשאן \u0003בתנור — חייב.\u0004","ושואלים: \u0003ותנא קמא\u0004 אשר שנה כי יש מחלוקת בין בית שמאי ובית הלל בענין זה \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003המעיסה ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003החליטה\u0004 שבאחת מהן בית הלל פוטרין ובאחרת מחייבים? \u0003אמר רב יהודה אמר שמואל וכן אמר ר' יהודה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 בשם \u0003ר' יהושע בן לוי: כמחלוקת בזו כך מחלוקת בזו\u0004 ובית הלל הקלו או החמירו בשוה בשני המקרים, \u0003ותברא\u0004 \u0005[ושבורה]\u0006 ראשיתה של ברייתא זו והיא צירוף של שני מקורות, ואין ליחס את שני הקטעים לחכם אחד \u0003מי ששנה זו לא שנה זו.\u0004","ולענייננו, \u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 כי \u0003חכמים אומרים אחד זה ואחד זה שעשאן באילפס — פטור\u0004 מחלה, ואם עשאן \u0003בתנור — חייב,\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' יוחנן\u0004 המחייב מעשה אילפס בחלה. ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' יוחנן:\u0004 דבר זה \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהא מעיסה וחלוטה חייבין בחלה — תלמוד לומר \"לחם\",\u0004","\u0003ר' יהודה אומר: אין לחם אלא האפוי בתנור.\u0004 לכאורה שיטת \u0003ר' יהודה היינו\u0004 \u0005[הרי היא]\u0006 שיטת \u0003תנא קמא! אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003מעשה אילפס איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 שבו נחלקו\u0005],\u0006 \u0003תנא קמא סבר: מעשה אילפס חייבין\u0004 בניגוד למעיסה וחליטה, \u0003ור' יהודה סבר: מעשה אילפס פטורין\u0004 כדין מעיסה וחליטה, שאין לחם אלא האפוי בתנור ממש.","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מעשה אילפס פטורין\u0004 מחלה, \u0003והכא\u0004 \u0005[וכאן]\u0006 מדובר \u0003כגון שחזר ואפאו בתנור,\u0004 ובזה \u0003קא מיפלגי\u0004 \u0005[נחלקו].\u0006 \u0003דתנא קמא\u0004 \u0005[שהתנא הראשון]\u0006 \u0003סבר: כיון שחזר ואפאו בתנור\u0004 — \u0003לחם קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 וחייב בחלה, \u0003ור' יהודה סבר, אין לחם אלא האפוי בתנור מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003וכיון דמעיקרא לאו\u0004 \u0005[שמתחילה לא]\u0006 \u0003בתנור אפייה\u0004 \u0005[אפאו],\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לחם הוא,\u0004","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ואפו עשר נשים לחמכם בתנור אחד\"\u0004 (ויקרא כו, כו), ובדרך אגב נלמד מכאן: \u0003לחם האפוי בתנור אחד — קרוי לחם, ושאין אפוי בתנור אחד\u0004 אלא בכלים שונים — \u0003אין קרוי לחם.\u0004","\u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003רבה ורב יוסף אחוריה\u0004 \u0005[אחרי]\u0006 \u0003ר' זירא, ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' זירא קמיה\u0004 \u0005[לפני]\u0006 \u0003עולא\u0004 לשמוע תורה מפיו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לר' זירא: בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003מעולא: הדביק\u0004 פת \u0003מבפנים\u0004 בתוך אילפס \u0003והרתיח מבחוץ מהו\u0004 לענין חיוב חלה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אימא ליה\u0004 \u0005[מה,\u0006 למה, \u0005אומר\u0006 אשאל \u0005לו]\u0006 לעולא דבר זה? \u0003דאי אמינא ליה\u0004 \u0005[שאם אומר לו\u0006 שאלה זו\u0005]\u0006 \u0003אמר\u0004 \u0005[יאמר]\u0006 \u0003לי: הי ניהו\u0004 \u0005[מה הם]\u0006 \u0003מעשה אילפס?\u0004 הלוא אלה הם, וידועה המחלוקת בהם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לר' זירא: בעו מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003מעולא:\u0004 אם \u0003הדביק\u0004 פת \u0003מבפנים\u0004 בתוך האילפס \u0003ואבוקה\u0004 בוערת \u0003כנגדו מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אימא ליה\u0004 \u0005[מה,\u0006 למה, \u0005אומר\u0006 אשאל \u0005לו]\u0006 \u0003דאי אמינא ליה\u0004 \u0005[שאם אומר לו]\u0006 \u0003אמר לי: רוב עניים עושין כן\u0004 מעשה אילפס שלהם, ואף זה בכלל מעשה אילפס.","\u0003אמר רב אסי: עיסה של מעשר שני לדברי ר' מאיר\u0004 — הסבור שמעשר שני דינו כדין הקדש, ואף שניתן לבעלים להשתמש בו, מכל מקום אין הוא נחשב כרכושם — הריהי כעיסה של הקדש ש\u0003פטורה מן החלה, לדברי חכמים\u0004 הסבורים שממון הדיוט הוא — \u0003חייבת בחלה.\u0004"]]};
